    pub fn update_company_model_budget(
        &self,
        input: UpdateCompanyModelBudgetInput,
    ) -> AppResult<CompanyModelBudgetView> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        if !(1..=1_000_000_000_000).contains(&input.daily_model_cost_budget_microusd) {
            return Err(AppError::Validation(
                "company daily_model_cost_budget_microusd must be between 1 and 1000000000000"
                    .into(),
            ));
        }
        let now = now_utc();
        let existing = self.repo.get_company_model_budget_policy(input.company_id);
        let policy = CompanyModelBudgetPolicy {
            company_id: input.company_id,
            daily_model_cost_budget_microusd: input.daily_model_cost_budget_microusd,
            configured: true,
            created_by_human_user_id: existing
                .as_ref()
                .and_then(|policy| policy.created_by_human_user_id)
                .or(Some(input.human_user_id)),
            updated_by_human_user_id: Some(input.human_user_id),
            created_at: existing
                .as_ref()
                .and_then(|policy| policy.created_at)
                .or(Some(now)),
            updated_at: Some(now),
        };
        self.repo.save_company_model_budget_policy(policy)?;
        self.get_company_model_budget_for_human(input.human_user_id, input.company_id)
    }

