    pub fn update_company_runtime_policy(
        &self,
        input: UpdateCompanyRuntimePolicyInput,
    ) -> AppResult<CompanyRuntimePolicy> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        if let Some(template_id) = input.default_runtime_template_id {
            let template = self
                .repo
                .get_agent_runtime_template(template_id)
                .filter(|template| template.company_id == input.company_id)
                .ok_or_else(|| AppError::NotFound("agent runtime template not found".into()))?;
            if template.status != AGENT_RUNTIME_TEMPLATE_STATUS_ACTIVE {
                return Err(AppError::Conflict(
                    "only an active runtime template can be the company default".into(),
                ));
            }
        }
        let now = now_utc();
        let existing = self.repo.get_company_runtime_policy(input.company_id);
        let policy = CompanyRuntimePolicy {
            company_id: input.company_id,
            default_runtime_template_id: input.default_runtime_template_id,
            auto_apply_to_new_agents: input.auto_apply_to_new_agents,
            configured: true,
            created_by_human_user_id: existing
                .as_ref()
                .and_then(|policy| policy.created_by_human_user_id)
                .or(Some(input.human_user_id)),
            updated_by_human_user_id: Some(input.human_user_id),
            created_at: existing
                .as_ref()
                .and_then(|policy| policy.created_at)
                .or(Some(now)),
            updated_at: Some(now),
        };
        self.repo.save_company_runtime_policy(policy.clone())?;
        Ok(policy)
    }

