    pub fn publish_agent_model_price_catalog_entry(
        &self,
        input: PublishAgentModelPriceCatalogInput,
    ) -> AppResult<AgentModelPriceCatalogEntry> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let source = self
            .repo
            .get_agent_runtime_config_by_agent(input.source_agent_id)
            .filter(|config| config.company_id == input.company_id)
            .ok_or_else(|| {
                AppError::NotFound("source agent runtime is not configured in this company".into())
            })?;
        if source.executor_kind != AGENT_RUNTIME_EXECUTOR_MODEL_V1 {
            return Err(AppError::Validation(
                "only a model_v1 runtime can publish model pricing".into(),
            ));
        }
        let model_name = source.model_name.clone().ok_or_else(|| {
            AppError::Validation("source runtime model_name is not configured".into())
        })?;
        if source.model_input_price_microusd_per_million_tokens <= 0
            || source.model_output_price_microusd_per_million_tokens <= 0
        {
            return Err(AppError::Validation(
                "source runtime must have positive input and output model prices".into(),
            ));
        }
        if self
            .repo
            .list_company_agent_model_price_catalog_entries(input.company_id)
            .iter()
            .any(|entry| {
                entry.status == AGENT_MODEL_PRICE_CATALOG_STATUS_ACTIVE
                    && entry.model_provider == source.model_provider
                    && entry.model_name == model_name
                    && entry.input_price_microusd_per_million_tokens
                        == source.model_input_price_microusd_per_million_tokens
                    && entry.output_price_microusd_per_million_tokens
                        == source.model_output_price_microusd_per_million_tokens
            })
        {
            return Err(AppError::Conflict(
                "the active catalog version already has these model prices".into(),
            ));
        }
        let notes = normalize_optional_text(input.notes).unwrap_or_default();
        if notes.chars().count() > 1_000 {
            return Err(AppError::Validation(
                "model price catalog notes cannot exceed 1000 characters".into(),
            ));
        }
        let now = now_utc();
        self.repo
            .publish_agent_model_price_catalog_entry(AgentModelPriceCatalogEntry {
                id: Uuid::new_v4(),
                company_id: input.company_id,
                model_provider: source.model_provider,
                model_name,
                version: 0,
                status: AGENT_MODEL_PRICE_CATALOG_STATUS_ACTIVE.into(),
                input_price_microusd_per_million_tokens: source
                    .model_input_price_microusd_per_million_tokens,
                output_price_microusd_per_million_tokens: source
                    .model_output_price_microusd_per_million_tokens,
                notes,
                source_agent_profile_id: Some(input.source_agent_id),
                created_by_human_user_id: input.human_user_id,
                updated_by_human_user_id: Some(input.human_user_id),
                created_at: now,
                updated_at: now,
            })
    }

    pub fn archive_agent_model_price_catalog_entry(
        &self,
        input: ArchiveAgentModelPriceCatalogInput,
    ) -> AppResult<AgentModelPriceCatalogEntry> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let mut entry = self
            .repo
            .get_agent_model_price_catalog_entry(input.catalog_entry_id)
            .filter(|entry| entry.company_id == input.company_id)
            .ok_or_else(|| AppError::NotFound("model price catalog entry not found".into()))?;
        if entry.status == AGENT_MODEL_PRICE_CATALOG_STATUS_ARCHIVED {
            return Ok(entry);
        }
        entry.status = AGENT_MODEL_PRICE_CATALOG_STATUS_ARCHIVED.into();
        entry.updated_by_human_user_id = Some(input.human_user_id);
        entry.updated_at = now_utc();
        self.repo
            .save_agent_model_price_catalog_entry(entry.clone())?;
        Ok(entry)
    }

    pub fn apply_agent_model_price_catalog_entry(
        &self,
        input: ApplyAgentModelPriceCatalogInput,
    ) -> AppResult<CompanyAgentRuntimeView> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let entry = self
            .repo
            .get_agent_model_price_catalog_entry(input.catalog_entry_id)
            .filter(|entry| entry.company_id == input.company_id)
            .ok_or_else(|| AppError::NotFound("model price catalog entry not found".into()))?;
        if entry.status != AGENT_MODEL_PRICE_CATALOG_STATUS_ACTIVE {
            return Err(AppError::Conflict(
                "only an active model price catalog entry can be applied".into(),
            ));
        }
        let mut config = self
            .repo
            .get_agent_runtime_config_by_agent(input.agent_id)
            .filter(|config| config.company_id == input.company_id)
            .ok_or_else(|| AppError::NotFound("agent runtime is not configured".into()))?;
        if config.model_provider != entry.model_provider
            || config.model_name.as_deref() != Some(entry.model_name.as_str())
        {
            return Err(AppError::Conflict(
                "runtime provider and model must match the catalog entry".into(),
            ));
        }
        config.model_price_catalog_entry_id = Some(entry.id);
        config.model_input_price_microusd_per_million_tokens =
            entry.input_price_microusd_per_million_tokens;
        config.model_output_price_microusd_per_million_tokens =
            entry.output_price_microusd_per_million_tokens;
        config.updated_by_human_user_id = Some(input.human_user_id);
        config.updated_at = now_utc();
        self.repo.save_agent_runtime_config(config.clone())?;
        Ok(self.agent_runtime_view(config, 20))
    }

    pub fn create_agent_runtime_template(
        &self,
        input: CreateAgentRuntimeTemplateInput,
    ) -> AppResult<AgentRuntimeTemplate> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let name = input.name.trim();
        if name.is_empty() || name.chars().count() > 80 {
            return Err(AppError::Validation(
                "runtime template name must contain 1 to 80 characters".into(),
            ));
        }
        if self
            .repo
            .list_company_agent_runtime_templates(input.company_id)
            .iter()
            .any(|template| {
                template.status == AGENT_RUNTIME_TEMPLATE_STATUS_ACTIVE
                    && template.name.eq_ignore_ascii_case(name)
            })
        {
            return Err(AppError::Conflict(
                "an active runtime template with this name already exists".into(),
            ));
        }
        let description = normalize_optional_text(input.description).unwrap_or_default();
        if description.chars().count() > 1_000 {
            return Err(AppError::Validation(
                "runtime template description cannot exceed 1000 characters".into(),
            ));
        }
        let source = self
            .repo
            .get_agent_runtime_config_by_agent(input.source_agent_id)
            .filter(|config| config.company_id == input.company_id)
            .ok_or_else(|| {
                AppError::NotFound("source agent runtime is not configured in this company".into())
            })?;
        let now = now_utc();
        let template = AgentRuntimeTemplate {
            id: Uuid::new_v4(),
            company_id: input.company_id,
            name: name.to_string(),
            description,
            status: AGENT_RUNTIME_TEMPLATE_STATUS_ACTIVE.into(),
            settings: agent_runtime_template_settings_from_config(&source),
            source_agent_profile_id: Some(input.source_agent_id),
            created_by_human_user_id: input.human_user_id,
            updated_by_human_user_id: Some(input.human_user_id),
            created_at: now,
            updated_at: now,
        };
        self.repo.save_agent_runtime_template(template.clone())?;
        Ok(template)
    }

    pub fn archive_agent_runtime_template(
        &self,
        input: ArchiveAgentRuntimeTemplateInput,
    ) -> AppResult<AgentRuntimeTemplate> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let mut template = self
            .repo
            .get_agent_runtime_template(input.runtime_template_id)
            .filter(|template| template.company_id == input.company_id)
            .ok_or_else(|| AppError::NotFound("agent runtime template not found".into()))?;
        if template.status == AGENT_RUNTIME_TEMPLATE_STATUS_ARCHIVED {
            return Ok(template);
        }
        template.status = AGENT_RUNTIME_TEMPLATE_STATUS_ARCHIVED.into();
        template.updated_by_human_user_id = Some(input.human_user_id);
        template.updated_at = now_utc();
        self.repo.save_agent_runtime_template(template.clone())?;
        if let Some(mut policy) = self.repo.get_company_runtime_policy(input.company_id) {
            if policy.default_runtime_template_id == Some(template.id) {
                policy.default_runtime_template_id = None;
                policy.updated_by_human_user_id = Some(input.human_user_id);
                policy.updated_at = Some(template.updated_at);
                self.repo.save_company_runtime_policy(policy)?;
            }
        }
        Ok(template)
    }

    pub fn apply_agent_runtime_template(
        &self,
        input: ApplyAgentRuntimeTemplateInput,
    ) -> AppResult<CompanyAgentRuntimeView> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let template = self
            .repo
            .get_agent_runtime_template(input.runtime_template_id)
            .filter(|template| template.company_id == input.company_id)
            .ok_or_else(|| AppError::NotFound("agent runtime template not found".into()))?;
        if template.status != AGENT_RUNTIME_TEMPLATE_STATUS_ACTIVE {
            return Err(AppError::Conflict(
                "only an active runtime template can be applied".into(),
            ));
        }
        let settings = template.settings.clone();
        let runtime = self.upsert_agent_runtime(UpsertAgentRuntimeInput {
            human_user_id: input.human_user_id,
            company_id: input.company_id,
            agent_id: input.agent_id,
            interval_seconds: Some(settings.interval_seconds),
            max_events: Some(settings.max_events),
            daily_run_budget: Some(settings.daily_run_budget),
            daily_action_budget: Some(settings.daily_action_budget),
            daily_model_input_token_budget: Some(settings.daily_model_input_token_budget),
            daily_model_output_token_budget: Some(settings.daily_model_output_token_budget),
            daily_model_cost_budget_microusd: Some(settings.daily_model_cost_budget_microusd),
            model_input_price_microusd_per_million_tokens: Some(
                settings.model_input_price_microusd_per_million_tokens,
            ),
            model_output_price_microusd_per_million_tokens: Some(
                settings.model_output_price_microusd_per_million_tokens,
            ),
            daily_approval_request_budget: Some(settings.daily_approval_request_budget),
            executor_kind: Some(settings.executor_kind.clone()),
            company_message_policy: Some(settings.company_message_policy.clone()),
            auto_start_assigned_tasks: Some(settings.auto_start_assigned_tasks),
            auto_announce_project_membership: Some(settings.auto_announce_project_membership),
            context_max_projects: Some(settings.context_max_projects),
            context_max_conversations: Some(settings.context_max_conversations),
            context_max_inbox_events: Some(settings.context_max_inbox_events),
            system_prompt: Some(settings.system_prompt.clone()),
            model_name: settings.model_name.clone(),
            model_provider: Some(settings.model_provider.clone()),
            provider_secret_ref: settings.provider_secret_ref.clone(),
            allowed_model_actions: Some(settings.allowed_model_actions.clone()),
            approval_required_model_actions: Some(settings.approval_required_model_actions.clone()),
            approval_request_ttl_minutes: Some(settings.approval_request_ttl_minutes),
            model_max_output_tokens: Some(settings.model_max_output_tokens),
            model_timeout_seconds: Some(settings.model_timeout_seconds),
            model_max_retries: Some(settings.model_max_retries),
            fallback_to_rules_v1: Some(settings.fallback_to_rules_v1),
        })?;
        let mut config = runtime.config;
        apply_agent_runtime_template_settings(&mut config, &settings);
        config.runtime_template_id = Some(template.id);
        config.updated_by_human_user_id = Some(input.human_user_id);
        config.updated_at = now_utc();
        self.repo.save_agent_runtime_config(config.clone())?;
        Ok(self.agent_runtime_view(config, 20))
    }

    pub fn upsert_agent_runtime(
        &self,
        input: UpsertAgentRuntimeInput,
    ) -> AppResult<CompanyAgentRuntimeView> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let membership = self
            .repo
            .get_company_agent_membership(input.agent_id)
            .filter(|membership| membership.company_id == input.company_id)
            .ok_or_else(|| AppError::NotFound("company agent membership not found".into()))?;
        if membership.employment_status != "active" {
            return Err(AppError::Validation(
                "only an active company agent can use a managed runtime".into(),
            ));
        }
        let agent = self
            .repo
            .get_agent_profile(input.agent_id)
            .ok_or_else(|| AppError::NotFound("agent not found".into()))?;
        if !matches!(agent.status, AgentStatus::Active) {
            return Err(AppError::Validation(
                "only an active agent profile can use a managed runtime".into(),
            ));
        }

        let existing = self.repo.get_agent_runtime_config_by_agent(input.agent_id);
        let interval_seconds = input
            .interval_seconds
            .or_else(|| existing.as_ref().map(|config| config.interval_seconds))
            .unwrap_or(30);
        if !(5..=86_400).contains(&interval_seconds) {
            return Err(AppError::Validation(
                "runtime interval_seconds must be between 5 and 86400".into(),
            ));
        }
        let max_events = input
            .max_events
            .or_else(|| existing.as_ref().map(|config| config.max_events))
            .unwrap_or(5);
        if !(1..=20).contains(&max_events) {
            return Err(AppError::Validation(
                "runtime max_events must be between 1 and 20".into(),
            ));
        }
        let daily_run_budget = input
            .daily_run_budget
            .or_else(|| existing.as_ref().map(|config| config.daily_run_budget))
            .unwrap_or(500);
        if !(1..=10_000).contains(&daily_run_budget) {
            return Err(AppError::Validation(
                "runtime daily_run_budget must be between 1 and 10000".into(),
            ));
        }
        let daily_action_budget = input
            .daily_action_budget
            .or_else(|| existing.as_ref().map(|config| config.daily_action_budget))
            .unwrap_or(1_000);
        if !(1..=100_000).contains(&daily_action_budget) {
            return Err(AppError::Validation(
                "runtime daily_action_budget must be between 1 and 100000".into(),
            ));
        }
        let daily_model_input_token_budget = input
            .daily_model_input_token_budget
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.daily_model_input_token_budget)
            })
            .unwrap_or(2_000_000);
        if !(1_000..=1_000_000_000).contains(&daily_model_input_token_budget) {
            return Err(AppError::Validation(
                "runtime daily_model_input_token_budget must be between 1000 and 1000000000".into(),
            ));
        }
        let daily_model_output_token_budget = input
            .daily_model_output_token_budget
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.daily_model_output_token_budget)
            })
            .unwrap_or(500_000);
        if !(1_000..=1_000_000_000).contains(&daily_model_output_token_budget) {
            return Err(AppError::Validation(
                "runtime daily_model_output_token_budget must be between 1000 and 1000000000"
                    .into(),
            ));
        }
        let daily_model_cost_budget_microusd = input
            .daily_model_cost_budget_microusd
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.daily_model_cost_budget_microusd)
            })
            .unwrap_or(5_000_000);
        if !(1..=1_000_000_000_000).contains(&daily_model_cost_budget_microusd) {
            return Err(AppError::Validation(
                "runtime daily_model_cost_budget_microusd must be between 1 and 1000000000000"
                    .into(),
            ));
        }
        let model_input_price_microusd_per_million_tokens = input
            .model_input_price_microusd_per_million_tokens
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.model_input_price_microusd_per_million_tokens)
            })
            .unwrap_or(0);
        let model_output_price_microusd_per_million_tokens = input
            .model_output_price_microusd_per_million_tokens
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.model_output_price_microusd_per_million_tokens)
            })
            .unwrap_or(0);
        if !(0..=1_000_000_000_000).contains(&model_input_price_microusd_per_million_tokens)
            || !(0..=1_000_000_000_000).contains(&model_output_price_microusd_per_million_tokens)
            || (model_input_price_microusd_per_million_tokens == 0)
                != (model_output_price_microusd_per_million_tokens == 0)
        {
            return Err(AppError::Validation(
                "runtime model prices must both be zero or both be between 1 and 1000000000000 microusd per million tokens"
                    .into(),
            ));
        }
        let daily_approval_request_budget = input
            .daily_approval_request_budget
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.daily_approval_request_budget)
            })
            .unwrap_or(20);
        if !(1..=1_000).contains(&daily_approval_request_budget) {
            return Err(AppError::Validation(
                "runtime daily_approval_request_budget must be between 1 and 1000".into(),
            ));
        }
        let executor_kind = input
            .executor_kind
            .or_else(|| existing.as_ref().map(|config| config.executor_kind.clone()))
            .unwrap_or_else(|| AGENT_RUNTIME_EXECUTOR_RULES_V1.into());
        if !matches!(
            executor_kind.as_str(),
            AGENT_RUNTIME_EXECUTOR_RULES_V1 | AGENT_RUNTIME_EXECUTOR_MODEL_V1
        ) {
            return Err(AppError::Validation(
                "runtime executor_kind must be rules_v1 or model_v1".into(),
            ));
        }
        let company_message_policy = input
            .company_message_policy
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.company_message_policy.clone())
            })
            .unwrap_or_else(|| AGENT_RUNTIME_MESSAGE_POLICY_DIRECT_ACK.into());
        if !matches!(
            company_message_policy.as_str(),
            AGENT_RUNTIME_MESSAGE_POLICY_OBSERVE
                | AGENT_RUNTIME_MESSAGE_POLICY_DIRECT_ACK
                | AGENT_RUNTIME_MESSAGE_POLICY_MENTIONED_ACK
        ) {
            return Err(AppError::Validation(
                "runtime company_message_policy must be observe, direct_ack, or mentioned_ack"
                    .into(),
            ));
        }
        let auto_start_assigned_tasks = input
            .auto_start_assigned_tasks
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.auto_start_assigned_tasks)
            })
            .unwrap_or(true);
        let auto_announce_project_membership = input
            .auto_announce_project_membership
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.auto_announce_project_membership)
            })
            .unwrap_or(true);
        let context_max_projects = runtime_context_limit(
            input.context_max_projects,
            existing.as_ref().map(|config| config.context_max_projects),
            10,
            50,
            "context_max_projects",
        )?;
        let context_max_conversations = runtime_context_limit(
            input.context_max_conversations,
            existing
                .as_ref()
                .map(|config| config.context_max_conversations),
            10,
            50,
            "context_max_conversations",
        )?;
        let context_max_inbox_events = runtime_context_limit(
            input.context_max_inbox_events,
            existing
                .as_ref()
                .map(|config| config.context_max_inbox_events),
            20,
            100,
            "context_max_inbox_events",
        )?;

        let system_prompt = input
            .system_prompt
            .unwrap_or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.system_prompt.clone())
                    .unwrap_or_default()
            })
            .trim()
            .to_string();
        if system_prompt.chars().count() > 20_000 {
            return Err(AppError::Validation(
                "runtime system_prompt cannot exceed 20000 characters".into(),
            ));
        }
        let model_name = normalize_runtime_optional_text(
            input.model_name,
            existing
                .as_ref()
                .and_then(|config| config.model_name.clone()),
            120,
            "model_name",
        )?;
        let model_provider = input
            .model_provider
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.model_provider.clone())
            })
            .unwrap_or_else(|| AGENT_RUNTIME_MODEL_PROVIDER_OPENAI_RESPONSES.into());
        if model_provider != AGENT_RUNTIME_MODEL_PROVIDER_OPENAI_RESPONSES {
            return Err(AppError::Validation(
                "runtime model_provider must be openai_responses".into(),
            ));
        }
        let provider_secret_ref = normalize_runtime_optional_text(
            input.provider_secret_ref,
            existing
                .as_ref()
                .and_then(|config| config.provider_secret_ref.clone()),
            256,
            "provider_secret_ref",
        )?;
        if let Some(secret_ref) = provider_secret_ref.as_deref() {
            validate_runtime_provider_secret_reference(secret_ref)?;
        }
        let allowed_model_actions =
            normalize_runtime_model_actions(input.allowed_model_actions.or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.allowed_model_actions.clone())
            }))?;
        let approval_required_model_actions = normalize_runtime_approval_actions(
            input.approval_required_model_actions.or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.approval_required_model_actions.clone())
            }),
        )?;
        let approval_request_ttl_minutes = input
            .approval_request_ttl_minutes
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.approval_request_ttl_minutes)
            })
            .unwrap_or(1_440);
        if !(5..=10_080).contains(&approval_request_ttl_minutes) {
            return Err(AppError::Validation(
                "runtime approval_request_ttl_minutes must be between 5 and 10080".into(),
            ));
        }
        let model_max_output_tokens = input
            .model_max_output_tokens
            .or_else(|| {
                existing
                    .as_ref()
                    .map(|config| config.model_max_output_tokens)
            })
            .unwrap_or(1_200);
        if !(64..=8_192).contains(&model_max_output_tokens) {
            return Err(AppError::Validation(
                "runtime model_max_output_tokens must be between 64 and 8192".into(),
            ));
        }
        let model_timeout_seconds = input
            .model_timeout_seconds
            .or_else(|| existing.as_ref().map(|config| config.model_timeout_seconds))
            .unwrap_or(30);
        if !(1..=120).contains(&model_timeout_seconds) {
            return Err(AppError::Validation(
                "runtime model_timeout_seconds must be between 1 and 120".into(),
            ));
        }
        let model_max_retries = input
            .model_max_retries
            .or_else(|| existing.as_ref().map(|config| config.model_max_retries))
            .unwrap_or(1);
        if !(0..=3).contains(&model_max_retries) {
            return Err(AppError::Validation(
                "runtime model_max_retries must be between 0 and 3".into(),
            ));
        }
        let fallback_to_rules_v1 = input
            .fallback_to_rules_v1
            .or_else(|| existing.as_ref().map(|config| config.fallback_to_rules_v1))
            .unwrap_or(true);
        if executor_kind == AGENT_RUNTIME_EXECUTOR_MODEL_V1 {
            if model_name.is_none() {
                return Err(AppError::Validation(
                    "runtime model_name is required for model_v1".into(),
                ));
            }
            if provider_secret_ref.is_none() {
                return Err(AppError::Validation(
                    "runtime provider_secret_ref is required for model_v1".into(),
                ));
            }
        }
        let model_price_catalog_entry_id = existing
            .as_ref()
            .and_then(|config| config.model_price_catalog_entry_id)
            .and_then(|entry_id| self.repo.get_agent_model_price_catalog_entry(entry_id))
            .filter(|entry| {
                entry.company_id == input.company_id
                    && entry.model_provider == model_provider
                    && model_name.as_deref() == Some(entry.model_name.as_str())
                    && entry.input_price_microusd_per_million_tokens
                        == model_input_price_microusd_per_million_tokens
                    && entry.output_price_microusd_per_million_tokens
                        == model_output_price_microusd_per_million_tokens
            })
            .map(|entry| entry.id);

        let now = now_utc();
        let config = AgentRuntimeConfig {
            id: existing
                .as_ref()
                .map(|config| config.id)
                .unwrap_or_else(Uuid::new_v4),
            company_id: input.company_id,
            agent_profile_id: input.agent_id,
            runtime_template_id: existing
                .as_ref()
                .and_then(|config| config.runtime_template_id),
            model_price_catalog_entry_id,
            executor_kind,
            status: existing
                .as_ref()
                .map(|config| config.status.clone())
                .unwrap_or_else(|| AGENT_RUNTIME_STATUS_ACTIVE.into()),
            interval_seconds,
            max_events,
            daily_run_budget,
            daily_action_budget,
            daily_model_input_token_budget,
            daily_model_output_token_budget,
            daily_model_cost_budget_microusd,
            model_input_price_microusd_per_million_tokens,
            model_output_price_microusd_per_million_tokens,
            daily_approval_request_budget,
            company_message_policy,
            auto_start_assigned_tasks,
            auto_announce_project_membership,
            context_max_projects,
            context_max_conversations,
            context_max_inbox_events,
            system_prompt,
            model_name,
            model_provider,
            provider_secret_ref,
            allowed_model_actions,
            approval_required_model_actions,
            approval_request_ttl_minutes,
            model_max_output_tokens,
            model_timeout_seconds,
            model_max_retries,
            fallback_to_rules_v1,
            next_run_at: existing
                .as_ref()
                .map(|config| config.next_run_at)
                .unwrap_or(now),
            last_run_at: existing.as_ref().and_then(|config| config.last_run_at),
            last_success_at: existing.as_ref().and_then(|config| config.last_success_at),
            last_error_at: existing.as_ref().and_then(|config| config.last_error_at),
            last_error: existing
                .as_ref()
                .and_then(|config| config.last_error.clone()),
            created_by_human_user_id: existing
                .as_ref()
                .map(|config| config.created_by_human_user_id)
                .unwrap_or(input.human_user_id),
            updated_by_human_user_id: Some(input.human_user_id),
            created_at: existing
                .as_ref()
                .map(|config| config.created_at)
                .unwrap_or(now),
            updated_at: now,
        };
        self.repo.save_agent_runtime_config(config.clone())?;
        Ok(self.agent_runtime_view(config, 20))
    }

    pub fn check_agent_runtime_secret_reference(
        &self,
        input: CheckAgentRuntimeSecretInput,
    ) -> AppResult<AgentRuntimeSecretHealthView> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let config = self
            .repo
            .get_agent_runtime_config_by_agent(input.agent_id)
            .filter(|config| config.company_id == input.company_id)
            .ok_or_else(|| AppError::NotFound("agent runtime is not configured".into()))?;
        let provider_secret_ref = config.provider_secret_ref.as_deref().ok_or_else(|| {
            AppError::Validation("runtime provider_secret_ref is not configured".into())
        })?;
        validate_runtime_provider_secret_reference(provider_secret_ref)?;
        self.runtime_model_provider
            .check_secret_reference(provider_secret_ref)?;
        Ok(agent_runtime_secret_health_view(
            &config,
            provider_secret_ref,
        ))
    }

    pub fn rotate_agent_runtime_secret_reference(
        &self,
        input: RotateAgentRuntimeSecretReferenceInput,
    ) -> AppResult<AgentRuntimeSecretRotationResult> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let provider_secret_ref = input.provider_secret_ref.trim().to_string();
        validate_runtime_provider_secret_reference(&provider_secret_ref)?;
        let mut config = self
            .repo
            .get_agent_runtime_config_by_agent(input.agent_id)
            .filter(|config| config.company_id == input.company_id)
            .ok_or_else(|| AppError::NotFound("agent runtime is not configured".into()))?;
        if config.provider_secret_ref.as_deref() == Some(provider_secret_ref.as_str()) {
            return Err(AppError::Conflict(
                "runtime provider secret reference is unchanged".into(),
            ));
        }
        self.runtime_model_provider
            .check_secret_reference(&provider_secret_ref)?;
        let checked_at = now_utc();
        config.provider_secret_ref = Some(provider_secret_ref.clone());
        config.updated_by_human_user_id = Some(input.human_user_id);
        config.updated_at = checked_at;
        self.repo.save_agent_runtime_config(config.clone())?;
        Ok(AgentRuntimeSecretRotationResult {
            secret_health: agent_runtime_secret_health_view(&config, &provider_secret_ref),
        })
    }

    pub fn pause_agent_runtime(
        &self,
        input: SetAgentRuntimeStatusInput,
    ) -> AppResult<CompanyAgentRuntimeView> {
        self.set_agent_runtime_status(input, AGENT_RUNTIME_STATUS_PAUSED)
    }

    pub fn resume_agent_runtime(
        &self,
        input: SetAgentRuntimeStatusInput,
    ) -> AppResult<CompanyAgentRuntimeView> {
        self.set_agent_runtime_status(input, AGENT_RUNTIME_STATUS_ACTIVE)
    }

    pub fn list_due_agent_runtimes_for_worker(
        &self,
        limit: usize,
    ) -> AppResult<Vec<AgentRuntimeConfig>> {
        let now = now_utc();
        Ok(self
            .repo
            .list_due_agent_runtime_configs(now, limit.clamp(1, 1_000))
            .into_iter()
            .filter(|config| {
                self.repo
                    .get_company(config.company_id)
                    .is_some_and(|company| company.status == "active")
                    && self
                        .repo
                        .get_company_agent_membership(config.agent_profile_id)
                        .is_some_and(|membership| {
                            membership.company_id == config.company_id
                                && membership.employment_status == "active"
                        })
                    && self
                        .repo
                        .get_agent_profile(config.agent_profile_id)
                        .is_some_and(|agent| matches!(agent.status, AgentStatus::Active))
            })
            .collect())
    }

    pub fn execute_due_agent_runtime(
        &self,
        runtime_config_id: Uuid,
    ) -> AppResult<Option<ManagedAgentRuntimeRunResult>> {
        let mut config = self
            .repo
            .get_agent_runtime_config(runtime_config_id)
            .ok_or_else(|| AppError::NotFound("agent runtime config not found".into()))?;
        if config.status != AGENT_RUNTIME_STATUS_ACTIVE {
            return Ok(None);
        }

        let now = now_utc();
        let next_interval_run = now + Duration::seconds(i64::from(config.interval_seconds));
        let pending_events = self.repo.list_agent_inbox_events(
            config.agent_profile_id,
            Some(AgentInboxEventStatus::Pending),
            10_000,
        );
        let pending_count = pending_events.len();
        if pending_count == 0 {
            let _ = self
                .repo
                .claim_agent_runtime_config(config.id, now, next_interval_run)?;
            return Ok(None);
        }

        let context_snapshot = self.build_agent_runtime_context_snapshot(&config)?;
        let context_payload = serde_json::to_value(&context_snapshot).unwrap_or_default();

        let window_start = runtime_daily_window_start(now);
        let usage = self
            .repo
            .get_agent_runtime_daily_usage(config.id, window_start);
        let remaining_action_budget =
            (i64::from(config.daily_action_budget) - usage.action_count).max(0) as usize;
        let approval_request_count = usage.approval_request_count.max(
            self.repo
                .count_agent_tool_approval_requests_since(config.agent_profile_id, window_start)
                as i64,
        );
        let remaining_approval_request_budget = (i64::from(config.daily_approval_request_budget)
            - approval_request_count)
            .max(0) as usize;
        let estimated_model_input_tokens =
            estimate_runtime_model_input_tokens(&context_snapshot, &config.system_prompt);
        let remaining_model_output_tokens =
            (config.daily_model_output_token_budget - usage.model_output_tokens).max(0);
        let estimated_model_cost_microusd = calculate_runtime_model_cost_microusd(
            estimated_model_input_tokens,
            i64::from(config.model_max_output_tokens).min(remaining_model_output_tokens),
            config.model_input_price_microusd_per_million_tokens,
            config.model_output_price_microusd_per_million_tokens,
        );
        let company_model_usage = self
            .repo
            .get_company_model_daily_usage(config.company_id, window_start);
        let company_model_budget = self
            .company_model_budget_policy(config.company_id)
            .daily_model_cost_budget_microusd;
        let budget_error = if usage.run_count >= i64::from(config.daily_run_budget) {
            Some(format!(
                "daily runtime run budget exceeded: {} runs",
                config.daily_run_budget
            ))
        } else if usage.action_count >= i64::from(config.daily_action_budget) {
            Some(format!(
                "daily runtime action budget exceeded: {} actions",
                config.daily_action_budget
            ))
        } else if config.executor_kind == AGENT_RUNTIME_EXECUTOR_MODEL_V1
            && approval_request_count >= i64::from(config.daily_approval_request_budget)
        {
            Some(format!(
                "daily runtime approval request budget exceeded: {} requests",
                config.daily_approval_request_budget
            ))
        } else if config.executor_kind == AGENT_RUNTIME_EXECUTOR_MODEL_V1
            && usage.model_input_tokens + estimated_model_input_tokens
                > config.daily_model_input_token_budget
        {
            Some(format!(
                "daily runtime model input token budget cannot cover the estimated request: {} remaining",
                (config.daily_model_input_token_budget - usage.model_input_tokens).max(0)
            ))
        } else if config.executor_kind == AGENT_RUNTIME_EXECUTOR_MODEL_V1
            && remaining_model_output_tokens < 64
        {
            Some(format!(
                "daily runtime model output token budget is exhausted: {} remaining",
                remaining_model_output_tokens
            ))
        } else if config.executor_kind == AGENT_RUNTIME_EXECUTOR_MODEL_V1
            && usage.model_cost_microusd + estimated_model_cost_microusd
                > config.daily_model_cost_budget_microusd
        {
            Some(format!(
                "daily runtime model cost budget cannot cover the estimated request: {} microusd remaining",
                (config.daily_model_cost_budget_microusd - usage.model_cost_microusd).max(0)
            ))
        } else if config.executor_kind == AGENT_RUNTIME_EXECUTOR_MODEL_V1
            && company_model_usage.model_cost_microusd + estimated_model_cost_microusd
                > company_model_budget
        {
            Some(format!(
                "daily company model cost budget cannot cover the estimated request: {} microusd remaining",
                (company_model_budget - company_model_usage.model_cost_microusd).max(0)
            ))
        } else if pending_events.first().is_some_and(|event| {
            autonomy_event_action_upper_bound(&event.event_type) > remaining_action_budget
        }) {
            Some(format!(
                "remaining daily runtime action budget ({remaining_action_budget}) cannot cover the next inbox event"
            ))
        } else {
            None
        };

        let next_run_at = budget_error
            .as_ref()
            .map(|_| window_start + Duration::days(1))
            .unwrap_or(next_interval_run);
        if !self
            .repo
            .claim_agent_runtime_config(config.id, now, next_run_at)?
        {
            return Ok(None);
        }

        let input_event_count = pending_count.min(config.max_events as usize) as i32;
        if let Some(error_message) = budget_error {
            let run = AgentRuntimeRun {
                id: Uuid::new_v4(),
                runtime_config_id: config.id,
                company_id: config.company_id,
                agent_profile_id: config.agent_profile_id,
                trigger_type: AGENT_RUNTIME_TRIGGER_SCHEDULED.into(),
                executor_kind: config.executor_kind.clone(),
                status: AGENT_RUNTIME_RUN_STATUS_SKIPPED_BUDGET.into(),
                input_event_count,
                processed_event_count: 0,
                action_count: 0,
                approval_request_count: 0,
                model_request_count: 0,
                model_input_tokens: 0,
                model_output_tokens: 0,
                model_cost_microusd: 0,
                model_input_price_microusd_per_million_tokens: config
                    .model_input_price_microusd_per_million_tokens,
                model_output_price_microusd_per_million_tokens: config
                    .model_output_price_microusd_per_million_tokens,
                model_pricing_status: runtime_model_pricing_status(&config).into(),
                remaining_pending_count: pending_count as i32,
                input_payload: json!({
                    "executor_kind": config.executor_kind.clone(),
                    "daily_usage": usage,
                    "company_daily_model_usage": company_model_usage,
                    "company_daily_model_cost_budget_microusd": company_model_budget,
                    "estimated_model_cost_microusd": estimated_model_cost_microusd,
                    "context_snapshot": context_payload,
                }),
                output_payload: json!({}),
                error_message: Some(error_message),
                started_at: now,
                finished_at: Some(now),
            };
            self.repo.insert_agent_runtime_run(run.clone())?;
            config.next_run_at = next_run_at;
            config.last_run_at = Some(now);
            config.updated_by_human_user_id = None;
            config.updated_at = now;
            self.repo.save_agent_runtime_config(config)?;
            return Ok(Some(ManagedAgentRuntimeRunResult {
                run,
                tick: None,
                model_execution: None,
            }));
        }

        let mut run = AgentRuntimeRun {
            id: Uuid::new_v4(),
            runtime_config_id: config.id,
            company_id: config.company_id,
            agent_profile_id: config.agent_profile_id,
            trigger_type: AGENT_RUNTIME_TRIGGER_SCHEDULED.into(),
            executor_kind: config.executor_kind.clone(),
            status: AGENT_RUNTIME_RUN_STATUS_RUNNING.into(),
            input_event_count,
            processed_event_count: 0,
            action_count: 0,
            approval_request_count: 0,
            model_request_count: 0,
            model_input_tokens: 0,
            model_output_tokens: 0,
            model_cost_microusd: 0,
            model_input_price_microusd_per_million_tokens: config
                .model_input_price_microusd_per_million_tokens,
            model_output_price_microusd_per_million_tokens: config
                .model_output_price_microusd_per_million_tokens,
            model_pricing_status: runtime_model_pricing_status(&config).into(),
            remaining_pending_count: pending_count as i32,
            input_payload: json!({
                "executor_kind": config.executor_kind.clone(),
                "max_events": config.max_events,
                "system_prompt_configured": !config.system_prompt.is_empty(),
                "model_name": config.model_name.clone(),
                "model_provider": config.model_provider.clone(),
                "allowed_model_actions": config.allowed_model_actions.clone(),
                "approval_required_model_actions": config.approval_required_model_actions.clone(),
                "approval_request_ttl_minutes": config.approval_request_ttl_minutes,
                "model_max_output_tokens": config.model_max_output_tokens,
                "model_timeout_seconds": config.model_timeout_seconds,
                "model_max_retries": config.model_max_retries,
                "fallback_to_rules_v1": config.fallback_to_rules_v1,
                "daily_model_cost_budget_microusd": config.daily_model_cost_budget_microusd,
                "model_input_price_microusd_per_million_tokens": config.model_input_price_microusd_per_million_tokens,
                "model_output_price_microusd_per_million_tokens": config.model_output_price_microusd_per_million_tokens,
                "estimated_model_cost_microusd": estimated_model_cost_microusd,
                "company_daily_model_cost_budget_microusd": company_model_budget,
                "provider_secret_ref_configured": config.provider_secret_ref.is_some(),
                "context_snapshot": context_payload,
            }),
            output_payload: json!({}),
            error_message: None,
            started_at: now,
            finished_at: None,
        };
        self.repo.insert_agent_runtime_run(run.clone())?;

        let execution = match self.enforce_agent_action_budget(config.agent_profile_id) {
            Ok(()) => self.execute_agent_runtime_strategy(
                &config,
                run.id,
                &context_snapshot,
                &pending_events,
                AgentRuntimeExecutionBudgets {
                    remaining_action_budget,
                    remaining_approval_request_budget,
                    remaining_model_output_tokens,
                },
            ),
            Err(error) => Err(error.into()),
        };
        let finished_at = now_utc();
        config.next_run_at = next_run_at;
        config.last_run_at = Some(finished_at);
        config.updated_by_human_user_id = None;
        config.updated_at = finished_at;
        let runtime_action_type = if config.executor_kind == AGENT_RUNTIME_EXECUTOR_MODEL_V1 {
            "agent.runtime.model_v1"
        } else {
            "agent.runtime.rules_v1"
        };

        match execution {
            Ok(execution) => {
                run.status = AGENT_RUNTIME_RUN_STATUS_SUCCEEDED.into();
                run.processed_event_count = execution.processed_event_count;
                run.action_count = execution.action_count;
                run.approval_request_count = execution.approval_request_count;
                run.model_request_count = execution.model_request_count;
                run.model_input_tokens = execution.model_input_tokens;
                run.model_output_tokens = execution.model_output_tokens;
                run.model_cost_microusd = execution.model_cost_microusd;
                run.model_input_price_microusd_per_million_tokens =
                    execution.model_input_price_microusd_per_million_tokens;
                run.model_output_price_microusd_per_million_tokens =
                    execution.model_output_price_microusd_per_million_tokens;
                run.model_pricing_status = execution.model_pricing_status;
                run.remaining_pending_count = execution.remaining_pending_count;
                run.output_payload = execution.output_payload;
                run.finished_at = Some(finished_at);
                config.last_success_at = Some(finished_at);
                config.last_error = None;
                config.last_error_at = None;
                self.repo.update_agent_runtime_run(run.clone())?;
                self.repo.save_agent_runtime_config(config)?;
                let _ = self.record_agent_action(
                    run.agent_profile_id,
                    runtime_action_type,
                    Some(format!("runtime:{}", run.runtime_config_id)),
                    run.input_payload.clone(),
                    run.output_payload.clone(),
                    AgentActionStatus::Success,
                );
                Ok(Some(ManagedAgentRuntimeRunResult {
                    run,
                    tick: execution.tick,
                    model_execution: execution.model_execution,
                }))
            }
            Err(failure) => {
                let AgentRuntimeExecutionFailure { error, model_usage } = failure;
                let error_message = error.to_string();
                run.model_request_count = model_usage.request_count;
                run.model_input_tokens = model_usage.input_tokens;
                run.model_output_tokens = model_usage.output_tokens;
                run.model_cost_microusd = model_usage.cost_microusd;
                run.model_input_price_microusd_per_million_tokens =
                    model_usage.input_price_microusd_per_million_tokens;
                run.model_output_price_microusd_per_million_tokens =
                    model_usage.output_price_microusd_per_million_tokens;
                run.model_pricing_status = model_usage.pricing_status;
                run.status = if matches!(error, AppError::RateLimited(_)) {
                    AGENT_RUNTIME_RUN_STATUS_SKIPPED_BUDGET.into()
                } else {
                    AGENT_RUNTIME_RUN_STATUS_FAILED.into()
                };
                run.error_message = Some(error_message.clone());
                run.finished_at = Some(finished_at);
                if run.status == AGENT_RUNTIME_RUN_STATUS_FAILED {
                    config.status = AGENT_RUNTIME_STATUS_ERROR.into();
                    config.last_error_at = Some(finished_at);
                    config.last_error = Some(error_message.clone());
                }
                self.repo.update_agent_runtime_run(run.clone())?;
                self.repo.save_agent_runtime_config(config)?;
                let _ = self.record_agent_action(
                    run.agent_profile_id,
                    runtime_action_type,
                    Some(format!("runtime:{}", run.runtime_config_id)),
                    run.input_payload.clone(),
                    json!({ "error": error_message }),
                    AgentActionStatus::Failed,
                );
                Ok(Some(ManagedAgentRuntimeRunResult {
                    run,
                    tick: None,
                    model_execution: None,
                }))
            }
        }
    }

    fn execute_agent_runtime_strategy(
        &self,
        config: &AgentRuntimeConfig,
        runtime_run_id: Uuid,
        context_snapshot: &AgentRuntimeContextSnapshot,
        pending_events: &[AgentInboxEvent],
        budgets: AgentRuntimeExecutionBudgets,
    ) -> Result<AgentRuntimeExecutionSuccess, AgentRuntimeExecutionFailure> {
        let AgentRuntimeExecutionBudgets {
            remaining_action_budget,
            remaining_approval_request_budget,
            remaining_model_output_tokens,
        } = budgets;
        if config.executor_kind == AGENT_RUNTIME_EXECUTOR_RULES_V1 {
            let tick = self.run_agent_autonomy(RunAgentAutonomyInput {
                actor_agent_id: config.agent_profile_id,
                max_events: config.max_events as usize,
                max_actions: Some(remaining_action_budget),
                policy: Some(AgentAutonomyPolicy {
                    company_id: config.company_id,
                    company_message_policy: config.company_message_policy.clone(),
                    auto_start_assigned_tasks: config.auto_start_assigned_tasks,
                    auto_announce_project_membership: config.auto_announce_project_membership,
                }),
            })?;
            let action_count = tick
                .runs
                .iter()
                .map(|event_run| event_run.actions.len() as i32)
                .sum();
            return Ok(AgentRuntimeExecutionSuccess {
                processed_event_count: tick.processed_event_count as i32,
                action_count,
                approval_request_count: 0,
                remaining_pending_count: tick.remaining_pending_count as i32,
                model_request_count: 0,
                model_input_tokens: 0,
                model_output_tokens: 0,
                model_cost_microusd: 0,
                model_input_price_microusd_per_million_tokens: 0,
                model_output_price_microusd_per_million_tokens: 0,
                model_pricing_status: AGENT_RUNTIME_MODEL_PRICING_STATUS_UNPRICED.into(),
                output_payload: serde_json::to_value(&tick).unwrap_or_default(),
                tick: Some(tick),
                model_execution: None,
            });
        }
        if config.executor_kind != AGENT_RUNTIME_EXECUTOR_MODEL_V1 {
            return Err(AppError::Validation(format!(
                "unsupported runtime executor_kind: {}",
                config.executor_kind
            ))
            .into());
        }

        let selected_events = pending_events
            .iter()
            .take(config.max_events as usize)
            .cloned()
            .collect::<Vec<_>>();
        let (ignored_runtime_generated_events, actionable_events): (Vec<_>, Vec<_>) =
            selected_events
                .iter()
                .cloned()
                .partition(is_runtime_generated_message_event);
        let allowed_actions = config
            .allowed_model_actions
            .iter()
            .filter(|action| context_snapshot.allowed_actions.contains(action))
            .cloned()
            .collect::<Vec<_>>();
        let approval_required_actions = config
            .approval_required_model_actions
            .iter()
            .filter(|action| context_snapshot.approval_required_actions.contains(action))
            .cloned()
            .collect::<Vec<_>>();

        if actionable_events.is_empty()
            || (allowed_actions.is_empty() && approval_required_actions.is_empty())
        {
            self.mark_runtime_events_with_status(
                &selected_events,
                AgentInboxEventStatus::Processed,
            )?;
            let remaining_pending_count = self
                .repo
                .list_agent_inbox_events(
                    config.agent_profile_id,
                    Some(AgentInboxEventStatus::Pending),
                    10_000,
                )
                .len() as i32;
            let execution = AgentRuntimeModelExecutionResult {
                plan: AgentRuntimeModelPlan {
                    summary: if actionable_events.is_empty() {
                        "仅收到 Runtime 自动生成事件，已安全忽略以防止循环回复".into()
                    } else {
                        "当前上下文没有获批的模型动作，事件已按观察模式处理".into()
                    },
                    actions: Vec::new(),
                    approval_requests: Vec::new(),
                },
                actions: Vec::new(),
                approval_requests: Vec::new(),
                processed_event_ids: actionable_events.iter().map(|event| event.id).collect(),
                ignored_runtime_generated_event_ids: ignored_runtime_generated_events
                    .iter()
                    .map(|event| event.id)
                    .collect(),
                provider_request_id: None,
                resolved_model_name: config.model_name.clone(),
                request_count: 0,
                input_tokens: 0,
                output_tokens: 0,
                cost_microusd: 0,
                input_price_microusd_per_million_tokens: config
                    .model_input_price_microusd_per_million_tokens,
                output_price_microusd_per_million_tokens: config
                    .model_output_price_microusd_per_million_tokens,
                pricing_status: runtime_model_pricing_status(config).into(),
            };
            return Ok(AgentRuntimeExecutionSuccess {
                processed_event_count: selected_events.len() as i32,
                action_count: 0,
                approval_request_count: 0,
                remaining_pending_count,
                model_request_count: 0,
                model_input_tokens: 0,
                model_output_tokens: 0,
                model_cost_microusd: 0,
                model_input_price_microusd_per_million_tokens: config
                    .model_input_price_microusd_per_million_tokens,
                model_output_price_microusd_per_million_tokens: config
                    .model_output_price_microusd_per_million_tokens,
                model_pricing_status: runtime_model_pricing_status(config).into(),
                output_payload: json!({ "model_execution": execution }),
                tick: None,
                model_execution: Some(execution),
            });
        }

        let mut model_context = context_snapshot.clone();
        model_context.pending_inbox_events = actionable_events.clone();
        let max_actions = remaining_action_budget.min(20);
        let max_output_tokens = i64::from(config.model_max_output_tokens)
            .min(remaining_model_output_tokens)
            .clamp(64, 8_192) as i32;
        let request = AgentRuntimeModelRequest {
            runtime_config_id: config.id,
            model_provider: config.model_provider.clone(),
            model_name: config
                .model_name
                .clone()
                .ok_or_else(|| AppError::Validation("runtime model_name is required".into()))?,
            provider_secret_ref: config.provider_secret_ref.clone().ok_or_else(|| {
                AppError::Validation("runtime provider_secret_ref is required".into())
            })?,
            system_prompt: build_runtime_model_system_prompt(config),
            context_snapshot: model_context,
            allowed_actions,
            approval_required_actions,
            max_actions,
            max_approval_requests: remaining_approval_request_budget.min(10),
            max_output_tokens,
            timeout_seconds: config.model_timeout_seconds,
        };

        let mut request_count = 0;
        let response = loop {
            request_count += 1;
            match self.runtime_model_provider.generate_plan(request.clone()) {
                Ok(response) => break Ok(response),
                Err(_error) if request_count <= config.model_max_retries => continue,
                Err(error) => break Err(error),
            }
        };
        let response = match response {
            Ok(response) => response,
            Err(error) if config.fallback_to_rules_v1 => {
                let tick = self.run_agent_autonomy(RunAgentAutonomyInput {
                    actor_agent_id: config.agent_profile_id,
                    max_events: config.max_events as usize,
                    max_actions: Some(remaining_action_budget),
                    policy: Some(AgentAutonomyPolicy {
                        company_id: config.company_id,
                        company_message_policy: config.company_message_policy.clone(),
                        auto_start_assigned_tasks: config.auto_start_assigned_tasks,
                        auto_announce_project_membership: config.auto_announce_project_membership,
                    }),
                })?;
                let action_count = tick
                    .runs
                    .iter()
                    .map(|event_run| event_run.actions.len() as i32)
                    .sum();
                return Ok(AgentRuntimeExecutionSuccess {
                    processed_event_count: tick.processed_event_count as i32,
                    action_count,
                    approval_request_count: 0,
                    remaining_pending_count: tick.remaining_pending_count as i32,
                    model_request_count: request_count,
                    model_input_tokens: 0,
                    model_output_tokens: 0,
                    model_cost_microusd: 0,
                    model_input_price_microusd_per_million_tokens: config
                        .model_input_price_microusd_per_million_tokens,
                    model_output_price_microusd_per_million_tokens: config
                        .model_output_price_microusd_per_million_tokens,
                    model_pricing_status: runtime_model_pricing_status(config).into(),
                    output_payload: json!({
                        "fallback_executor": AGENT_RUNTIME_EXECUTOR_RULES_V1,
                        "model_error": error.to_string(),
                        "model_request_count": request_count,
                        "tick": tick,
                    }),
                    tick: Some(tick),
                    model_execution: None,
                });
            }
            Err(error) => {
                return Err(AgentRuntimeExecutionFailure::with_model_usage(
                    error,
                    AgentRuntimeModelUsageSnapshot::for_config(config, request_count, 0, 0),
                ))
            }
        };
        let model_usage = AgentRuntimeModelUsageSnapshot::for_config(
            config,
            request_count,
            response.input_tokens,
            response.output_tokens,
        );

        if let Err(error) = self.validate_agent_runtime_model_plan(
            config,
            context_snapshot,
            &response.plan,
            max_actions,
            remaining_approval_request_budget.min(10),
        ) {
            if let Err(mark_error) = self
                .mark_runtime_events_with_status(&selected_events, AgentInboxEventStatus::Failed)
            {
                return Err(AgentRuntimeExecutionFailure::with_model_usage(
                    mark_error,
                    model_usage,
                ));
            }
            return Err(AgentRuntimeExecutionFailure::with_model_usage(
                error,
                model_usage,
            ));
        }
        let actions = match self.execute_agent_runtime_model_plan(config, &response.plan) {
            Ok(actions) => actions,
            Err(error) => {
                if let Err(mark_error) = self.mark_runtime_events_with_status(
                    &selected_events,
                    AgentInboxEventStatus::Failed,
                ) {
                    return Err(AgentRuntimeExecutionFailure::with_model_usage(
                        mark_error,
                        model_usage,
                    ));
                }
                return Err(AgentRuntimeExecutionFailure::with_model_usage(
                    error,
                    model_usage,
                ));
            }
        };
        let approval_requests = match self.create_agent_runtime_approval_requests(
            config,
            runtime_run_id,
            &response.plan,
        ) {
            Ok(requests) => requests,
            Err(error) => {
                if let Err(mark_error) = self.mark_runtime_events_with_status(
                    &selected_events,
                    AgentInboxEventStatus::Failed,
                ) {
                    return Err(AgentRuntimeExecutionFailure::with_model_usage(
                        mark_error,
                        model_usage,
                    ));
                }
                return Err(AgentRuntimeExecutionFailure::with_model_usage(
                    error,
                    model_usage,
                ));
            }
        };
        self.mark_runtime_events_with_status(&selected_events, AgentInboxEventStatus::Processed)?;
        let remaining_pending_count = self
            .repo
            .list_agent_inbox_events(
                config.agent_profile_id,
                Some(AgentInboxEventStatus::Pending),
                10_000,
            )
            .len() as i32;
        let input_tokens = model_usage.input_tokens;
        let output_tokens = model_usage.output_tokens;
        let model_cost_microusd = model_usage.cost_microusd;
        let pricing_status = model_usage.pricing_status.clone();
        let execution = AgentRuntimeModelExecutionResult {
            plan: response.plan,
            actions,
            approval_requests,
            processed_event_ids: actionable_events.iter().map(|event| event.id).collect(),
            ignored_runtime_generated_event_ids: ignored_runtime_generated_events
                .iter()
                .map(|event| event.id)
                .collect(),
            provider_request_id: response.provider_request_id,
            resolved_model_name: response.resolved_model_name,
            request_count,
            input_tokens,
            output_tokens,
            cost_microusd: model_cost_microusd,
            input_price_microusd_per_million_tokens: config
                .model_input_price_microusd_per_million_tokens,
            output_price_microusd_per_million_tokens: config
                .model_output_price_microusd_per_million_tokens,
            pricing_status: pricing_status.clone(),
        };
        Ok(AgentRuntimeExecutionSuccess {
            processed_event_count: selected_events.len() as i32,
            action_count: (execution.actions.len() + execution.approval_requests.len()) as i32,
            approval_request_count: execution.approval_requests.len() as i32,
            remaining_pending_count,
            model_request_count: request_count,
            model_input_tokens: execution.input_tokens,
            model_output_tokens: execution.output_tokens,
            model_cost_microusd,
            model_input_price_microusd_per_million_tokens: config
                .model_input_price_microusd_per_million_tokens,
            model_output_price_microusd_per_million_tokens: config
                .model_output_price_microusd_per_million_tokens,
            model_pricing_status: pricing_status,
            output_payload: json!({ "model_execution": execution }),
            tick: None,
            model_execution: Some(execution),
        })
    }

    fn validate_agent_runtime_model_plan(
        &self,
        config: &AgentRuntimeConfig,
        context: &AgentRuntimeContextSnapshot,
        plan: &AgentRuntimeModelPlan,
        max_actions: usize,
        max_approval_requests: usize,
    ) -> AppResult<()> {
        let summary = plan.summary.trim();
        if summary.is_empty() || summary.chars().count() > 2_000 {
            return Err(AppError::Validation(
                "runtime model plan summary must contain 1 to 2000 characters".into(),
            ));
        }
        if plan.actions.len() + plan.approval_requests.len() > max_actions {
            return Err(AppError::Validation(format!(
                "runtime model plan requested {} total actions but only {max_actions} are allowed",
                plan.actions.len() + plan.approval_requests.len()
            )));
        }
        if plan.approval_requests.len() > max_approval_requests {
            return Err(AppError::Validation(format!(
                "runtime model plan requested {} approvals but only {max_approval_requests} are allowed",
                plan.approval_requests.len()
            )));
        }
        let mut task_targets = HashSet::new();
        let mut project_status_targets = HashSet::new();
        for action in &plan.actions {
            if !config.allowed_model_actions.contains(&action.tool)
                || !context.allowed_actions.contains(&action.tool)
            {
                return Err(AppError::Unauthorized(format!(
                    "runtime model action is not allowed: {}",
                    action.tool
                )));
            }
            match action.tool.as_str() {
                AGENT_RUNTIME_MODEL_ACTION_MESSAGE_SEND => {
                    let conversation_id = action.conversation_id.ok_or_else(|| {
                        AppError::Validation(
                            "company.chat.message.send requires conversation_id".into(),
                        )
                    })?;
                    if !context.conversations.iter().any(|conversation| {
                        conversation.preview.id == conversation_id
                            && conversation
                                .member_agent_ids
                                .contains(&config.agent_profile_id)
                    }) {
                        return Err(AppError::Unauthorized(
                            "runtime model may only message a visible company conversation".into(),
                        ));
                    }
                    let content = action.content.as_deref().unwrap_or_default().trim();
                    if content.is_empty() || content.chars().count() > 2_000 {
                        return Err(AppError::Validation(
                            "runtime model message content must contain 1 to 2000 characters"
                                .into(),
                        ));
                    }
                }
                AGENT_RUNTIME_MODEL_ACTION_TASK_START_ASSIGNED => {
                    let project_id = action.project_id.ok_or_else(|| {
                        AppError::Validation(
                            "company.project.task.start_assigned requires project_id".into(),
                        )
                    })?;
                    let task_id = action.task_id.ok_or_else(|| {
                        AppError::Validation(
                            "company.project.task.start_assigned requires task_id".into(),
                        )
                    })?;
                    if !task_targets.insert(task_id) {
                        return Err(AppError::Validation(
                            "runtime model plan cannot start the same task twice".into(),
                        ));
                    }
                    if !context.projects.iter().any(|project| {
                        project.project.id == project_id
                            && project.assigned_open_tasks.iter().any(|task| {
                                task.id == task_id
                                    && task.assignee_agent_id == Some(config.agent_profile_id)
                                    && task.status == PROJECT_TASK_STATUS_TODO
                            })
                    }) {
                        return Err(AppError::Unauthorized(
                            "runtime model may only start a visible todo task assigned to itself"
                                .into(),
                        ));
                    }
                }
                AGENT_RUNTIME_MODEL_ACTION_PROJECT_STATUS_UPDATE => {
                    let project_id = action.project_id.ok_or_else(|| {
                        AppError::Validation(
                            "company.project.status.update requires project_id".into(),
                        )
                    })?;
                    if !project_status_targets.insert(project_id) {
                        return Err(AppError::Validation(
                            "runtime model plan cannot update the same project status twice".into(),
                        ));
                    }
                    if !context
                        .projects
                        .iter()
                        .any(|project| project.project.id == project_id)
                    {
                        return Err(AppError::Unauthorized(
                            "runtime model may only update a visible project".into(),
                        ));
                    }
                    let summary = action.summary.as_deref().unwrap_or_default().trim();
                    if summary.is_empty() || summary.chars().count() > 2_000 {
                        return Err(AppError::Validation(
                            "runtime model project summary must contain 1 to 2000 characters"
                                .into(),
                        ));
                    }
                    if !action
                        .progress_percent
                        .is_some_and(|progress| (0..=100).contains(&progress))
                    {
                        return Err(AppError::Validation(
                            "runtime model project progress_percent must be between 0 and 100"
                                .into(),
                        ));
                    }
                }
                _ => {
                    return Err(AppError::Unauthorized(format!(
                        "runtime model action is not supported: {}",
                        action.tool
                    )));
                }
            }
        }
        for approval in &plan.approval_requests {
            if !config
                .approval_required_model_actions
                .contains(&approval.tool)
                || !context.approval_required_actions.contains(&approval.tool)
            {
                return Err(AppError::Unauthorized(format!(
                    "runtime model approval action is not allowed: {}",
                    approval.tool
                )));
            }
            let reason = approval.reason.trim();
            if reason.is_empty() || reason.chars().count() > 500 {
                return Err(AppError::Validation(
                    "runtime model approval reason must contain 1 to 500 characters".into(),
                ));
            }
            match approval.tool.as_str() {
                AGENT_RUNTIME_APPROVAL_ACTION_STAFF_HIRE => {
                    let display_name = approval.display_name.as_deref().unwrap_or_default().trim();
                    let handle = approval.handle.as_deref().unwrap_or_default().trim();
                    if display_name.is_empty() || display_name.chars().count() > 80 {
                        return Err(AppError::Validation(
                            "staff hire approval requires a display_name of 1 to 80 characters"
                                .into(),
                        ));
                    }
                    if handle.is_empty() || handle.chars().count() > 64 {
                        return Err(AppError::Validation(
                            "staff hire approval requires a handle of 1 to 64 characters".into(),
                        ));
                    }
                    if approval.org_unit_id.is_some_and(|org_unit_id| {
                        !context.org_units.iter().any(|org_unit| {
                            org_unit.id == org_unit_id && org_unit.status == "active"
                        })
                    }) {
                        return Err(AppError::Unauthorized(
                            "staff hire approval org unit is outside the company context".into(),
                        ));
                    }
                    if approval
                        .reports_to_membership_id
                        .is_some_and(|membership_id| {
                            membership_id != context.membership.id
                                && !context.coworkers.iter().any(|coworker| {
                                    coworker.membership.id == membership_id
                                        && coworker.membership.employment_status == "active"
                                })
                        })
                    {
                        return Err(AppError::Unauthorized(
                            "staff hire approval reporting manager is outside the active company context"
                                .into(),
                        ));
                    }
                }
                AGENT_RUNTIME_APPROVAL_ACTION_STAFF_SUSPEND
                | AGENT_RUNTIME_APPROVAL_ACTION_STAFF_TERMINATE => {
                    let target_agent_id = approval.target_agent_id.ok_or_else(|| {
                        AppError::Validation("staffing approval requires target_agent_id".into())
                    })?;
                    if target_agent_id == config.agent_profile_id
                        || !context.coworkers.iter().any(|coworker| {
                            coworker.agent_profile.id == target_agent_id
                                && coworker.membership.employment_status != "terminated"
                        })
                    {
                        return Err(AppError::Unauthorized(
                            "staffing approval may only target another visible employed Agent"
                                .into(),
                        ));
                    }
                }
                AGENT_RUNTIME_APPROVAL_ACTION_TASK_REASSIGN => {
                    let project_id = approval.project_id.ok_or_else(|| {
                        AppError::Validation(
                            "task reassignment approval requires project_id".into(),
                        )
                    })?;
                    let task_id = approval.task_id.ok_or_else(|| {
                        AppError::Validation("task reassignment approval requires task_id".into())
                    })?;
                    let assignee_agent_id = approval.assignee_agent_id.ok_or_else(|| {
                        AppError::Validation(
                            "task reassignment approval requires assignee_agent_id".into(),
                        )
                    })?;
                    if !context.projects.iter().any(|project| {
                        project.project.id == project_id
                            && project.open_tasks.iter().any(|task| task.id == task_id)
                            && project.member_agent_ids.contains(&assignee_agent_id)
                    }) {
                        return Err(AppError::Unauthorized(
                            "task reassignment approval must use a visible open task and active project member"
                                .into(),
                        ));
                    }
                }
                _ => {
                    return Err(AppError::Unauthorized(format!(
                        "runtime model approval action is not supported: {}",
                        approval.tool
                    )));
                }
            }
        }
        Ok(())
    }

    fn execute_agent_runtime_model_plan(
        &self,
        config: &AgentRuntimeConfig,
        plan: &AgentRuntimeModelPlan,
    ) -> AppResult<Vec<AutonomyTickAction>> {
        let mut executed = Vec::new();
        for action in &plan.actions {
            match action.tool.as_str() {
                AGENT_RUNTIME_MODEL_ACTION_MESSAGE_SEND => {
                    let message = self.send_company_message_internal(
                        SendCompanyMessageInput {
                            actor_agent_id: config.agent_profile_id,
                            company_id: config.company_id,
                            conversation_id: action.conversation_id.ok_or_else(|| {
                                AppError::Validation("conversation_id is required".into())
                            })?,
                            content: action.content.clone().unwrap_or_default(),
                        },
                        true,
                    )?;
                    executed.push(AutonomyTickAction {
                        action_type: AGENT_RUNTIME_MODEL_ACTION_MESSAGE_SEND.into(),
                        target_ref: Some(format!("conversation:{}", message.conversation_id)),
                        summary: "模型计划已发送公司消息".into(),
                    });
                }
                AGENT_RUNTIME_MODEL_ACTION_TASK_START_ASSIGNED => {
                    let updated =
                        self.update_company_project_task(UpdateCompanyProjectTaskInput {
                            actor_agent_id: config.agent_profile_id,
                            company_id: config.company_id,
                            project_id: action.project_id.ok_or_else(|| {
                                AppError::Validation("project_id is required".into())
                            })?,
                            task_id: action.task_id.ok_or_else(|| {
                                AppError::Validation("task_id is required".into())
                            })?,
                            title: None,
                            description: None,
                            status: Some(PROJECT_TASK_STATUS_IN_PROGRESS.into()),
                            priority: None,
                            assignee_agent_id: None,
                            due_at: None,
                        })?;
                    executed.push(AutonomyTickAction {
                        action_type: AGENT_RUNTIME_MODEL_ACTION_TASK_START_ASSIGNED.into(),
                        target_ref: Some(format!("task:{}", updated.id)),
                        summary: "模型计划已将分配给自己的任务更新为进行中".into(),
                    });
                }
                AGENT_RUNTIME_MODEL_ACTION_PROJECT_STATUS_UPDATE => {
                    let update = self.create_company_project_status_update(
                        CreateCompanyProjectStatusUpdateInput {
                            actor_agent_id: config.agent_profile_id,
                            company_id: config.company_id,
                            project_id: action.project_id.ok_or_else(|| {
                                AppError::Validation("project_id is required".into())
                            })?,
                            summary: action.summary.clone().unwrap_or_default(),
                            progress_percent: action.progress_percent.ok_or_else(|| {
                                AppError::Validation("progress_percent is required".into())
                            })?,
                            blockers: action.blockers.clone(),
                            next_steps: action.next_steps.clone(),
                            project_status: None,
                        },
                    )?;
                    executed.push(AutonomyTickAction {
                        action_type: AGENT_RUNTIME_MODEL_ACTION_PROJECT_STATUS_UPDATE.into(),
                        target_ref: Some(format!("project_status:{}", update.id)),
                        summary: "模型计划已写入正式项目状态".into(),
                    });
                }
                _ => {
                    return Err(AppError::Unauthorized(format!(
                        "runtime model action is not supported: {}",
                        action.tool
                    )));
                }
            }
        }
        Ok(executed)
    }

    fn create_agent_runtime_approval_requests(
        &self,
        config: &AgentRuntimeConfig,
        runtime_run_id: Uuid,
        plan: &AgentRuntimeModelPlan,
    ) -> AppResult<Vec<AgentToolApprovalRequest>> {
        let now = now_utc();
        let expires_at = now + Duration::minutes(i64::from(config.approval_request_ttl_minutes));
        let mut created = Vec::new();
        for approval in &plan.approval_requests {
            let request = AgentToolApprovalRequest {
                id: Uuid::new_v4(),
                company_id: config.company_id,
                approval_source: AGENT_TOOL_APPROVAL_SOURCE_RUNTIME_MODEL.into(),
                runtime_config_id: Some(config.id),
                runtime_run_id: Some(runtime_run_id),
                codex_trigger_run_id: None,
                requested_by_agent_id: config.agent_profile_id,
                tool_name: approval.tool.clone(),
                risk_level: "high".into(),
                reason: approval.reason.trim().to_string(),
                arguments: serde_json::to_value(approval).unwrap_or_else(|_| json!({})),
                status: AGENT_TOOL_APPROVAL_STATUS_PENDING.into(),
                expires_at,
                reviewed_by_human_user_id: None,
                review_note: String::new(),
                reviewed_at: None,
                execution_result: json!({}),
                error_message: None,
                created_at: now,
                updated_at: now,
            };
            self.repo
                .insert_agent_tool_approval_request(request.clone())?;
            created.push(request);
        }
        Ok(created)
    }

    fn mark_runtime_events_with_status(
        &self,
        events: &[AgentInboxEvent],
        status: AgentInboxEventStatus,
    ) -> AppResult<()> {
        let processed_at = now_utc();
        for event in events {
            let mut event = event.clone();
            event.status = status.clone();
            event.processed_at = Some(processed_at);
            self.repo.update_agent_inbox_event(event)?;
        }
        Ok(())
    }

    pub fn list_agent_tool_approvals_for_human(
        &self,
        human_user_id: Uuid,
        company_id: Uuid,
        status: Option<&str>,
        limit: usize,
    ) -> AppResult<Vec<AgentToolApprovalRequest>> {
        self.ensure_human_can_manage_company_runtimes(human_user_id, company_id)?;
        if status.is_some_and(|status| !is_agent_tool_approval_status(status)) {
            return Err(AppError::Validation(
                "unsupported agent tool approval status".into(),
            ));
        }
        self.refresh_and_list_agent_tool_approvals(company_id, status, limit.clamp(1, 200))
    }

    pub fn approve_agent_tool_approval(
        &self,
        input: ReviewAgentToolApprovalInput,
    ) -> AppResult<AgentToolApprovalRequest> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let review_note = normalize_approval_review_note(input.review_note)?;
        let reviewable = self.ensure_agent_tool_approval_is_reviewable(
            input.company_id,
            input.approval_request_id,
        )?;
        if reviewable.approval_source == AGENT_TOOL_APPROVAL_SOURCE_CODEX {
            return self
                .repo
                .claim_agent_tool_approval_request(
                    input.approval_request_id,
                    input.human_user_id,
                    AGENT_TOOL_APPROVAL_STATUS_APPROVED,
                    &review_note,
                    now_utc(),
                )?
                .ok_or_else(|| {
                    AppError::Conflict(
                        "approval request is no longer pending or was claimed by another reviewer"
                            .into(),
                    )
                });
        }
        let mut request = self
            .repo
            .claim_agent_tool_approval_request(
                input.approval_request_id,
                input.human_user_id,
                AGENT_TOOL_APPROVAL_STATUS_EXECUTING,
                &review_note,
                now_utc(),
            )?
            .ok_or_else(|| {
                AppError::Conflict(
                    "approval request is no longer pending or was claimed by another reviewer"
                        .into(),
                )
            })?;
        let now = now_utc();
        match self.execute_agent_tool_approval(&request) {
            Ok(result) => {
                request.status = AGENT_TOOL_APPROVAL_STATUS_EXECUTED.into();
                request.execution_result = result;
                request.error_message = None;
            }
            Err(error) => {
                request.status = AGENT_TOOL_APPROVAL_STATUS_FAILED.into();
                request.error_message = Some(error.to_string());
            }
        }
        request.updated_at = now;
        self.repo
            .update_agent_tool_approval_request(request.clone())?;
        Ok(request)
    }

    pub fn reject_agent_tool_approval(
        &self,
        input: ReviewAgentToolApprovalInput,
    ) -> AppResult<AgentToolApprovalRequest> {
        self.ensure_human_can_manage_company_runtimes(input.human_user_id, input.company_id)?;
        let review_note = normalize_approval_review_note(input.review_note)?;
        self.ensure_agent_tool_approval_is_reviewable(input.company_id, input.approval_request_id)?;
        self.repo
            .claim_agent_tool_approval_request(
                input.approval_request_id,
                input.human_user_id,
                AGENT_TOOL_APPROVAL_STATUS_REJECTED,
                &review_note,
                now_utc(),
            )?
            .ok_or_else(|| {
                AppError::Conflict(
                    "approval request is no longer pending or was claimed by another reviewer"
                        .into(),
                )
            })
    }

    fn refresh_and_list_agent_tool_approvals(
        &self,
        company_id: Uuid,
        status: Option<&str>,
        limit: usize,
    ) -> AppResult<Vec<AgentToolApprovalRequest>> {
        let now = now_utc();
        let pending = self.repo.list_company_agent_tool_approval_requests(
            company_id,
            Some(AGENT_TOOL_APPROVAL_STATUS_PENDING),
            1_000,
        );
        for mut request in pending {
            if request.expires_at <= now {
                request.status = AGENT_TOOL_APPROVAL_STATUS_EXPIRED.into();
                request.updated_at = now;
                self.repo.update_agent_tool_approval_request(request)?;
            }
        }
        Ok(self
            .repo
            .list_company_agent_tool_approval_requests(company_id, status, limit))
    }

    pub fn create_codex_approval_request(
        &self,
        input: CreateCodexApprovalRequestInput,
    ) -> AppResult<AgentToolApprovalRequest> {
        if !matches!(
            input.tool_name.as_str(),
            AGENT_CODEX_APPROVAL_TOOL_COMMAND
                | AGENT_CODEX_APPROVAL_TOOL_FILE_CHANGE
                | AGENT_CODEX_APPROVAL_TOOL_PERMISSIONS
        ) {
            return Err(AppError::Validation(
                "unsupported Codex approval request type".into(),
            ));
        }
        if !matches!(input.risk_level.as_str(), "low" | "medium" | "high") {
            return Err(AppError::Validation(
                "unsupported Codex approval risk level".into(),
            ));
        }
        if !input.arguments.is_object() {
            return Err(AppError::Validation(
                "Codex approval arguments must be an object".into(),
            ));
        }
        let now = now_utc();
        if input.expires_at <= now {
            return Err(AppError::Validation(
                "Codex approval request must expire in the future".into(),
            ));
        }
        let request = AgentToolApprovalRequest {
            id: Uuid::new_v4(),
            company_id: input.company_id,
            approval_source: AGENT_TOOL_APPROVAL_SOURCE_CODEX.into(),
            runtime_config_id: None,
            runtime_run_id: None,
            codex_trigger_run_id: Some(input.codex_trigger_run_id),
            requested_by_agent_id: input.requested_by_agent_id,
            tool_name: input.tool_name,
            risk_level: input.risk_level,
            reason: input.reason.trim().to_string(),
            arguments: input.arguments,
            status: AGENT_TOOL_APPROVAL_STATUS_PENDING.into(),
            expires_at: input.expires_at,
            reviewed_by_human_user_id: None,
            review_note: String::new(),
            reviewed_at: None,
            execution_result: json!({}),
            error_message: None,
            created_at: now,
            updated_at: now,
        };
        self.repo
            .insert_agent_tool_approval_request(request.clone())?;
        Ok(request)
    }

    pub fn get_codex_approval_request_for_runner(
        &self,
        approval_request_id: Uuid,
        codex_trigger_run_id: Uuid,
    ) -> AppResult<AgentToolApprovalRequest> {
        let mut request = self
            .repo
            .get_agent_tool_approval_request(approval_request_id)
            .filter(|request| {
                request.approval_source == AGENT_TOOL_APPROVAL_SOURCE_CODEX
                    && request.codex_trigger_run_id == Some(codex_trigger_run_id)
            })
            .ok_or_else(|| AppError::NotFound("Codex approval request not found".into()))?;
        if request.status == AGENT_TOOL_APPROVAL_STATUS_PENDING && request.expires_at <= now_utc() {
            request.status = AGENT_TOOL_APPROVAL_STATUS_EXPIRED.into();
            request.updated_at = now_utc();
            self.repo
                .update_agent_tool_approval_request(request.clone())?;
        }
        Ok(request)
    }

    fn ensure_agent_tool_approval_is_reviewable(
        &self,
        company_id: Uuid,
        approval_request_id: Uuid,
    ) -> AppResult<AgentToolApprovalRequest> {
        let mut request = self
            .repo
            .get_agent_tool_approval_request(approval_request_id)
            .filter(|request| request.company_id == company_id)
            .ok_or_else(|| AppError::NotFound("agent tool approval request not found".into()))?;
        if request.status != AGENT_TOOL_APPROVAL_STATUS_PENDING {
            return Err(AppError::Conflict(format!(
                "approval request is not pending: {}",
                request.status
            )));
        }
        if request.expires_at <= now_utc() {
            request.status = AGENT_TOOL_APPROVAL_STATUS_EXPIRED.into();
            request.updated_at = now_utc();
            self.repo
                .update_agent_tool_approval_request(request.clone())?;
            return Err(AppError::Conflict("approval request has expired".into()));
        }
        Ok(request)
    }

    fn execute_agent_tool_approval(
        &self,
        request: &AgentToolApprovalRequest,
    ) -> AppResult<serde_json::Value> {
        let proposal: AgentRuntimeModelApprovalRequest =
            serde_json::from_value(request.arguments.clone()).map_err(|error| {
                AppError::Validation(format!("approval request arguments are invalid: {error}"))
            })?;
        if proposal.tool != request.tool_name {
            return Err(AppError::Validation(
                "approval request tool does not match its arguments".into(),
            ));
        }
        match request.tool_name.as_str() {
            AGENT_RUNTIME_APPROVAL_ACTION_STAFF_HIRE => {
                let result = self.hire_company_agent(AgentStaffingHireInput {
                    actor_agent_id: request.requested_by_agent_id,
                    company_id: request.company_id,
                    display_name: proposal.display_name.unwrap_or_default(),
                    handle: proposal.handle.unwrap_or_default(),
                    persona: proposal.persona.unwrap_or_default(),
                    org_unit_id: proposal.org_unit_id,
                    job_title: proposal.job_title,
                    reports_to_membership_id: proposal.reports_to_membership_id,
                    reason: Some(request.reason.clone()),
                    idempotency_key: Some(format!("approval:{}", request.id)),
                })?;
                Ok(serde_json::to_value(result).unwrap_or_default())
            }
            AGENT_RUNTIME_APPROVAL_ACTION_STAFF_SUSPEND => {
                let result = self.suspend_company_agent_as_agent(AgentStaffingStatusInput {
                    actor_agent_id: request.requested_by_agent_id,
                    company_id: request.company_id,
                    target_agent_id: proposal.target_agent_id.ok_or_else(|| {
                        AppError::Validation("target_agent_id is required".into())
                    })?,
                    reason: Some(request.reason.clone()),
                    handoff_plan: proposal.handoff_plan,
                    handoff_agent_id: proposal.handoff_agent_id,
                    idempotency_key: Some(format!("approval:{}", request.id)),
                })?;
                Ok(serde_json::to_value(result).unwrap_or_default())
            }
            AGENT_RUNTIME_APPROVAL_ACTION_STAFF_TERMINATE => {
                let result = self.terminate_company_agent_as_agent(AgentStaffingStatusInput {
                    actor_agent_id: request.requested_by_agent_id,
                    company_id: request.company_id,
                    target_agent_id: proposal.target_agent_id.ok_or_else(|| {
                        AppError::Validation("target_agent_id is required".into())
                    })?,
                    reason: Some(request.reason.clone()),
                    handoff_plan: proposal.handoff_plan,
                    handoff_agent_id: proposal.handoff_agent_id,
                    idempotency_key: Some(format!("approval:{}", request.id)),
                })?;
                Ok(serde_json::to_value(result).unwrap_or_default())
            }
            AGENT_RUNTIME_APPROVAL_ACTION_TASK_REASSIGN => {
                let result = self.update_company_project_task(UpdateCompanyProjectTaskInput {
                    actor_agent_id: request.requested_by_agent_id,
                    company_id: request.company_id,
                    project_id: proposal
                        .project_id
                        .ok_or_else(|| AppError::Validation("project_id is required".into()))?,
                    task_id: proposal
                        .task_id
                        .ok_or_else(|| AppError::Validation("task_id is required".into()))?,
                    title: None,
                    description: None,
                    status: None,
                    priority: None,
                    assignee_agent_id: Some(proposal.assignee_agent_id.ok_or_else(|| {
                        AppError::Validation("assignee_agent_id is required".into())
                    })?),
                    due_at: None,
                })?;
                Ok(serde_json::to_value(result).unwrap_or_default())
            }
            _ => Err(AppError::Unauthorized(
                "approval request tool is unsupported".into(),
            )),
        }
    }

    fn ensure_human_can_manage_company_runtimes(
        &self,
        human_user_id: Uuid,
        company_id: Uuid,
    ) -> AppResult<CompanyHumanMember> {
        self.repo
            .get_company(company_id)
            .filter(|company| company.status == "active")
            .ok_or_else(|| AppError::NotFound("active company not found".into()))?;
        let membership = self
            .repo
            .get_company_human_member(company_id, human_user_id)
            .filter(|membership| membership.status == "active")
            .ok_or_else(|| {
                AppError::Unauthorized("human user is not an active company member".into())
            })?;
        if !matches!(
            membership.role.as_str(),
            COMPANY_ROLE_OWNER | COMPANY_ROLE_ADMIN
        ) {
            return Err(AppError::Unauthorized(
                "company owner or admin role is required to manage agent runtimes".into(),
            ));
        }
        Ok(membership)
    }

