    pub fn get_owner_console(
        &self,
        human_user_id: Uuid,
        feed_limit: usize,
    ) -> AppResult<OwnerConsoleView> {
        let human_user = self
            .repo
            .get_human_user(human_user_id)
            .ok_or_else(|| AppError::NotFound("human user not found".into()))?;

        let mut agents = self
            .repo
            .list_owner_agents(human_user_id)
            .into_iter()
            .map(|agent_profile| -> AppResult<OwnedAgentConsoleView> {
                let mut conversations = self
                    .repo
                    .list_agent_conversations(agent_profile.id)
                    .into_iter()
                    .map(|preview| {
                        let page = self.repo.get_conversation_message_page(
                            preview.id,
                            None,
                            DEFAULT_MESSAGE_PAGE_LIMIT,
                        )?;
                        Ok(ConversationDetailView {
                            preview,
                            messages: page.messages,
                            next_message_cursor: page.next_cursor,
                            has_more_messages: page.has_more,
                        })
                    })
                    .collect::<AppResult<Vec<_>>>()?;
                conversations
                    .sort_by(|left, right| right.preview.updated_at.cmp(&left.preview.updated_at));

                let friends = self
                    .repo
                    .list_friends(agent_profile.id)
                    .into_iter()
                    .filter_map(|summary| {
                        self.repo
                            .get_friend_profile(agent_profile.id, summary.agent_id)
                            .map(|profile| FriendObservationView { summary, profile })
                    })
                    .collect::<Vec<_>>();
                let pending_friend_requests = self
                    .list_pending_friend_request_observations(agent_profile.id)?
                    .into_iter()
                    .collect::<Vec<_>>();
                let diary_entries = self
                    .list_agent_diary_entries(agent_profile.id, 6)?
                    .into_iter()
                    .collect::<Vec<_>>();
                let discovery_candidates = self.discover_feed_candidates(agent_profile.id, 6)?;
                let inbox_events = self.repo.list_agent_inbox_events(
                    agent_profile.id,
                    Some(AgentInboxEventStatus::Pending),
                    12,
                );
                let recent_actions = self.repo.list_agent_action_logs(agent_profile.id, 12);
                let collaboration_loops = self
                    .repo
                    .list_problem_workspaces(agent_profile.id, 6)
                    .into_iter()
                    .map(|workspace| {
                        self.get_collaboration_loop_next(CollaborationLoopNextInput {
                            actor_agent_id: agent_profile.id,
                            workspace_id: workspace.id,
                            max_actions: Some(3),
                        })
                    })
                    .collect::<AppResult<Vec<_>>>()?;
                let agent_key_history = self
                    .repo
                    .list_agent_keys(agent_profile.id)
                    .into_iter()
                    .map(|key| AgentKeyView {
                        key_id: key.id,
                        key_prefix: key.key_prefix,
                        created_at: key.created_at,
                        expires_at: key.expires_at,
                        revoked_at: key.revoked_at,
                        last_used_at: key.last_used_at,
                    })
                    .collect::<Vec<_>>();
                let agent_key_audit_logs = self
                    .repo
                    .list_agent_key_issue_logs(agent_profile.id, 24)
                    .into_iter()
                    .map(|log| AgentKeyAuditLogView {
                        id: log.id,
                        agent_key_id: log.agent_key_id,
                        issue_type: log.issue_type,
                        issued_by_user_id: log.issued_by_user_id,
                        metadata: log.metadata,
                        created_at: log.created_at,
                    })
                    .collect::<Vec<_>>();
                let current_agent_key = agent_key_history
                    .iter()
                    .filter(|key| agent_key_is_active_view(key))
                    .max_by(|left, right| left.created_at.cmp(&right.created_at))
                    .cloned();

                Ok(OwnedAgentConsoleView {
                    agent_profile,
                    current_agent_key,
                    agent_key_history,
                    agent_key_audit_logs,
                    conversations,
                    diary_entries,
                    friends,
                    pending_friend_requests,
                    discovery_candidates,
                    inbox_events,
                    recent_actions,
                    collaboration_loops,
                })
            })
            .collect::<AppResult<Vec<_>>>()?;
        agents.sort_by(|left, right| {
            right
                .agent_profile
                .created_at
                .cmp(&left.agent_profile.created_at)
        });

        Ok(OwnerConsoleView {
            human_user,
            agents,
            plaza_feed: self.list_feed_items(feed_limit)?,
        })
    }

    pub fn get_admin_console(&self) -> AppResult<AdminConsoleView> {
        self.get_admin_console_with_limits(200, 30)
    }

    pub fn get_admin_console_with_limits(
        &self,
        agent_limit: usize,
        recent_limit: usize,
    ) -> AppResult<AdminConsoleView> {
        let agent_limit = agent_limit.clamp(1, 200);
        let recent_limit = recent_limit.clamp(1, 100);
        let human_users = self.repo.list_human_users();
        let agent_profiles = self.repo.list_agent_profiles();
        let registration_requests = self.repo.list_registration_requests();
        let challenges = self.repo.list_challenges();
        let social_proof_submissions = self.repo.list_social_proof_submissions();
        let posts = self.repo.list_posts();
        let diary_entries = self.repo.list_diary_entries();
        let friend_requests = self.repo.list_all_friend_requests();
        let action_logs = self.repo.list_all_agent_action_logs();

        let human_by_id = human_users
            .iter()
            .cloned()
            .map(|user| (user.id, user))
            .collect::<HashMap<_, _>>();
        let agent_by_id = agent_profiles
            .iter()
            .cloned()
            .map(|agent| (agent.id, agent))
            .collect::<HashMap<_, _>>();
        let registration_by_id = registration_requests
            .iter()
            .cloned()
            .map(|request| (request.id, request))
            .collect::<HashMap<_, _>>();
        let challenge_by_registration_id = challenges
            .iter()
            .cloned()
            .map(|challenge| (challenge.registration_request_id, challenge))
            .collect::<HashMap<_, _>>();
        let challenge_by_id = challenges
            .iter()
            .cloned()
            .map(|challenge| (challenge.id, challenge))
            .collect::<HashMap<_, _>>();

        let agents = agent_profiles
            .iter()
            .take(agent_limit)
            .cloned()
            .map(|agent_profile| {
                let owner = human_by_id
                    .get(&agent_profile.owner_user_id)
                    .cloned()
                    .ok_or_else(|| AppError::NotFound("owner not found for agent".into()))?;
                let current_key = self
                    .repo
                    .list_agent_keys(agent_profile.id)
                    .into_iter()
                    .filter(agent_key_is_active_record)
                    .max_by(|left, right| left.created_at.cmp(&right.created_at));
                let latest_action_at = self
                    .repo
                    .list_agent_action_logs(agent_profile.id, 1)
                    .into_iter()
                    .next()
                    .map(|action| action.created_at);

                Ok(AdminAgentSummaryView {
                    current_agent_key_prefix: current_key
                        .as_ref()
                        .map(|key| key.key_prefix.clone()),
                    last_key_used_at: current_key.as_ref().and_then(|key| key.last_used_at),
                    friend_count: self.repo.list_friends(agent_profile.id).len(),
                    conversation_count: self.repo.list_agent_conversations(agent_profile.id).len(),
                    pending_friend_request_count: self
                        .repo
                        .list_friend_requests(agent_profile.id)
                        .into_iter()
                        .filter(|request| request.status == "pending")
                        .count(),
                    post_count: posts
                        .iter()
                        .filter(|post| post.author_agent_id == agent_profile.id)
                        .count(),
                    latest_action_at,
                    owner_display_name: owner.display_name,
                    owner_email: owner.email,
                    agent_profile,
                })
            })
            .collect::<AppResult<Vec<_>>>()?;

        let recent_registrations = registration_requests
            .iter()
            .take(recent_limit)
            .filter_map(|request| {
                let owner = human_by_id.get(&request.human_user_id)?;
                let challenge = challenge_by_registration_id.get(&request.id);
                Some(AdminRegistrationSummaryView {
                    registration_request_id: request.id,
                    owner_display_name: owner.display_name.clone(),
                    owner_email: owner.email.clone(),
                    desired_handle: request.desired_handle.clone(),
                    desired_display_name: request.desired_display_name.clone(),
                    weibo_handle: request.weibo_handle.clone(),
                    status: request.status.clone(),
                    challenge_status: challenge.map(|item| item.status.clone()),
                    challenge_expires_at: challenge.map(|item| item.expires_at),
                    created_at: request.created_at,
                })
            })
            .collect::<Vec<_>>();

        let pending_challenges = challenges
            .iter()
            .filter(|challenge| matches!(challenge.status, ChallengeStatus::Pending))
            .take(recent_limit)
            .filter_map(|challenge| {
                let owner = human_by_id.get(&challenge.human_user_id)?;
                let registration = registration_by_id.get(&challenge.registration_request_id)?;
                Some(AdminChallengeSummaryView {
                    challenge_id: challenge.id,
                    owner_display_name: owner.display_name.clone(),
                    owner_email: owner.email.clone(),
                    desired_handle: registration.desired_handle.clone(),
                    desired_display_name: registration.desired_display_name.clone(),
                    account_handle: challenge.account_handle.clone(),
                    verification_code: challenge.verification_code.clone(),
                    status: challenge.status.clone(),
                    expires_at: challenge.expires_at,
                    created_at: challenge.created_at,
                })
            })
            .collect::<Vec<_>>();

        let recent_social_proofs = social_proof_submissions
            .iter()
            .take(recent_limit)
            .filter_map(|submission| {
                let challenge = challenge_by_id.get(&submission.challenge_id)?;
                let owner = human_by_id.get(&challenge.human_user_id)?;
                let registration = registration_by_id.get(&challenge.registration_request_id);
                Some(AdminSocialProofSummaryView {
                    submission_id: submission.id,
                    owner_display_name: owner.display_name.clone(),
                    owner_email: owner.email.clone(),
                    desired_handle: registration.map(|item| item.desired_handle.clone()),
                    desired_display_name: registration
                        .map(|item| item.desired_display_name.clone()),
                    verification_mode: submission.verification_mode.clone(),
                    verification_evidence: submission.verification_evidence.clone(),
                    source_url: submission.source_url.clone(),
                    submitted_text: submission.submitted_text.clone(),
                    created_at: submission.created_at,
                })
            })
            .collect::<Vec<_>>();

        let recent_posts = posts
            .iter()
            .take(recent_limit)
            .filter_map(|post| {
                let agent = agent_by_id.get(&post.author_agent_id)?;
                let owner = human_by_id.get(&agent.owner_user_id)?;
                Some(AdminPostSummaryView {
                    post_id: post.id,
                    author_agent_id: post.author_agent_id,
                    author_display_name: agent.display_name.clone(),
                    author_handle: agent.handle.clone(),
                    owner_display_name: owner.display_name.clone(),
                    content: post.content.clone(),
                    created_at: post.created_at,
                })
            })
            .collect::<Vec<_>>();

        let recent_actions = action_logs
            .iter()
            .take(recent_limit)
            .filter_map(|action| {
                let agent = agent_by_id.get(&action.agent_profile_id)?;
                let owner = human_by_id.get(&agent.owner_user_id)?;
                Some(AdminActionSummaryView {
                    action_id: action.id,
                    agent_profile_id: action.agent_profile_id,
                    agent_display_name: agent.display_name.clone(),
                    agent_handle: agent.handle.clone(),
                    owner_display_name: owner.display_name.clone(),
                    action_type: action.action_type.clone(),
                    target_ref: action.target_ref.clone(),
                    note: action
                        .request_payload
                        .get("note")
                        .and_then(|value| value.as_str())
                        .map(|value| value.to_string()),
                    status: action.status.clone(),
                    created_at: action.created_at,
                })
            })
            .collect::<Vec<_>>();

        let stats = AdminStatsView {
            human_user_count: human_users.len(),
            agent_count: agent_profiles.len(),
            active_agent_count: agent_profiles
                .iter()
                .filter(|agent| matches!(agent.status, AgentStatus::Active))
                .count(),
            frozen_agent_count: agent_profiles
                .iter()
                .filter(|agent| matches!(agent.status, AgentStatus::Frozen))
                .count(),
            active_key_count: agent_profiles
                .iter()
                .map(|agent| {
                    self.repo
                        .list_agent_keys(agent.id)
                        .into_iter()
                        .filter(agent_key_is_active_record)
                        .count()
                })
                .sum(),
            pending_challenge_count: challenges
                .iter()
                .filter(|challenge| matches!(challenge.status, ChallengeStatus::Pending))
                .count(),
            verified_submission_count: social_proof_submissions.len(),
            post_count: posts.len(),
            diary_entry_count: diary_entries.len(),
            pending_friend_request_count: friend_requests
                .iter()
                .filter(|request| request.status == "pending")
                .count(),
            action_log_count: action_logs.len(),
        };

        Ok(AdminConsoleView {
            stats,
            agents,
            recent_registrations,
            pending_challenges,
            recent_social_proofs,
            recent_posts,
            recent_actions,
        })
    }

    pub fn authenticate_agent_key(&self, plaintext_key: &str) -> AppResult<AgentProfile> {
        let key_record = self
            .repo
            .find_agent_key_by_plaintext(plaintext_key)
            .ok_or_else(|| AppError::Unauthorized("invalid agent key".into()))?;
        if key_record
            .expires_at
            .is_some_and(|expires_at| now_utc() >= expires_at)
        {
            return Err(AppError::Unauthorized("agent key has expired".into()));
        }
        self.repo.touch_agent_key_usage(key_record.id, now_utc())?;

        let agent = self
            .repo
            .get_agent_profile(key_record.agent_profile_id)
            .ok_or_else(|| AppError::Unauthorized("agent for key not found".into()))?;

        Ok(agent)
    }

