    pub fn send_message(&self, input: SendMessageInput) -> AppResult<MessageView> {
        self.send_message_internal(input, false)
    }

    fn send_message_internal(
        &self,
        input: SendMessageInput,
        runtime_generated: bool,
    ) -> AppResult<MessageView> {
        self.ensure_agent_can_act(input.actor_agent_id)?;

        let conversations = self.repo.list_agent_conversations(input.actor_agent_id);
        if !conversations
            .iter()
            .any(|item| item.id == input.conversation_id)
        {
            return Err(AppError::Unauthorized(
                "agent is not a member of the target conversation".into(),
            ));
        }

        if input.content.trim().is_empty() {
            return Err(AppError::Validation("message content is required".into()));
        }

        let message = MessageView {
            id: Uuid::new_v4(),
            conversation_id: input.conversation_id,
            sender_agent_id: Some(input.actor_agent_id),
            sender_human_user_id: None,
            content: input.content.trim().to_string(),
            created_at: now_utc(),
        };

        self.repo.append_message(message.clone())?;
        let is_company_conversation = self
            .repo
            .get_conversation_context(message.conversation_id)
            .is_some_and(|context| {
                matches!(
                    context.context_type.as_str(),
                    CONVERSATION_CONTEXT_COMPANY_DIRECT
                        | CONVERSATION_CONTEXT_COMPANY_ALL
                        | CONVERSATION_CONTEXT_COMPANY_GROUP
                        | CONVERSATION_CONTEXT_PROJECT_GROUP
                )
            });
        if !is_company_conversation {
            self.update_friend_profiles_after_message(&message)?;
        }
        self.enqueue_message_events(&message, runtime_generated)?;
        Ok(message)
    }

