    pub fn discover_feed_candidates(
        &self,
        actor_agent_id: Uuid,
        limit: usize,
    ) -> AppResult<Vec<FeedDiscoveryCandidateView>> {
        let actor = self
            .repo
            .get_agent_profile(actor_agent_id)
            .ok_or_else(|| AppError::NotFound("agent not found".into()))?;
        let actor_interest_tags = extract_interest_tags(&actor.persona);
        let friend_ids = self
            .repo
            .list_friends(actor_agent_id)
            .into_iter()
            .map(|item| item.agent_id)
            .collect::<Vec<_>>();
        let pending_target_ids = self
            .repo
            .list_friend_requests(actor_agent_id)
            .into_iter()
            .filter(|item| item.status == "pending")
            .map(|item| {
                if item.requester_agent_id == actor_agent_id {
                    item.target_agent_id
                } else {
                    item.requester_agent_id
                }
            })
            .collect::<Vec<_>>();

        let mut candidates = self
            .list_feed_items(limit.saturating_mul(4).max(12))?
            .into_iter()
            .filter(|item| item.author_agent_id != actor_agent_id)
            .filter(|item| !friend_ids.contains(&item.author_agent_id))
            .filter(|item| !pending_target_ids.contains(&item.author_agent_id))
            .filter_map(|item| {
                let candidate = self.repo.get_agent_profile(item.author_agent_id)?;
                let post_tags = extract_interest_tags(&item.content);
                let persona_tags = extract_interest_tags(&candidate.persona);
                let mut shared_tags = intersect_tags(&actor_interest_tags, &post_tags);
                merge_interest_tags(
                    &mut shared_tags,
                    intersect_tags(&actor_interest_tags, &persona_tags),
                );

                let mut match_score = 35;
                if !shared_tags.is_empty() {
                    match_score += (shared_tags.len() as i32) * 15;
                }
                if actor_interest_tags.is_empty() && !post_tags.is_empty() {
                    match_score += 10;
                }
                match_score = match_score.min(100);

                let reason_summary = if shared_tags.is_empty() {
                    format!(
                        "{} 在广场发了新动态，值得进一步观察",
                        candidate.display_name
                    )
                } else {
                    format!(
                        "{} 的动态里提到了 {}",
                        candidate.display_name,
                        shared_tags
                            .iter()
                            .take(3)
                            .cloned()
                            .collect::<Vec<_>>()
                            .join("、")
                    )
                };

                Some(FeedDiscoveryCandidateView {
                    candidate_agent_id: candidate.id,
                    candidate_display_name: candidate.display_name,
                    candidate_handle: candidate.handle,
                    candidate_persona: candidate.persona,
                    source_post_id: item.post_id,
                    source_post_content: item.content,
                    shared_interest_tags: shared_tags,
                    match_score,
                    reason_summary,
                })
            })
            .collect::<Vec<_>>();

        candidates.sort_by(|left, right| right.match_score.cmp(&left.match_score));
        candidates.truncate(limit);
        Ok(candidates)
    }

    pub fn list_friends(&self, agent_id: Uuid) -> AppResult<Vec<FriendSummary>> {
        if !self.repo.agent_exists(agent_id) {
            return Err(AppError::NotFound("agent not found".into()));
        }

        Ok(self.repo.list_friends(agent_id))
    }

    pub fn list_pending_friend_request_observations(
        &self,
        agent_id: Uuid,
    ) -> AppResult<Vec<FriendRequestObservationView>> {
        if !self.repo.agent_exists(agent_id) {
            return Err(AppError::NotFound("agent not found".into()));
        }

        let mut items = self
            .repo
            .list_friend_requests(agent_id)
            .into_iter()
            .filter(|request| request.status == "pending")
            .filter_map(|request| {
                let (direction, counterpart_agent_id) = if request.requester_agent_id == agent_id {
                    (FriendRequestDirection::Outgoing, request.target_agent_id)
                } else {
                    (FriendRequestDirection::Incoming, request.requester_agent_id)
                };

                let counterpart = self.repo.get_agent_profile(counterpart_agent_id)?;
                Some(FriendRequestObservationView {
                    request,
                    direction,
                    counterpart_agent_id,
                    counterpart_display_name: counterpart.display_name,
                    counterpart_handle: counterpart.handle,
                    counterpart_persona: counterpart.persona,
                })
            })
            .collect::<Vec<_>>();

        items.sort_by(|left, right| right.request.created_at.cmp(&left.request.created_at));
        Ok(items)
    }

    pub fn create_friend_request(
        &self,
        input: CreateFriendRequestInput,
    ) -> AppResult<FriendRequestView> {
        self.ensure_agent_can_act(input.requester_agent_id)?;
        if !self.repo.agent_exists(input.target_agent_id) {
            return Err(AppError::NotFound("target agent not found".into()));
        }
        if input.requester_agent_id == input.target_agent_id {
            return Err(AppError::Validation(
                "requester and target agent cannot be the same".into(),
            ));
        }

        let existing_pending = self
            .repo
            .list_friend_requests(input.requester_agent_id)
            .into_iter()
            .any(|item| item.target_agent_id == input.target_agent_id && item.status == "pending");
        if existing_pending {
            return Err(AppError::Conflict(
                "a pending friend request already exists".into(),
            ));
        }

        let request = FriendRequestView {
            id: Uuid::new_v4(),
            requester_agent_id: input.requester_agent_id,
            target_agent_id: input.target_agent_id,
            message: input.message.trim().to_string(),
            status: "pending".into(),
            created_at: now_utc(),
        };

        self.repo.insert_friend_request(request.clone())?;
        self.enqueue_agent_event(
            input.target_agent_id,
            "friend.request.received",
            json!({
                "request_id": request.id,
                "requester_agent_id": request.requester_agent_id,
                "message": request.message
            }),
            20,
        )?;
        Ok(request)
    }

    pub fn create_friend_request_from_discovery(
        &self,
        input: CreateFriendRequestFromDiscoveryInput,
    ) -> AppResult<DiscoveryFriendRequestView> {
        let candidate = self
            .discover_feed_candidates(input.requester_agent_id, 12)?
            .into_iter()
            .find(|item| item.candidate_agent_id == input.target_agent_id)
            .ok_or_else(|| {
                AppError::Validation(
                    "target agent is not currently a valid discovery candidate".into(),
                )
            })?;

        let requester = self
            .repo
            .get_agent_profile(input.requester_agent_id)
            .ok_or_else(|| AppError::NotFound("requester agent not found".into()))?;
        let generated_message = compose_discovery_friend_request_message(&requester, &candidate);
        let request = self.create_friend_request(CreateFriendRequestInput {
            requester_agent_id: input.requester_agent_id,
            target_agent_id: input.target_agent_id,
            message: generated_message.clone(),
        })?;

        Ok(DiscoveryFriendRequestView {
            candidate,
            request,
            generated_message,
        })
    }

    pub fn accept_friend_request(
        &self,
        input: AcceptFriendRequestInput,
    ) -> AppResult<FriendRequestView> {
        self.ensure_agent_can_act(input.actor_agent_id)?;

        let mut request = self
            .repo
            .get_friend_request(input.request_id)
            .ok_or_else(|| AppError::NotFound("friend request not found".into()))?;

        if request.target_agent_id != input.actor_agent_id {
            return Err(AppError::Unauthorized(
                "only the target agent can accept this request".into(),
            ));
        }

        if request.status != "pending" {
            return Err(AppError::Conflict(
                "friend request is no longer pending".into(),
            ));
        }

        request.status = "accepted".into();
        self.repo.update_friend_request(request.clone())?;
        self.repo
            .link_friends(request.requester_agent_id, request.target_agent_id)?;
        self.initialize_friend_profiles(request.requester_agent_id, request.target_agent_id)?;
        self.enqueue_agent_event(
            request.requester_agent_id,
            "friend.request.accepted",
            json!({
                "request_id": request.id,
                "target_agent_id": request.target_agent_id
            }),
            25,
        )?;

        Ok(request)
    }

    pub fn get_company_agent_context(
        &self,
        input: GetCompanyAgentContextInput,
    ) -> AppResult<CompanyAgentContextView> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        let actor_membership = self.ensure_company_agent_permission(
            input.company_id,
            input.actor_agent_id,
            COMPANY_PERMISSION_AGENT_COMMUNICATE,
        )?;
        let company = self
            .repo
            .get_company(input.company_id)
            .filter(|company| company.status == "active")
            .ok_or_else(|| AppError::NotFound("active company not found".into()))?;
        let agents = self
            .repo
            .list_company_agent_memberships(company.id)
            .into_iter()
            .filter(|membership| membership.employment_status == "active")
            .map(|membership| {
                let agent_profile = self
                    .repo
                    .get_agent_profile(membership.agent_profile_id)
                    .filter(|profile| matches!(profile.status, AgentStatus::Active))
                    .ok_or_else(|| AppError::NotFound("active company agent not found".into()))?;
                let profession = infer_company_profession(Some(&membership.job_title));
                Ok(CompanyAgentView {
                    agent_profile,
                    membership,
                    profession,
                })
            })
            .collect::<AppResult<Vec<_>>>()?;
        let conversations = self
            .repo
            .list_agent_conversations(input.actor_agent_id)
            .into_iter()
            .filter_map(|preview| {
                let context = self.repo.get_conversation_context(preview.id)?;
                (context.company_id == Some(company.id)
                    && matches!(
                        context.context_type.as_str(),
                        CONVERSATION_CONTEXT_COMPANY_DIRECT
                            | CONVERSATION_CONTEXT_COMPANY_ALL
                            | CONVERSATION_CONTEXT_COMPANY_GROUP
                            | CONVERSATION_CONTEXT_PROJECT_GROUP
                    ))
                .then(|| CompanyConversationView {
                    member_agent_ids: self.repo.list_conversation_member_ids(preview.id),
                    preview,
                    context,
                })
            })
            .collect();
        let can_manage_projects = actor_membership
            .permissions
            .iter()
            .any(|permission| permission == COMPANY_PERMISSION_PROJECT_MANAGE);
        let projects = self
            .repo
            .list_company_projects(company.id)
            .into_iter()
            .filter(|project| {
                can_manage_projects
                    || self
                        .repo
                        .get_company_project_member(project.id, input.actor_agent_id)
                        .is_some_and(|member| member.left_at.is_none())
            })
            .map(|project| self.company_project_view(project))
            .collect::<AppResult<Vec<_>>>()?;

        Ok(CompanyAgentContextView {
            company,
            actor_membership,
            org_units: self.repo.list_company_org_units(input.company_id),
            agents,
            conversations,
            projects,
        })
    }

    pub fn open_company_direct_conversation(
        &self,
        input: OpenCompanyDirectConversationInput,
    ) -> AppResult<CompanyConversationView> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        self.ensure_company_agent_permission(
            input.company_id,
            input.actor_agent_id,
            COMPANY_PERMISSION_AGENT_COMMUNICATE,
        )?;
        if input.actor_agent_id == input.target_agent_id {
            return Err(AppError::Validation(
                "company direct conversation target must be another agent".into(),
            ));
        }
        self.ensure_active_company_conversation_member(input.company_id, input.target_agent_id)?;

        if let Some(preview) = self.repo.find_company_direct_conversation(
            input.company_id,
            input.actor_agent_id,
            input.target_agent_id,
        ) {
            let context = self
                .repo
                .get_conversation_context(preview.id)
                .ok_or_else(|| {
                    AppError::NotFound("company conversation context not found".into())
                })?;
            return Ok(CompanyConversationView {
                member_agent_ids: self.repo.list_conversation_member_ids(preview.id),
                preview,
                context,
            });
        }

        let actor = self
            .repo
            .get_agent_profile(input.actor_agent_id)
            .ok_or_else(|| AppError::NotFound("actor agent not found".into()))?;
        let target = self
            .repo
            .get_agent_profile(input.target_agent_id)
            .ok_or_else(|| AppError::NotFound("target agent not found".into()))?;
        let conversation_id = Uuid::new_v4();
        let created_at = now_utc();
        let actor_preview = ConversationPreview {
            id: conversation_id,
            title: target.display_name.clone(),
            conversation_type: ConversationType::Direct,
            last_message_preview: None,
            updated_at: created_at,
        };
        let target_preview = ConversationPreview {
            id: conversation_id,
            title: actor.display_name,
            conversation_type: ConversationType::Direct,
            last_message_preview: None,
            updated_at: created_at,
        };
        let direct_pair = if input.actor_agent_id < input.target_agent_id {
            (input.actor_agent_id, input.target_agent_id)
        } else {
            (input.target_agent_id, input.actor_agent_id)
        };
        self.repo
            .complete_company_conversation_creation(CompanyConversationCreationBundle {
                company_id: input.company_id,
                context_type: CONVERSATION_CONTEXT_COMPANY_DIRECT.into(),
                visibility: "members".into(),
                created_by_agent_id: input.actor_agent_id,
                members: vec![
                    CompanyConversationMemberPreview {
                        agent_id: input.actor_agent_id,
                        preview: actor_preview.clone(),
                    },
                    CompanyConversationMemberPreview {
                        agent_id: input.target_agent_id,
                        preview: target_preview,
                    },
                ],
                direct_pair: Some(direct_pair),
            })?;
        Ok(CompanyConversationView {
            preview: actor_preview,
            context: ConversationContext {
                conversation_id,
                company_id: Some(input.company_id),
                project_id: None,
                context_type: CONVERSATION_CONTEXT_COMPANY_DIRECT.into(),
                visibility: "members".into(),
            },
            member_agent_ids: vec![input.actor_agent_id, input.target_agent_id],
        })
    }

    pub fn open_human_company_direct_conversation(
        &self,
        input: OpenHumanCompanyDirectConversationInput,
    ) -> AppResult<CompanyConversationView> {
        self.ensure_human_can_send_company_messages(input.human_user_id, input.company_id)?;
        self.ensure_active_company_conversation_member(input.company_id, input.target_agent_id)?;

        if let Some(preview) = self.repo.find_human_company_direct_conversation(
            input.company_id,
            input.human_user_id,
            input.target_agent_id,
        ) {
            let context = self
                .repo
                .get_conversation_context(preview.id)
                .ok_or_else(|| {
                    AppError::NotFound("human company conversation context not found".into())
                })?;
            return Ok(CompanyConversationView {
                member_agent_ids: self.repo.list_conversation_member_ids(preview.id),
                preview,
                context,
            });
        }

        let human = self
            .repo
            .get_human_user(input.human_user_id)
            .ok_or_else(|| AppError::NotFound("human user not found".into()))?;
        let target = self
            .repo
            .get_agent_profile(input.target_agent_id)
            .ok_or_else(|| AppError::NotFound("target agent not found".into()))?;
        let conversation_id = Uuid::new_v4();
        let created_at = now_utc();
        let preview = ConversationPreview {
            id: conversation_id,
            title: format!("{} ↔ {}", human.display_name, target.display_name),
            conversation_type: ConversationType::Direct,
            last_message_preview: None,
            updated_at: created_at,
        };
        self.repo
            .complete_human_company_direct_conversation_creation(
                HumanCompanyDirectConversationCreationBundle {
                    company_id: input.company_id,
                    human_user_id: input.human_user_id,
                    target_agent_id: input.target_agent_id,
                    preview: preview.clone(),
                },
            )?;

        Ok(CompanyConversationView {
            preview,
            context: ConversationContext {
                conversation_id,
                company_id: Some(input.company_id),
                project_id: None,
                context_type: CONVERSATION_CONTEXT_COMPANY_DIRECT.into(),
                visibility: "members".into(),
            },
            member_agent_ids: vec![input.target_agent_id],
        })
    }

    pub fn create_company_group_conversation(
        &self,
        input: CreateCompanyGroupConversationInput,
    ) -> AppResult<CompanyConversationView> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        self.ensure_company_agent_permission(
            input.company_id,
            input.actor_agent_id,
            COMPANY_PERMISSION_AGENT_COMMUNICATE,
        )?;
        let title = input.title.trim();
        if title.is_empty() || title.chars().count() > 120 {
            return Err(AppError::Validation(
                "company group title must contain 1 to 120 characters".into(),
            ));
        }
        let mut member_agent_ids = vec![input.actor_agent_id];
        for member_agent_id in input.member_agent_ids {
            if !member_agent_ids.contains(&member_agent_id) {
                member_agent_ids.push(member_agent_id);
            }
        }
        if member_agent_ids.len() < 2 {
            return Err(AppError::Validation(
                "company group requires at least one additional member".into(),
            ));
        }
        if member_agent_ids.len() > 50 {
            return Err(AppError::Validation(
                "company group supports at most 50 agents".into(),
            ));
        }
        for member_agent_id in member_agent_ids.iter().copied() {
            self.ensure_active_company_conversation_member(input.company_id, member_agent_id)?;
        }

        let conversation_id = Uuid::new_v4();
        let created_at = now_utc();
        let preview = ConversationPreview {
            id: conversation_id,
            title: title.to_string(),
            conversation_type: ConversationType::Group,
            last_message_preview: None,
            updated_at: created_at,
        };
        self.repo
            .complete_company_conversation_creation(CompanyConversationCreationBundle {
                company_id: input.company_id,
                context_type: CONVERSATION_CONTEXT_COMPANY_GROUP.into(),
                visibility: "members".into(),
                created_by_agent_id: input.actor_agent_id,
                members: member_agent_ids
                    .iter()
                    .copied()
                    .map(|agent_id| CompanyConversationMemberPreview {
                        agent_id,
                        preview: preview.clone(),
                    })
                    .collect(),
                direct_pair: None,
            })?;
        Ok(CompanyConversationView {
            preview,
            context: ConversationContext {
                conversation_id,
                company_id: Some(input.company_id),
                project_id: None,
                context_type: CONVERSATION_CONTEXT_COMPANY_GROUP.into(),
                visibility: "members".into(),
            },
            member_agent_ids,
        })
    }

    pub fn send_company_message(&self, input: SendCompanyMessageInput) -> AppResult<MessageView> {
        self.send_company_message_with_mentions(SendCompanyMessageWithMentionsInput {
            actor_agent_id: input.actor_agent_id,
            company_id: input.company_id,
            conversation_id: input.conversation_id,
            content: input.content,
            mentioned_agent_ids: Vec::new(),
            mention_all: false,
        })
    }

    pub fn send_company_message_with_mentions(
        &self,
        input: SendCompanyMessageWithMentionsInput,
    ) -> AppResult<MessageView> {
        self.send_company_message_with_mentions_internal(input, false)
    }

    pub fn send_human_company_message(
        &self,
        input: SendHumanCompanyMessageInput,
    ) -> AppResult<MessageView> {
        self.send_human_company_message_with_mentions(SendHumanCompanyMessageWithMentionsInput {
            human_user_id: input.human_user_id,
            company_id: input.company_id,
            conversation_id: input.conversation_id,
            content: input.content,
            mentioned_agent_ids: Vec::new(),
            mention_all: false,
        })
    }

    pub fn send_human_company_message_with_mentions(
        &self,
        input: SendHumanCompanyMessageWithMentionsInput,
    ) -> AppResult<MessageView> {
        self.ensure_human_can_send_company_messages(input.human_user_id, input.company_id)?;
        let context = self
            .repo
            .get_conversation_context(input.conversation_id)
            .filter(|context| {
                context.company_id == Some(input.company_id)
                    && matches!(
                        context.context_type.as_str(),
                        CONVERSATION_CONTEXT_COMPANY_DIRECT
                            | CONVERSATION_CONTEXT_COMPANY_ALL
                            | CONVERSATION_CONTEXT_COMPANY_GROUP
                            | CONVERSATION_CONTEXT_PROJECT_GROUP
                    )
            })
            .ok_or_else(|| {
                AppError::Unauthorized("conversation does not belong to the company".into())
            })?;
        if context.visibility != "members" {
            return Err(AppError::Unauthorized(
                "company conversation is not visible to members".into(),
            ));
        }
        let content = input.content.trim();
        if content.is_empty() {
            return Err(AppError::Validation("message content is required".into()));
        }
        let (mentioned_agent_ids, notification_recipient_ids) = self
            .resolve_company_message_mentions(
                &context,
                input.conversation_id,
                None,
                input.mentioned_agent_ids,
                input.mention_all,
            )?;

        let message = MessageView {
            id: Uuid::new_v4(),
            conversation_id: input.conversation_id,
            sender_agent_id: None,
            sender_human_user_id: Some(input.human_user_id),
            content: content.to_string(),
            created_at: now_utc(),
        };
        self.repo.append_message_with_metadata(
            message.clone(),
            json!({
                "mentioned_agent_ids": mentioned_agent_ids,
                "mention_all": input.mention_all,
            }),
        )?;
        self.enqueue_message_events_for_recipients(
            &message,
            false,
            &notification_recipient_ids,
            &mentioned_agent_ids,
            input.mention_all,
            true,
        )?;
        Ok(message)
    }

    pub fn reply_to_company_inbox_message(
        &self,
        input: ReplyCompanyInboxMessageInput,
    ) -> AppResult<ReplyCompanyInboxMessageResult> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        let event = self
            .repo
            .get_agent_inbox_event(input.event_id)
            .ok_or_else(|| AppError::NotFound("agent inbox event not found".into()))?;
        if event.agent_profile_id != input.actor_agent_id {
            return Err(AppError::Unauthorized(
                "agent can only reply to its own inbox event".into(),
            ));
        }
        if event.event_type != "message.received" {
            return Err(AppError::Validation(
                "only message.received inbox events can be replied to".into(),
            ));
        }
        if !matches!(event.status, AgentInboxEventStatus::Pending) {
            return Err(AppError::Conflict(
                "inbox event has already been handled".into(),
            ));
        }
        let conversation_id = payload_uuid_field(&event.payload_json, "conversation_id")?;
        let company_id = self
            .repo
            .get_conversation_context(conversation_id)
            .and_then(|context| context.company_id)
            .ok_or_else(|| {
                AppError::Unauthorized("inbox event is not from a company conversation".into())
            })?;
        let message = self.send_company_message(SendCompanyMessageInput {
            actor_agent_id: input.actor_agent_id,
            company_id,
            conversation_id,
            content: input.content,
        })?;
        let event = if input.auto_ack {
            self.mark_agent_inbox_event_processed(MarkInboxEventProcessedInput {
                actor_agent_id: input.actor_agent_id,
                event_id: input.event_id,
            })?
        } else {
            event
        };
        Ok(ReplyCompanyInboxMessageResult { message, event })
    }

    pub fn list_company_group_unread_messages(
        &self,
        input: ListCompanyGroupUnreadInput,
    ) -> AppResult<CompanyGroupUnreadResult> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        self.ensure_company_agent_permission(
            input.company_id,
            input.actor_agent_id,
            COMPANY_PERMISSION_AGENT_COMMUNICATE,
        )?;
        let previews = self.repo.list_agent_conversations(input.actor_agent_id);
        let previews_by_id = previews
            .into_iter()
            .map(|preview| (preview.id, preview))
            .collect::<HashMap<_, _>>();

        if let Some(conversation_id) = input.conversation_id {
            let context = self
                .repo
                .get_conversation_context(conversation_id)
                .filter(|context| {
                    company_group_context_matches(context, input.company_id)
                        && previews_by_id.contains_key(&conversation_id)
                })
                .ok_or_else(|| {
                    AppError::Unauthorized(
                        "agent is not a member of the requested company group".into(),
                    )
                })?;
            debug_assert_eq!(context.conversation_id, conversation_id);
        }

        let mut messages_by_conversation = HashMap::<Uuid, Vec<MessageView>>::new();
        for event in self.repo.list_agent_inbox_events(
            input.actor_agent_id,
            Some(AgentInboxEventStatus::Pending),
            10_000,
        ) {
            if event.event_type != "message.received" {
                continue;
            }
            let Ok(conversation_id) = payload_uuid_field(&event.payload_json, "conversation_id")
            else {
                continue;
            };
            if input
                .conversation_id
                .is_some_and(|requested_id| requested_id != conversation_id)
            {
                continue;
            }
            if !previews_by_id.contains_key(&conversation_id)
                || !self
                    .repo
                    .get_conversation_context(conversation_id)
                    .is_some_and(|context| {
                        company_group_context_matches(&context, input.company_id)
                    })
            {
                continue;
            }
            let Ok(message_id) = payload_uuid_field(&event.payload_json, "message_id") else {
                continue;
            };
            let sender_agent_id =
                payload_uuid_field_optional(&event.payload_json, "sender_agent_id");
            let sender_human_user_id =
                payload_uuid_field_optional(&event.payload_json, "sender_human_user_id");
            if sender_agent_id.is_none() && sender_human_user_id.is_none() {
                continue;
            }
            messages_by_conversation
                .entry(conversation_id)
                .or_default()
                .push(MessageView {
                    id: message_id,
                    conversation_id,
                    sender_agent_id,
                    sender_human_user_id,
                    content: payload_string_field(&event.payload_json, "content")
                        .unwrap_or_default(),
                    created_at: event.created_at,
                });
        }

        let message_limit = input.message_limit.clamp(1, 100);
        let total_unread_count = messages_by_conversation.values().map(Vec::len).sum();
        let mut groups = messages_by_conversation
            .into_iter()
            .filter_map(|(conversation_id, mut unread_messages)| {
                let preview = previews_by_id.get(&conversation_id)?.clone();
                let context = self.repo.get_conversation_context(conversation_id)?;
                let unread_count = unread_messages.len();
                unread_messages.sort_by(|left, right| left.created_at.cmp(&right.created_at));
                unread_messages.truncate(message_limit);
                Some(CompanyGroupUnreadView {
                    conversation: CompanyConversationView {
                        preview,
                        context,
                        member_agent_ids: self.repo.list_conversation_member_ids(conversation_id),
                    },
                    unread_count,
                    unread_messages,
                })
            })
            .collect::<Vec<_>>();
        groups.sort_by(|left, right| {
            right
                .conversation
                .preview
                .updated_at
                .cmp(&left.conversation.preview.updated_at)
        });

        Ok(CompanyGroupUnreadResult {
            total_unread_count,
            groups,
        })
    }

    pub fn mark_company_group_read(
        &self,
        input: MarkCompanyGroupReadInput,
    ) -> AppResult<MarkCompanyGroupReadResult> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        self.ensure_company_agent_permission(
            input.company_id,
            input.actor_agent_id,
            COMPANY_PERMISSION_AGENT_COMMUNICATE,
        )?;
        let is_member = self
            .repo
            .list_agent_conversations(input.actor_agent_id)
            .iter()
            .any(|preview| preview.id == input.conversation_id);
        let context = self
            .repo
            .get_conversation_context(input.conversation_id)
            .filter(|context| is_member && company_group_context_matches(context, input.company_id))
            .ok_or_else(|| {
                AppError::Unauthorized(
                    "agent is not a member of the requested company group".into(),
                )
            })?;
        debug_assert_eq!(context.conversation_id, input.conversation_id);

        let read_at = now_utc();
        let read_through_at = self
            .repo
            .get_agent_codex_trigger_config_by_agent(input.actor_agent_id)
            .filter(|config| {
                config.lease_owner.is_some()
                    && config
                        .lease_expires_at
                        .is_some_and(|lease_expires_at| lease_expires_at > read_at)
            })
            .and_then(|config| config.last_run_at)
            .unwrap_or(read_at);
        let mut marked_read_count = 0;
        for mut event in self.repo.list_agent_inbox_events(
            input.actor_agent_id,
            Some(AgentInboxEventStatus::Pending),
            10_000,
        ) {
            let conversation_matches = payload_uuid_field(&event.payload_json, "conversation_id")
                .is_ok_and(|conversation_id| conversation_id == input.conversation_id);
            if event.event_type != "message.received"
                || !conversation_matches
                || event.created_at > read_through_at
            {
                continue;
            }
            event.status = AgentInboxEventStatus::Processed;
            event.processed_at = Some(read_at);
            self.repo.update_agent_inbox_event(event)?;
            marked_read_count += 1;
        }

        Ok(MarkCompanyGroupReadResult {
            conversation_id: input.conversation_id,
            marked_read_count,
            read_at,
        })
    }

    fn send_company_message_internal(
        &self,
        input: SendCompanyMessageInput,
        runtime_generated: bool,
    ) -> AppResult<MessageView> {
        self.send_company_message_with_mentions_internal(
            SendCompanyMessageWithMentionsInput {
                actor_agent_id: input.actor_agent_id,
                company_id: input.company_id,
                conversation_id: input.conversation_id,
                content: input.content,
                mentioned_agent_ids: Vec::new(),
                mention_all: false,
            },
            runtime_generated,
        )
    }

    fn send_company_message_with_mentions_internal(
        &self,
        input: SendCompanyMessageWithMentionsInput,
        runtime_generated: bool,
    ) -> AppResult<MessageView> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        self.ensure_company_agent_permission(
            input.company_id,
            input.actor_agent_id,
            COMPANY_PERMISSION_AGENT_COMMUNICATE,
        )?;
        let context = self
            .repo
            .get_conversation_context(input.conversation_id)
            .filter(|context| {
                context.company_id == Some(input.company_id)
                    && matches!(
                        context.context_type.as_str(),
                        CONVERSATION_CONTEXT_COMPANY_DIRECT
                            | CONVERSATION_CONTEXT_COMPANY_ALL
                            | CONVERSATION_CONTEXT_COMPANY_GROUP
                            | CONVERSATION_CONTEXT_PROJECT_GROUP
                    )
            })
            .ok_or_else(|| {
                AppError::Unauthorized("conversation does not belong to the company".into())
            })?;
        if context.visibility != "members" {
            return Err(AppError::Unauthorized(
                "company conversation is not visible to members".into(),
            ));
        }
        if !self
            .repo
            .list_conversation_member_ids(input.conversation_id)
            .contains(&input.actor_agent_id)
        {
            return Err(AppError::Unauthorized(
                "agent is not a member of the target conversation".into(),
            ));
        }
        let content = input.content.trim();
        if content.is_empty() {
            return Err(AppError::Validation("message content is required".into()));
        }
        let (mentioned_agent_ids, notification_recipient_ids) = self
            .resolve_company_message_mentions(
                &context,
                input.conversation_id,
                Some(input.actor_agent_id),
                input.mentioned_agent_ids,
                input.mention_all,
            )?;
        let message = MessageView {
            id: Uuid::new_v4(),
            conversation_id: input.conversation_id,
            sender_agent_id: Some(input.actor_agent_id),
            sender_human_user_id: None,
            content: content.to_string(),
            created_at: now_utc(),
        };
        self.repo.append_message_with_metadata(
            message.clone(),
            json!({
                "mentioned_agent_ids": mentioned_agent_ids,
                "mention_all": input.mention_all,
            }),
        )?;
        self.enqueue_message_events_for_recipients(
            &message,
            runtime_generated,
            &notification_recipient_ids,
            &mentioned_agent_ids,
            input.mention_all,
            context.context_type == CONVERSATION_CONTEXT_COMPANY_DIRECT
                || input.mention_all
                || !mentioned_agent_ids.is_empty(),
        )?;
        Ok(message)
    }

    fn resolve_company_message_mentions(
        &self,
        context: &ConversationContext,
        conversation_id: Uuid,
        sender_agent_id: Option<Uuid>,
        mentioned_agent_ids: Vec<Uuid>,
        mention_all: bool,
    ) -> AppResult<(Vec<Uuid>, Vec<Uuid>)> {
        if context.context_type == CONVERSATION_CONTEXT_COMPANY_DIRECT
            && (mention_all || !mentioned_agent_ids.is_empty())
        {
            return Err(AppError::Validation(
                "mentions are only supported in group conversations".into(),
            ));
        }

        let mut participants = self.repo.list_conversation_member_ids(conversation_id);
        participants.sort();
        participants.dedup();

        let mut normalized_mentions = mentioned_agent_ids;
        normalized_mentions.sort();
        normalized_mentions.dedup();
        if normalized_mentions.len() > 50 {
            return Err(AppError::Validation(
                "a message can mention at most 50 Agents".into(),
            ));
        }
        if mention_all {
            normalized_mentions.clear();
        }
        if let Some(sender_agent_id) = sender_agent_id {
            normalized_mentions.retain(|agent_id| *agent_id != sender_agent_id);
        }
        if normalized_mentions
            .iter()
            .any(|agent_id| !participants.contains(agent_id))
        {
            return Err(AppError::Validation(
                "mentioned Agent must be an active member of the conversation".into(),
            ));
        }

        let mut recipients = if context.context_type == CONVERSATION_CONTEXT_COMPANY_DIRECT
            || mention_all
            || normalized_mentions.is_empty()
        {
            participants
        } else {
            normalized_mentions.clone()
        };
        if let Some(sender_agent_id) = sender_agent_id {
            recipients.retain(|agent_id| *agent_id != sender_agent_id);
        }
        Ok((normalized_mentions, recipients))
    }

    pub fn create_company_project(
        &self,
        input: CreateCompanyProjectInput,
    ) -> AppResult<CompanyProjectView> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        self.ensure_company_agent_permission(
            input.company_id,
            input.actor_agent_id,
            COMPANY_PERMISSION_PROJECT_CREATE,
        )?;
        let governance = self.effective_company_governance_policy_settings(input.company_id);
        let active_project_count = self
            .repo
            .list_company_projects(input.company_id)
            .into_iter()
            .filter(|project| {
                !matches!(
                    project.status.as_str(),
                    PROJECT_STATUS_COMPLETED | PROJECT_STATUS_CANCELLED
                )
            })
            .count();
        if active_project_count >= governance.max_active_projects as usize {
            return Err(AppError::RateLimited(format!(
                "company active project limit of {} has been reached",
                governance.max_active_projects
            )));
        }
        let name = input.name.trim();
        if name.is_empty() || name.chars().count() > 120 {
            return Err(AppError::Validation(
                "project name must contain 1 to 120 characters".into(),
            ));
        }
        let description = normalize_optional_text(input.description).unwrap_or_default();
        if description.chars().count() > 4000 {
            return Err(AppError::Validation(
                "project description must not exceed 4000 characters".into(),
            ));
        }
        let mut member_agent_ids = vec![input.actor_agent_id];
        for agent_id in input.member_agent_ids {
            if !member_agent_ids.contains(&agent_id) {
                member_agent_ids.push(agent_id);
            }
        }
        if member_agent_ids.len() > governance.max_project_members as usize {
            return Err(AppError::Validation(format!(
                "project supports at most {} active members",
                governance.max_project_members
            )));
        }
        for agent_id in member_agent_ids.iter().copied() {
            self.ensure_active_company_conversation_member(input.company_id, agent_id)?;
        }

        let now = now_utc();
        let project_id = Uuid::new_v4();
        let conversation_id = Uuid::new_v4();
        let project = CompanyProject {
            id: project_id,
            company_id: input.company_id,
            name: name.to_string(),
            description,
            status: PROJECT_STATUS_ACTIVE.into(),
            owner_agent_id: input.actor_agent_id,
            project_group_conversation_id: conversation_id,
            created_by_agent_id: input.actor_agent_id,
            updated_by_agent_id: None,
            due_at: None,
            created_at: now,
            updated_at: now,
            completed_at: None,
        };
        let preview = ConversationPreview {
            id: conversation_id,
            title: format!("项目 · {name}"),
            conversation_type: ConversationType::Group,
            last_message_preview: None,
            updated_at: now,
        };
        let members = member_agent_ids
            .iter()
            .copied()
            .map(|agent_id| CompanyProjectMember {
                id: Uuid::new_v4(),
                project_id,
                agent_profile_id: agent_id,
                role: if agent_id == input.actor_agent_id {
                    PROJECT_MEMBER_ROLE_OWNER.into()
                } else {
                    PROJECT_MEMBER_ROLE_MEMBER.into()
                },
                joined_at: now,
                left_at: None,
                added_by_agent_id: input.actor_agent_id,
            })
            .collect::<Vec<_>>();
        self.repo
            .complete_company_project_creation(CompanyProjectCreationBundle {
                project: project.clone(),
                members,
                conversation_members: member_agent_ids
                    .iter()
                    .copied()
                    .map(|agent_id| CompanyConversationMemberPreview {
                        agent_id,
                        preview: preview.clone(),
                    })
                    .collect(),
            })?;
        for agent_id in member_agent_ids {
            if agent_id != input.actor_agent_id {
                let _ = self.enqueue_agent_event(
                    agent_id,
                    "company.project.member_added",
                    json!({
                        "company_id": input.company_id,
                        "project_id": project_id,
                        "project_name": name,
                        "conversation_id": conversation_id,
                        "added_by_agent_id": input.actor_agent_id,
                    }),
                    35,
                );
            }
        }
        self.company_project_view(project)
    }

