    pub fn replace_company_project_assets(
        &self,
        input: ReplaceCompanyProjectAssetsInput,
    ) -> AppResult<Vec<CompanyProjectAsset>> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        self.ensure_company_agent_permission(
            input.company_id,
            input.actor_agent_id,
            COMPANY_PERMISSION_PROJECT_ASSETS_MANAGE,
        )?;
        self.ensure_company_project_access(
            input.company_id,
            input.project_id,
            input.actor_agent_id,
        )?;
        if input.assets.len() > 500 {
            return Err(AppError::Validation(
                "a project asset inventory supports at most 500 entries".into(),
            ));
        }
        let now = now_utc();
        let mut locators = HashSet::new();
        let mut assets = Vec::with_capacity(input.assets.len());
        for asset in input.assets {
            let name = normalize_required_project_asset_text(asset.name, 200, "asset name")?;
            let asset_type =
                normalize_required_project_asset_text(asset.asset_type, 80, "asset type")?;
            let locator =
                normalize_required_project_asset_text(asset.locator, 4_096, "asset locator")?;
            if !locators.insert(locator.clone()) {
                return Err(AppError::Validation(format!(
                    "duplicate project asset locator: {locator}"
                )));
            }
            let description = asset.description.unwrap_or_default().trim().to_string();
            if description.chars().count() > 4_000 {
                return Err(AppError::Validation(
                    "asset description must not exceed 4000 characters".into(),
                ));
            }
            let status = asset.status.unwrap_or_else(|| "active".into());
            if !matches!(
                status.as_str(),
                "active" | "missing" | "deprecated" | "unknown"
            ) {
                return Err(AppError::Validation(
                    "asset status must be active, missing, deprecated, or unknown".into(),
                ));
            }
            let metadata = asset.metadata.unwrap_or_else(|| json!({}));
            if !metadata.is_object() {
                return Err(AppError::Validation(
                    "asset metadata must be a JSON object".into(),
                ));
            }
            assets.push(CompanyProjectAsset {
                id: Uuid::new_v4(),
                project_id: input.project_id,
                name,
                asset_type,
                locator,
                description,
                status,
                metadata,
                updated_by_agent_id: Some(input.actor_agent_id),
                updated_by_human_user_id: None,
                created_at: now,
                updated_at: now,
            });
        }
        assets.sort_by(|left, right| {
            left.asset_type
                .cmp(&right.asset_type)
                .then_with(|| left.name.cmp(&right.name))
        });
        self.repo
            .replace_company_project_assets(input.project_id, assets.clone())?;
        self.repo
            .mark_company_project_asset_refresh_completed(input.project_id, now)?;
        Ok(assets)
    }

    pub fn upsert_company_project_asset_refresh_for_human(
        &self,
        input: UpsertCompanyProjectAssetRefreshForHumanInput,
    ) -> AppResult<CompanyProjectAssetRefreshConfig> {
        self.ensure_company_project_for_human_manager(
            input.human_user_id,
            input.company_id,
            input.project_id,
        )?;
        self.ensure_company_agent_for_human_manager(
            input.human_user_id,
            input.company_id,
            input.maintainer_agent_id,
        )?;
        self.ensure_active_project_member(input.project_id, input.maintainer_agent_id)?;
        self.ensure_company_agent_permission(
            input.company_id,
            input.maintainer_agent_id,
            COMPANY_PERMISSION_PROJECT_ASSETS_MANAGE,
        )?;
        if !(5..=10_080).contains(&input.interval_minutes) {
            return Err(AppError::Validation(
                "asset refresh interval_minutes must be between 5 and 10080".into(),
            ));
        }
        let existing = self
            .repo
            .get_company_project_asset_refresh_config(input.project_id);
        let now = now_utc();
        let schedule_changed = existing.as_ref().is_none_or(|config| {
            config.maintainer_agent_id != input.maintainer_agent_id
                || config.interval_minutes != input.interval_minutes
                || config.enabled != input.enabled
        });
        let next_refresh_at = if input.run_now && input.enabled {
            now
        } else if !schedule_changed {
            existing
                .as_ref()
                .map_or(now, |config| config.next_refresh_at)
        } else {
            now + Duration::minutes(i64::from(input.interval_minutes))
        };
        let config = CompanyProjectAssetRefreshConfig {
            project_id: input.project_id,
            maintainer_agent_id: input.maintainer_agent_id,
            interval_minutes: input.interval_minutes,
            enabled: input.enabled,
            next_refresh_at,
            last_requested_at: existing
                .as_ref()
                .and_then(|config| config.last_requested_at),
            last_completed_at: existing
                .as_ref()
                .and_then(|config| config.last_completed_at),
            created_by_human_user_id: existing.as_ref().map_or(input.human_user_id, |config| {
                config.created_by_human_user_id
            }),
            updated_by_human_user_id: Some(input.human_user_id),
            created_at: existing.as_ref().map_or(now, |config| config.created_at),
            updated_at: now,
        };
        self.repo
            .save_company_project_asset_refresh_config(config.clone())?;
        Ok(config)
    }

