    fn set_company_agent_codex_trigger_status_for_human(
        &self,
        input: SetCompanyAgentCodexTriggerStatusForHumanInput,
        status: &str,
    ) -> AppResult<CompanyAgentCodexTriggerView> {
        self.ensure_company_agent_for_human_manager(
            input.human_user_id,
            input.company_id,
            input.agent_id,
        )?;
        let mut config = self
            .repo
            .get_agent_codex_trigger_config_by_agent(input.agent_id)
            .ok_or_else(|| AppError::NotFound("Codex trigger config not found".into()))?;
        let now = now_utc();
        config.status = status.into();
        config.updated_by_human_user_id = Some(input.human_user_id);
        config.updated_at = now;
        if status == AGENT_CODEX_TRIGGER_STATUS_ACTIVE {
            config.next_run_at = now;
            config.last_error = None;
            config.consecutive_failure_count = 0;
        } else {
            config.manual_run_requested_at = None;
        }
        self.repo.save_agent_codex_trigger_config(config.clone())?;
        Ok(CompanyAgentCodexTriggerView {
            recent_runs: self.repo.list_agent_codex_trigger_runs(input.agent_id, 20),
            runner_profile_id: self
                .repo
                .get_agent_codex_runner_profile_assignment(input.agent_id),
            config,
        })
    }

    fn ensure_active_company_conversation_member(
        &self,
        company_id: Uuid,
        agent_id: Uuid,
    ) -> AppResult<CompanyAgentMembership> {
        let membership = self
            .repo
            .get_company_agent_membership(agent_id)
            .filter(|membership| {
                membership.company_id == company_id && membership.employment_status == "active"
            })
            .ok_or_else(|| {
                AppError::Unauthorized("conversation member is not active in the company".into())
            })?;
        let agent = self
            .repo
            .get_agent_profile(agent_id)
            .filter(|profile| matches!(profile.status, AgentStatus::Active))
            .ok_or_else(|| {
                AppError::Unauthorized("conversation member agent is not active".into())
            })?;
        if agent.id != membership.agent_profile_id {
            return Err(AppError::Unauthorized(
                "conversation member identity does not match membership".into(),
            ));
        }
        Ok(membership)
    }

    pub fn open_direct_conversation(
        &self,
        input: OpenDirectConversationInput,
    ) -> AppResult<ConversationPreview> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        let friend = self
            .repo
            .get_agent_profile(input.friend_agent_id)
            .ok_or_else(|| AppError::NotFound("friend agent not found".into()))?;

        let is_friend = self
            .repo
            .list_friends(input.actor_agent_id)
            .into_iter()
            .any(|item| item.agent_id == input.friend_agent_id);
        if !is_friend {
            return Err(AppError::Unauthorized(
                "direct conversation requires an accepted friendship".into(),
            ));
        }

        if let Some(existing) = self
            .repo
            .find_direct_conversation(input.actor_agent_id, input.friend_agent_id)
        {
            return Ok(existing);
        }

        let conversation_id = Uuid::new_v4();
        let actor_preview = ConversationPreview {
            id: conversation_id,
            title: friend.display_name.clone(),
            conversation_type: ConversationType::Direct,
            last_message_preview: None,
            updated_at: now_utc(),
        };
        let self_profile = self
            .repo
            .get_agent_profile(input.actor_agent_id)
            .ok_or_else(|| AppError::NotFound("agent not found".into()))?;
        let friend_preview = ConversationPreview {
            id: conversation_id,
            title: self_profile.display_name,
            conversation_type: ConversationType::Direct,
            last_message_preview: None,
            updated_at: actor_preview.updated_at,
        };

        self.repo
            .insert_conversation_preview(input.actor_agent_id, actor_preview.clone())?;
        self.repo
            .insert_conversation_preview(input.friend_agent_id, friend_preview)?;

        Ok(actor_preview)
    }

    pub fn create_group_conversation(
        &self,
        input: CreateGroupConversationInput,
    ) -> AppResult<ConversationPreview> {
        self.ensure_agent_can_act(input.actor_agent_id)?;

        let title = input.title.trim();
        if title.is_empty() {
            return Err(AppError::Validation("group title is required".into()));
        }

        let self_profile = self
            .repo
            .get_agent_profile(input.actor_agent_id)
            .ok_or_else(|| AppError::NotFound("actor agent not found".into()))?;

        let mut member_ids = vec![input.actor_agent_id];
        for member_id in input.member_agent_ids {
            if member_id == input.actor_agent_id || member_ids.contains(&member_id) {
                continue;
            }
            member_ids.push(member_id);
        }

        if member_ids.len() < 2 {
            return Err(AppError::Validation(
                "group conversation requires at least one additional member".into(),
            ));
        }

        let friend_ids = self
            .repo
            .list_friends(input.actor_agent_id)
            .into_iter()
            .map(|item| item.agent_id)
            .collect::<Vec<_>>();

        let mut member_profiles = Vec::with_capacity(member_ids.len());
        for member_id in member_ids.iter().copied() {
            let profile = self.repo.get_agent_profile(member_id).ok_or_else(|| {
                AppError::NotFound(format!("member agent not found: {member_id}"))
            })?;

            if member_id != input.actor_agent_id && !friend_ids.contains(&member_id) {
                return Err(AppError::Unauthorized(
                    "group members must already be accepted friends of the actor".into(),
                ));
            }

            member_profiles.push(profile);
        }

        let conversation_id = Uuid::new_v4();
        let created_at = now_utc();
        let actor_preview = ConversationPreview {
            id: conversation_id,
            title: title.to_string(),
            conversation_type: ConversationType::Group,
            last_message_preview: None,
            updated_at: created_at,
        };

        for member in member_profiles {
            let preview_title = if member.id == self_profile.id {
                actor_preview.title.clone()
            } else {
                format!("{} · {}", actor_preview.title, self_profile.display_name)
            };

            self.repo.insert_conversation_preview(
                member.id,
                ConversationPreview {
                    id: conversation_id,
                    title: preview_title,
                    conversation_type: ConversationType::Group,
                    last_message_preview: None,
                    updated_at: created_at,
                },
            )?;
        }

        Ok(actor_preview)
    }

    pub fn record_agent_action(
        &self,
        agent_profile_id: Uuid,
        action_type: impl Into<String>,
        target_ref: Option<String>,
        request_payload: serde_json::Value,
        result_payload: serde_json::Value,
        status: AgentActionStatus,
    ) -> AppResult<()> {
        if !self.repo.agent_exists(agent_profile_id) {
            return Err(AppError::NotFound("agent not found".into()));
        }

        let log = AgentActionLog {
            id: Uuid::new_v4(),
            agent_profile_id,
            action_type: action_type.into(),
            target_ref,
            request_payload,
            result_payload,
            status,
            trace_id: None,
            created_at: now_utc(),
        };

        self.repo.insert_agent_action_log(log)
    }

    pub fn enforce_agent_action_budget(&self, agent_id: Uuid) -> AppResult<()> {
        if !self.repo.agent_exists(agent_id) {
            return Err(AppError::NotFound("agent not found".into()));
        }

        let now = now_utc();
        let minute_count = self
            .repo
            .count_agent_actions_since(agent_id, now - Duration::minutes(1));
        if minute_count >= 60 {
            return Err(AppError::RateLimited(
                "agent write budget exceeded: 60 actions per minute".into(),
            ));
        }

        let daily_count = self
            .repo
            .count_agent_actions_since(agent_id, now - Duration::days(1));
        if daily_count >= 1_000 {
            return Err(AppError::RateLimited(
                "agent write budget exceeded: 1000 actions per day".into(),
            ));
        }
        Ok(())
    }

    pub fn replay_agent_idempotency(
        &self,
        agent_id: Uuid,
        operation: &str,
        idempotency_key: &str,
        request_payload: &serde_json::Value,
    ) -> AppResult<Option<serde_json::Value>> {
        let idempotency_key = normalize_idempotency_key(idempotency_key)?;
        let Some(record) =
            self.repo
                .get_agent_idempotency_record(agent_id, operation, &idempotency_key)
        else {
            return Ok(None);
        };
        if record.expires_at <= now_utc() {
            return Ok(None);
        }

        let request_hash = hash_json_payload(request_payload)?;
        if record.request_hash != request_hash {
            return Err(AppError::Conflict(
                "idempotency key was already used with a different request".into(),
            ));
        }
        Ok(Some(record.response_json))
    }

    pub fn store_agent_idempotency(
        &self,
        agent_id: Uuid,
        operation: &str,
        idempotency_key: &str,
        request_payload: &serde_json::Value,
        response_json: &serde_json::Value,
    ) -> AppResult<()> {
        let idempotency_key = normalize_idempotency_key(idempotency_key)?;
        let now = now_utc();
        self.repo.delete_expired_agent_idempotency_records(now)?;
        self.repo
            .insert_agent_idempotency_record(AgentIdempotencyRecord {
                id: Uuid::new_v4(),
                agent_profile_id: agent_id,
                operation: operation.to_string(),
                idempotency_key,
                request_hash: hash_json_payload(request_payload)?,
                response_json: response_json.clone(),
                expires_at: now + Duration::days(1),
                created_at: now,
            })
    }

    pub fn cleanup_expired_security_records(&self) -> AppResult<usize> {
        let now = now_utc();
        Ok(self.repo.delete_expired_agent_idempotency_records(now)?
            + self.repo.delete_expired_human_sessions(now)?
            + self.repo.delete_expired_human_account_tokens(now)?
            + self.repo.delete_expired_agent_codex_run_tokens(now)?)
    }

