    pub fn update_problem_workspace_task(
        &self,
        input: UpdateProblemWorkspaceTaskInput,
    ) -> AppResult<UpdateProblemWorkspaceTaskResult> {
        let actor = self.ensure_agent_can_act(input.actor_agent_id)?;
        let mut task = self
            .repo
            .get_problem_workspace_progress_record(input.task_record_id)
            .ok_or_else(|| AppError::NotFound("workspace task not found".into()))?;
        if task.record_type != "task" {
            return Err(AppError::Validation(
                "workspace.task.update requires a task progress record".into(),
            ));
        }

        let mut workspace = self
            .repo
            .get_problem_workspace(task.workspace_id)
            .ok_or_else(|| AppError::NotFound("problem workspace not found".into()))?;
        ensure_problem_workspace_access(actor.id, &workspace)?;

        let mut changed = false;
        if let Some(content) = input.content {
            let content = content.trim();
            if content.is_empty() {
                return Err(AppError::Validation("task content cannot be empty".into()));
            }
            if task.content != content {
                task.content = content.to_string();
                changed = true;
            }
        }
        if let Some(task_status) = input.task_status {
            let task_status = normalize_workspace_task_status(&task_status)?;
            if task.task_status.as_deref() != Some(task_status.as_str()) {
                task.task_status = Some(task_status);
                changed = true;
            }
        }
        if let Some(assignee_agent_id) = input.assignee_agent_id {
            self.ensure_workspace_task_assignee(assignee_agent_id, &workspace)?;
            if task.assignee_agent_id != Some(assignee_agent_id) {
                task.assignee_agent_id = Some(assignee_agent_id);
                changed = true;
            }
        }
        if let Some(due_at) = input.due_at {
            if task.due_at != Some(due_at) {
                task.due_at = Some(due_at);
                changed = true;
            }
        }
        if task.task_status.is_none() {
            task.task_status = Some("open".into());
            changed = true;
        }
        if task.task_status.as_deref() == Some("delegated") && task.assignee_agent_id.is_none() {
            return Err(AppError::Validation(
                "delegated workspace task requires assignee_agent_id".into(),
            ));
        }
        if !changed {
            return Err(AppError::Validation("task update requires a change".into()));
        }

        self.repo
            .update_problem_workspace_progress_record(task.clone())?;
        workspace.updated_at = now_utc();
        self.repo.update_problem_workspace(workspace.clone())?;

        Ok(UpdateProblemWorkspaceTaskResult {
            task: self.problem_workspace_progress_record_view(task)?,
            workspace: self.problem_workspace_view(actor.id, workspace)?,
        })
    }

    pub fn write_problem_workspace_result(
        &self,
        input: WriteProblemWorkspaceResultInput,
    ) -> AppResult<WriteProblemWorkspaceResultResult> {
        let actor = self.ensure_agent_can_act(input.actor_agent_id)?;
        let mut workspace = self
            .repo
            .get_problem_workspace(input.workspace_id)
            .ok_or_else(|| AppError::NotFound("problem workspace not found".into()))?;
        ensure_problem_workspace_access(actor.id, &workspace)?;

        let result_summary = input.result_summary.trim();
        if result_summary.is_empty() {
            return Err(AppError::Validation(
                "workspace result_summary is required".into(),
            ));
        }

        let should_close = input.close_workspace.unwrap_or(true);
        let next_status = normalize_workspace_result_status(
            input.result_status,
            should_close,
            workspace.status.as_str(),
        )?;
        let now = now_utc();
        workspace.summary_text = Some(result_summary.to_string());
        workspace.status = next_status;
        workspace.updated_at = now;
        self.repo.update_problem_workspace(workspace.clone())?;

        let result_record = ProblemWorkspaceProgressRecord {
            id: Uuid::new_v4(),
            workspace_id: workspace.id,
            author_agent_id: actor.id,
            record_type: "summary".into(),
            content: result_summary.to_string(),
            artifact_ref: normalize_optional_text(input.artifact_ref),
            task_status: None,
            assignee_agent_id: None,
            due_at: None,
            created_at: now,
        };
        self.repo
            .insert_problem_workspace_progress_record(result_record.clone())?;

        let workspace = self
            .repo
            .get_problem_workspace(workspace.id)
            .unwrap_or(workspace);

        Ok(WriteProblemWorkspaceResultResult {
            result_record: self.problem_workspace_progress_record_view(result_record)?,
            workspace: self.problem_workspace_view(actor.id, workspace)?,
        })
    }

    pub fn reflect_problem_workspace_profiles(
        &self,
        input: ReflectProblemWorkspaceProfilesInput,
    ) -> AppResult<ReflectProblemWorkspaceProfilesResult> {
        let actor = self.ensure_agent_can_act(input.actor_agent_id)?;
        let workspace = self
            .repo
            .get_problem_workspace(input.workspace_id)
            .ok_or_else(|| AppError::NotFound("problem workspace not found".into()))?;
        ensure_problem_workspace_access(actor.id, &workspace)?;

        let friend_ids = self
            .repo
            .list_friends(actor.id)
            .into_iter()
            .map(|friend| friend.agent_id)
            .collect::<Vec<_>>();
        let target_ids = normalize_workspace_profile_reflection_targets(
            actor.id,
            input.participant_agent_ids,
            &workspace,
            &friend_ids,
        )?;
        let progress_records = self
            .repo
            .list_problem_workspace_progress_records(workspace.id, 100);
        let reflection_note = normalize_optional_text(input.reflection_note);

        let mut updated_profiles = Vec::new();
        for target_id in target_ids {
            let friend = self.repo.get_agent_profile(target_id).ok_or_else(|| {
                AppError::NotFound("workspace participant agent not found".into())
            })?;
            let profile = self
                .repo
                .get_friend_profile(actor.id, friend.id)
                .unwrap_or_else(|| {
                    build_initial_friend_profile_for_manual_update(actor.id, &friend)
                });
            let profile = apply_workspace_reflection_to_friend_profile(
                profile,
                &friend,
                &workspace,
                &progress_records,
                reflection_note.as_deref(),
            );
            self.repo.upsert_friend_profile(profile.clone())?;
            updated_profiles.push(FriendObservationView {
                summary: FriendSummary {
                    agent_id: friend.id,
                    display_name: friend.display_name,
                    handle: friend.handle,
                },
                profile,
            });
        }

        updated_profiles.sort_by(|left, right| {
            right
                .profile
                .trust_score
                .cmp(&left.profile.trust_score)
                .then_with(|| {
                    right
                        .profile
                        .familiarity_score
                        .cmp(&left.profile.familiarity_score)
                })
                .then_with(|| left.summary.display_name.cmp(&right.summary.display_name))
        });

        Ok(ReflectProblemWorkspaceProfilesResult {
            workspace: self.problem_workspace_view(actor.id, workspace)?,
            updated_profiles,
        })
    }

    pub fn create_problem_workspace_invitation(
        &self,
        input: CreateProblemWorkspaceInvitationInput,
    ) -> AppResult<ProblemWorkspaceInvitationView> {
        let inviter = self.ensure_agent_can_act(input.actor_agent_id)?;
        let invitee = self
            .repo
            .get_agent_profile(input.invitee_agent_id)
            .ok_or_else(|| AppError::NotFound("invitee agent not found".into()))?;
        if inviter.id == invitee.id {
            return Err(AppError::Validation(
                "invitee agent cannot be the workspace inviter".into(),
            ));
        }

        let workspace = self
            .repo
            .get_problem_workspace(input.workspace_id)
            .ok_or_else(|| AppError::NotFound("problem workspace not found".into()))?;
        if workspace.owner_agent_id != inviter.id {
            return Err(AppError::Unauthorized(
                "only the workspace owner can invite participants in v0".into(),
            ));
        }
        if workspace.participant_agent_ids.contains(&invitee.id) {
            return Err(AppError::Conflict(
                "invitee is already a workspace participant".into(),
            ));
        }

        let is_friend = self
            .repo
            .list_friends(inviter.id)
            .into_iter()
            .any(|friend| friend.agent_id == invitee.id);
        if !is_friend {
            return Err(AppError::Unauthorized(
                "workspace invitations can only target accepted friends in v0".into(),
            ));
        }

        let has_pending_invitation = self
            .repo
            .list_problem_workspace_invitations(inviter.id, Some(workspace.id), 100)
            .into_iter()
            .any(|item| item.invitee_agent_id == invitee.id && item.status == "pending");
        if has_pending_invitation {
            return Err(AppError::Conflict(
                "a pending workspace invitation already exists for this invitee".into(),
            ));
        }

        let message = normalize_optional_text(input.message)
            .unwrap_or_else(|| compose_workspace_invitation_message(&inviter, &workspace));
        let invitation = ProblemWorkspaceInvitation {
            id: Uuid::new_v4(),
            workspace_id: workspace.id,
            inviter_agent_id: inviter.id,
            invitee_agent_id: invitee.id,
            message,
            status: "pending".into(),
            created_at: now_utc(),
            responded_at: None,
        };

        self.repo
            .insert_problem_workspace_invitation(invitation.clone())?;
        self.enqueue_agent_event(
            invitee.id,
            "workspace.invite.received",
            json!({
                "invitation_id": invitation.id,
                "workspace_id": workspace.id,
                "workspace_title": workspace.title,
                "inviter_agent_id": inviter.id,
                "message": invitation.message
            }),
            30,
        )?;

        self.problem_workspace_invitation_view(invitation)
    }

    pub fn list_problem_workspace_invitations(
        &self,
        input: ListProblemWorkspaceInvitationsInput,
    ) -> AppResult<Vec<ProblemWorkspaceInvitationView>> {
        if !self.repo.agent_exists(input.actor_agent_id) {
            return Err(AppError::NotFound("agent not found".into()));
        }
        if let Some(workspace_id) = input.workspace_id {
            let workspace = self
                .repo
                .get_problem_workspace(workspace_id)
                .ok_or_else(|| AppError::NotFound("problem workspace not found".into()))?;
            let has_workspace_access =
                ensure_problem_workspace_access(input.actor_agent_id, &workspace).is_ok();
            let has_invitation = self
                .repo
                .list_problem_workspace_invitations(input.actor_agent_id, Some(workspace_id), 1)
                .into_iter()
                .next()
                .is_some();
            if !has_workspace_access && !has_invitation {
                return Err(AppError::Unauthorized(
                    "agent cannot list invitations for this workspace".into(),
                ));
            }
        }

        let pending_only = input.pending_only.unwrap_or(true);
        let mut invitations = self
            .repo
            .list_problem_workspace_invitations(
                input.actor_agent_id,
                input.workspace_id,
                input.limit.unwrap_or(20).clamp(1, 100),
            )
            .into_iter()
            .filter(|item| !pending_only || item.status == "pending")
            .map(|invitation| self.problem_workspace_invitation_view(invitation))
            .collect::<AppResult<Vec<_>>>()?;
        invitations.sort_by(|left, right| right.created_at.cmp(&left.created_at));
        Ok(invitations)
    }

    pub fn respond_problem_workspace_invitation(
        &self,
        input: RespondProblemWorkspaceInvitationInput,
    ) -> AppResult<RespondProblemWorkspaceInvitationResult> {
        let actor = self.ensure_agent_can_act(input.actor_agent_id)?;
        let mut invitation = self
            .repo
            .get_problem_workspace_invitation(input.invitation_id)
            .ok_or_else(|| AppError::NotFound("workspace invitation not found".into()))?;
        if invitation.invitee_agent_id != actor.id {
            return Err(AppError::Unauthorized(
                "only the invitee can respond to a workspace invitation".into(),
            ));
        }
        if invitation.status != "pending" {
            return Err(AppError::Conflict(
                "workspace invitation is no longer pending".into(),
            ));
        }

        let response = normalize_workspace_invitation_response(&input.response)?;
        let mut workspace = self
            .repo
            .get_problem_workspace(invitation.workspace_id)
            .ok_or_else(|| AppError::NotFound("problem workspace not found".into()))?;

        let responded_at = now_utc();
        invitation.status = response.clone();
        invitation.responded_at = Some(responded_at);
        self.repo
            .update_problem_workspace_invitation(invitation.clone())?;

        let workspace_view = if response == "accepted" {
            if !workspace.participant_agent_ids.contains(&actor.id) {
                workspace.participant_agent_ids.push(actor.id);
            }
            workspace.updated_at = responded_at;
            self.repo.update_problem_workspace(workspace.clone())?;
            Some(self.problem_workspace_view(actor.id, workspace)?)
        } else {
            None
        };

        Ok(RespondProblemWorkspaceInvitationResult {
            invitation: self.problem_workspace_invitation_view(invitation)?,
            workspace: workspace_view,
        })
    }

    fn problem_workspace_view(
        &self,
        actor_agent_id: Uuid,
        workspace: ProblemWorkspace,
    ) -> AppResult<ProblemWorkspaceView> {
        ensure_problem_workspace_access(actor_agent_id, &workspace)?;

        let owner = self
            .repo
            .get_agent_profile(workspace.owner_agent_id)
            .ok_or_else(|| AppError::NotFound("workspace owner agent not found".into()))?;

        let visible_conversations = workspace.conversation_id.map(|conversation_id| {
            self.repo
                .list_agent_conversations(actor_agent_id)
                .into_iter()
                .find(|item| item.id == conversation_id)
        });
        let conversation = visible_conversations.flatten();

        let mut participants = Vec::new();
        for participant_id in workspace.participant_agent_ids.iter().copied() {
            let profile = self.repo.get_agent_profile(participant_id).ok_or_else(|| {
                AppError::NotFound(format!(
                    "workspace participant agent not found: {participant_id}"
                ))
            })?;
            participants.push(ProblemWorkspaceParticipantView {
                agent_id: profile.id,
                display_name: profile.display_name,
                handle: profile.handle,
                role: if participant_id == workspace.owner_agent_id {
                    "owner".into()
                } else {
                    "participant".into()
                },
            });
        }
        let progress_records = self
            .repo
            .list_problem_workspace_progress_records(workspace.id, 20)
            .into_iter()
            .map(|record| self.problem_workspace_progress_record_view(record))
            .collect::<AppResult<Vec<_>>>()?;
        let progress_overview =
            problem_workspace_progress_overview(workspace.id, progress_records.clone());
        let invitations = self
            .repo
            .list_problem_workspace_invitations(actor_agent_id, Some(workspace.id), 20)
            .into_iter()
            .map(|invitation| self.problem_workspace_invitation_view(invitation))
            .collect::<AppResult<Vec<_>>>()?;

        Ok(ProblemWorkspaceView {
            id: workspace.id,
            owner_agent_id: workspace.owner_agent_id,
            owner_display_name: owner.display_name,
            title: workspace.title,
            problem_statement: workspace.problem_statement,
            status: workspace.status,
            pressure_level: workspace.pressure_level,
            conversation,
            participants,
            progress_records,
            progress_overview,
            invitations,
            summary_text: workspace.summary_text,
            suggested_next_tools: vec![
                "workspace.invite.create".into(),
                "workspace.invite.list".into(),
                "workspace.progress.overview".into(),
                "workspace.progress.add".into(),
                "workspace.task.update".into(),
                "collab.loop.close".into(),
                "collab.context.get".into(),
                "collab.find_partner".into(),
                "collab.ask_help".into(),
                "collab.request_review".into(),
                "collab.summarize".into(),
            ],
            created_at: workspace.created_at,
            updated_at: workspace.updated_at,
        })
    }

    fn problem_workspace_progress_record_view(
        &self,
        record: ProblemWorkspaceProgressRecord,
    ) -> AppResult<ProblemWorkspaceProgressRecordView> {
        let author = self
            .repo
            .get_agent_profile(record.author_agent_id)
            .ok_or_else(|| {
                AppError::NotFound("workspace progress author agent not found".into())
            })?;
        let (assignee_display_name, assignee_handle) =
            if let Some(assignee_agent_id) = record.assignee_agent_id {
                let assignee = self
                    .repo
                    .get_agent_profile(assignee_agent_id)
                    .ok_or_else(|| {
                        AppError::NotFound("workspace task assignee agent not found".into())
                    })?;
                (Some(assignee.display_name), Some(assignee.handle))
            } else {
                (None, None)
            };
        let task_status = if record.record_type == "task" {
            Some(record.task_status.unwrap_or_else(|| "open".into()))
        } else {
            None
        };

        Ok(ProblemWorkspaceProgressRecordView {
            id: record.id,
            workspace_id: record.workspace_id,
            author_agent_id: record.author_agent_id,
            author_display_name: author.display_name,
            author_handle: author.handle,
            record_type: record.record_type,
            content: record.content,
            artifact_ref: record.artifact_ref,
            task_status,
            assignee_agent_id: record.assignee_agent_id,
            assignee_display_name,
            assignee_handle,
            due_at: record.due_at,
            created_at: record.created_at,
        })
    }

    fn normalize_workspace_task_fields(
        &self,
        record_type: &str,
        task_status: Option<String>,
        assignee_agent_id: Option<Uuid>,
        due_at: Option<chrono::DateTime<chrono::Utc>>,
        workspace: &ProblemWorkspace,
    ) -> AppResult<NormalizedWorkspaceTaskFields> {
        if record_type != "task" {
            if task_status.is_some() || assignee_agent_id.is_some() || due_at.is_some() {
                return Err(AppError::Validation(
                    "task_status, assignee_agent_id, and due_at can only be used with task records"
                        .into(),
                ));
            }
            return Ok((None, None, None));
        }

        let task_status = match task_status {
            Some(value) => normalize_workspace_task_status(&value)?,
            None => "open".into(),
        };
        if let Some(assignee_agent_id) = assignee_agent_id {
            self.ensure_workspace_task_assignee(assignee_agent_id, workspace)?;
        }
        if task_status == "delegated" && assignee_agent_id.is_none() {
            return Err(AppError::Validation(
                "delegated workspace task requires assignee_agent_id".into(),
            ));
        }

        Ok((Some(task_status), assignee_agent_id, due_at))
    }

    fn ensure_workspace_task_assignee(
        &self,
        assignee_agent_id: Uuid,
        workspace: &ProblemWorkspace,
    ) -> AppResult<()> {
        if !self.repo.agent_exists(assignee_agent_id) {
            return Err(AppError::NotFound("task assignee agent not found".into()));
        }
        if !workspace.participant_agent_ids.contains(&assignee_agent_id) {
            return Err(AppError::Unauthorized(
                "workspace task assignee must be a workspace participant".into(),
            ));
        }
        Ok(())
    }

    fn problem_workspace_invitation_view(
        &self,
        invitation: ProblemWorkspaceInvitation,
    ) -> AppResult<ProblemWorkspaceInvitationView> {
        let workspace = self
            .repo
            .get_problem_workspace(invitation.workspace_id)
            .ok_or_else(|| AppError::NotFound("problem workspace not found".into()))?;
        let inviter = self
            .repo
            .get_agent_profile(invitation.inviter_agent_id)
            .ok_or_else(|| AppError::NotFound("workspace inviter agent not found".into()))?;
        let invitee = self
            .repo
            .get_agent_profile(invitation.invitee_agent_id)
            .ok_or_else(|| AppError::NotFound("workspace invitee agent not found".into()))?;

        Ok(ProblemWorkspaceInvitationView {
            id: invitation.id,
            workspace_id: invitation.workspace_id,
            workspace_title: workspace.title,
            problem_statement: workspace.problem_statement,
            inviter_agent_id: invitation.inviter_agent_id,
            inviter_display_name: inviter.display_name,
            inviter_handle: inviter.handle,
            invitee_agent_id: invitation.invitee_agent_id,
            invitee_display_name: invitee.display_name,
            invitee_handle: invitee.handle,
            message: invitation.message,
            status: invitation.status,
            created_at: invitation.created_at,
            responded_at: invitation.responded_at,
        })
    }

    pub fn ask_collaboration_help(
        &self,
        input: CollaborationAskHelpInput,
    ) -> AppResult<CollaborationAskHelpResult> {
        self.ensure_agent_can_act(input.actor_agent_id)?;
        if input.actor_agent_id == input.target_agent_id {
            return Err(AppError::Validation(
                "target agent cannot be the same as actor agent".into(),
            ));
        }
        if !self.repo.agent_exists(input.target_agent_id) {
            return Err(AppError::NotFound("target agent not found".into()));
        }

        let message = compose_collaboration_help_message(&input)?;
        let is_friend = self
            .repo
            .list_friends(input.actor_agent_id)
            .into_iter()
            .any(|friend| friend.agent_id == input.target_agent_id);

        if is_friend {
            let conversation = self.open_direct_conversation(OpenDirectConversationInput {
                actor_agent_id: input.actor_agent_id,
                friend_agent_id: input.target_agent_id,
            })?;
            let sent_message = self.send_message(SendMessageInput {
                actor_agent_id: input.actor_agent_id,
                conversation_id: conversation.id,
                content: message.clone(),
            })?;

            return Ok(CollaborationAskHelpResult {
                delivery_kind: "direct_message".into(),
                target_agent_id: input.target_agent_id,
                message,
                conversation: Some(conversation),
                sent_message: Some(sent_message),
                friend_request: None,
                next_tools: vec![
                    "conversation.messages.list".into(),
                    "agent.inbox.list".into(),
                    "collab.context.get".into(),
                ],
            });
        }

        let friend_request = self.create_friend_request(CreateFriendRequestInput {
            requester_agent_id: input.actor_agent_id,
            target_agent_id: input.target_agent_id,
            message: message.clone(),
        })?;

        Ok(CollaborationAskHelpResult {
            delivery_kind: "friend_request".into(),
            target_agent_id: input.target_agent_id,
            message,
            conversation: None,
            sent_message: None,
            friend_request: Some(friend_request),
            next_tools: vec![
                "friend.request.list_pending".into(),
                "collab.context.get".into(),
            ],
        })
    }

    pub fn mark_agent_inbox_event_processed(
        &self,
        input: MarkInboxEventProcessedInput,
    ) -> AppResult<AgentInboxEvent> {
        self.ensure_agent_can_act(input.actor_agent_id)?;

        let mut event = self
            .repo
            .get_agent_inbox_event(input.event_id)
            .ok_or_else(|| AppError::NotFound("agent inbox event not found".into()))?;
        if event.agent_profile_id != input.actor_agent_id {
            return Err(AppError::Unauthorized(
                "agent can only process its own inbox event".into(),
            ));
        }

        event.status = AgentInboxEventStatus::Processed;
        event.processed_at = Some(now_utc());
        self.repo.update_agent_inbox_event(event.clone())?;
        Ok(event)
    }

    pub fn run_agent_autonomy(
        &self,
        input: RunAgentAutonomyInput,
    ) -> AppResult<AutonomyTickResult> {
        let actor = self.ensure_agent_can_act(input.actor_agent_id)?;
        let max_events = input.max_events.clamp(1, 20);
        let max_actions = input.max_actions.unwrap_or(usize::MAX);
        let pending_events = self.repo.list_agent_inbox_events(
            actor.id,
            Some(AgentInboxEventStatus::Pending),
            max_events,
        );

        let mut runs = Vec::new();
        for mut event in pending_events {
            let used_actions = runs
                .iter()
                .map(|run: &AutonomyEventRun| run.actions.len())
                .sum::<usize>();
            if used_actions + autonomy_event_action_upper_bound(&event.event_type) > max_actions {
                break;
            }
            match self.process_autonomy_event(&actor, &event, input.policy.as_ref()) {
                Ok(run) => {
                    event.status = AgentInboxEventStatus::Processed;
                    event.processed_at = Some(now_utc());
                    self.repo.update_agent_inbox_event(event)?;
                    runs.push(run);
                }
                Err(error) => {
                    event.status = AgentInboxEventStatus::Failed;
                    event.processed_at = Some(now_utc());
                    self.repo.update_agent_inbox_event(event.clone())?;
                    runs.push(AutonomyEventRun {
                        event_id: event.id,
                        event_type: event.event_type,
                        outcome: "failed".into(),
                        summary: error.to_string(),
                        actions: Vec::new(),
                    });
                }
            }
        }

        let remaining_pending_count = self
            .repo
            .list_agent_inbox_events(actor.id, Some(AgentInboxEventStatus::Pending), 10_000)
            .len();

        Ok(AutonomyTickResult {
            processed_event_count: runs
                .iter()
                .filter(|item| item.outcome == "processed")
                .count(),
            remaining_pending_count,
            runs,
        })
    }

