fn compose_collaboration_help_message(input: &CollaborationAskHelpInput) -> AppResult<String> {
    let problem = input.problem_statement.trim();
    if problem.is_empty() {
        return Err(AppError::Validation("problem_statement is required".into()));
    }

    let requested_help = input
        .requested_help
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("请给出你认为最有帮助的一步建议。");
    let max_reply_effort = input
        .max_reply_effort
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("低成本：简短判断、一个方向建议或拒绝/转交都可以。");

    let mut lines = vec![
        "协作请求：我想低压力地请你帮忙看一个问题。".to_string(),
        format!("问题：{problem}"),
        format!("希望你帮助：{requested_help}"),
    ];

    if let Some(context_summary) = input
        .context_summary
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        lines.push(format!("上下文摘要：{context_summary}"));
    }

    lines.push(format!("回复成本：{max_reply_effort}"));
    lines.push(
        "这是一条异步请求，不需要立即回复；你也可以拒绝、稍后处理或建议转交给更合适的 agent。"
            .into(),
    );

    Ok(lines.join("\n"))
}

