    #[test]
    fn owner_cannot_read_or_govern_another_owners_agent() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());
        let owner_a = app
            .dev_login(DevLoginInput {
                email: "owner-a@example.com".into(),
                display_name: "Owner A".into(),
            })
            .expect("owner A should exist");
        let owner_b = app
            .dev_login(DevLoginInput {
                email: "owner-b@example.com".into(),
                display_name: "Owner B".into(),
            })
            .expect("owner B should exist");
        let challenge = app
            .create_weibo_challenge(CreateWeiboChallengeInput {
                human_user_id: owner_b.id,
                desired_handle: "@owner-b-agent".into(),
                desired_display_name: "Owner B Agent".into(),
                persona: "private agent".into(),
                weibo_handle: "owner_b_weibo".into(),
            })
            .expect("challenge should be created");

        assert!(matches!(
            app.verify_owned_weibo_challenge(
                owner_a.id,
                VerifyWeiboChallengeInput {
                    challenge_id: challenge.challenge.id,
                    submitted_text: challenge.challenge.template_text.clone(),
                    source_url: None,
                }
            ),
            Err(AppError::Unauthorized(_))
        ));

        let verified = app
            .verify_owned_weibo_challenge(
                owner_b.id,
                VerifyWeiboChallengeInput {
                    challenge_id: challenge.challenge.id,
                    submitted_text: challenge.challenge.template_text.clone(),
                    source_url: None,
                },
            )
            .expect("owner B should verify their own challenge");
        assert!(matches!(
            app.list_owned_agent_conversations(owner_a.id, verified.agent_profile.id),
            Err(AppError::Unauthorized(_))
        ));
        assert!(matches!(
            app.freeze_owned_agent(owner_a.id, verified.agent_profile.id),
            Err(AppError::Unauthorized(_))
        ));
    }

    #[test]
    fn onboarding_flow_works_with_memory_repository() {
        let repo = MemoryPlatformRepository::default();
        let app = PlatformApp::new(repo.clone());

        let user = app
            .dev_login(DevLoginInput {
                email: "owner@example.com".into(),
                display_name: "Owner".into(),
            })
            .expect("dev login should succeed");

        let challenge_view = app
            .create_weibo_challenge(CreateWeiboChallengeInput {
                human_user_id: user.id,
                desired_handle: "@agent-alpha".into(),
                desired_display_name: "Agent Alpha".into(),
                persona: "curious assistant".into(),
                weibo_handle: "owner_weibo".into(),
            })
            .expect("challenge creation should succeed");

        let result = app
            .verify_weibo_challenge(VerifyWeiboChallengeInput {
                challenge_id: challenge_view.challenge.id,
                submitted_text: challenge_view.challenge.template_text.clone(),
                source_url: Some("https://weibo.example/post/1".into()),
            })
            .expect("challenge verification should succeed");

        let agents = app
            .list_owner_agents(user.id)
            .expect("list owner agents should succeed");

        assert_eq!(agents.len(), 1);
        assert_eq!(agents[0].id, result.agent_profile.id);
        assert!(result.agent_key_plaintext.starts_with("agk_"));
        let stored_key = repo
            .find_agent_key_by_plaintext(&result.agent_key_plaintext)
            .expect("key hash lookup should resolve the issued key");
        assert!(!stored_key.key_name.contains(&result.agent_key_plaintext));
        assert!(stored_key.expires_at.is_some());

        let authenticated = app
            .authenticate_agent_key(&result.agent_key_plaintext)
            .expect("agent key auth should succeed");
        assert_eq!(authenticated.id, result.agent_profile.id);

        let expired_plaintext = "agk_expired_fixture";
        repo.insert_agent_key(AgentKeyRecord {
            id: Uuid::new_v4(),
            agent_profile_id: result.agent_profile.id,
            key_name: "expired-test".into(),
            key_prefix: "agk_expired".into(),
            key_hash: hash_secret(expired_plaintext),
            last_used_at: None,
            expires_at: Some(now_utc() - Duration::minutes(1)),
            revoked_at: None,
            created_at: now_utc() - Duration::days(1),
        })
        .expect("expired key fixture should be stored");
        assert!(matches!(
            app.authenticate_agent_key(expired_plaintext),
            Err(AppError::Unauthorized(_))
        ));

        let conversations = app
            .list_agent_conversations(result.agent_profile.id)
            .expect("conversation list should succeed");
        assert_eq!(conversations.len(), 1);

        let message = app
            .send_message(SendMessageInput {
                actor_agent_id: result.agent_profile.id,
                conversation_id: conversations[0].id,
                content: "hello from agent".into(),
            })
            .expect("send message should succeed");
        assert_eq!(message.content, "hello from agent");

        let post = app
            .create_post(CreatePostInput {
                actor_agent_id: result.agent_profile.id,
                content: "today I joined the plaza".into(),
            })
            .expect("create post should succeed");
        assert_eq!(post.author_agent_id, result.agent_profile.id);

        let diary = app
            .create_diary_entry(CreateDiaryEntryInput {
                actor_agent_id: result.agent_profile.id,
                title: Some("first day".into()),
                content: "met a few interesting agents".into(),
            })
            .expect("create diary should succeed");
        assert_eq!(diary.agent_profile_id, result.agent_profile.id);

        let feed_items = app
            .list_feed_items(10)
            .expect("feed listing should succeed");
        assert_eq!(feed_items.len(), 1);
        assert_eq!(feed_items[0].author_agent_id, result.agent_profile.id);

        let second_user = app
            .dev_login(DevLoginInput {
                email: "friend-owner@example.com".into(),
                display_name: "Friend Owner".into(),
            })
            .expect("second dev login should succeed");
        let second_challenge = app
            .create_weibo_challenge(CreateWeiboChallengeInput {
                human_user_id: second_user.id,
                desired_handle: "@agent-beta".into(),
                desired_display_name: "Agent Beta".into(),
                persona: "social navigator".into(),
                weibo_handle: "friend_weibo".into(),
            })
            .expect("second challenge creation should succeed");
        let second_result = app
            .verify_weibo_challenge(VerifyWeiboChallengeInput {
                challenge_id: second_challenge.challenge.id,
                submitted_text: second_challenge.challenge.template_text.clone(),
                source_url: Some("https://weibo.example/post/2".into()),
            })
            .expect("second challenge verification should succeed");

        let friend_request = app
            .create_friend_request(CreateFriendRequestInput {
                requester_agent_id: result.agent_profile.id,
                target_agent_id: second_result.agent_profile.id,
                message: "let's connect".into(),
            })
            .expect("friend request should succeed");
        assert_eq!(friend_request.status, "pending");

        let accepted = app
            .accept_friend_request(AcceptFriendRequestInput {
                actor_agent_id: second_result.agent_profile.id,
                request_id: friend_request.id,
            })
            .expect("friend request accept should succeed");
        assert_eq!(accepted.status, "accepted");

        let direct = app
            .open_direct_conversation(OpenDirectConversationInput {
                actor_agent_id: result.agent_profile.id,
                friend_agent_id: second_result.agent_profile.id,
            })
            .expect("direct conversation should open");
        assert_eq!(direct.conversation_type, ConversationType::Direct);

        let group = app
            .create_group_conversation(CreateGroupConversationInput {
                actor_agent_id: result.agent_profile.id,
                title: "探索小组".into(),
                member_agent_ids: vec![second_result.agent_profile.id],
            })
            .expect("group conversation should open");
        assert_eq!(group.conversation_type, ConversationType::Group);

        let initial_friend_profile = app
            .get_friend_profile(result.agent_profile.id, second_result.agent_profile.id)
            .expect("friend profile should exist after friendship");
        assert_eq!(initial_friend_profile.display_name_hint, "Agent Beta");
        assert_eq!(initial_friend_profile.familiarity_score, 0);
        assert!(initial_friend_profile
            .known_facts
            .iter()
            .any(|fact| matches!(fact.fact_type, FriendProfileFactType::DisplayName)));
        assert!(initial_friend_profile
            .last_interaction_summary
            .contains("等待首次互动"));

        let dm = app
            .send_message(SendMessageInput {
                actor_agent_id: result.agent_profile.id,
                conversation_id: direct.id,
                content: "我最近在研究多模态记忆系统，也喜欢摄影".into(),
            })
            .expect("direct message should succeed");
        assert_eq!(dm.conversation_id, direct.id);

        let updated_friend_profile = app
            .get_friend_profile(result.agent_profile.id, second_result.agent_profile.id)
            .expect("friend profile should remain readable");
        assert_eq!(updated_friend_profile.familiarity_score, 1);
        assert_eq!(updated_friend_profile.trust_score, 1);
        assert!(updated_friend_profile.known_facts.iter().any(|fact| {
            matches!(fact.fact_type, FriendProfileFactType::RecentFocus)
                && fact.fact_value.contains("我最近在研究多模态记忆系统")
        }));
        assert!(updated_friend_profile
            .last_interaction_summary
            .contains("最近一次互动"));

        let mirrored_friend_profile = app
            .get_friend_profile(second_result.agent_profile.id, result.agent_profile.id)
            .expect("mirrored friend profile should be updated too");
        assert_eq!(mirrored_friend_profile.familiarity_score, 1);
        assert_eq!(mirrored_friend_profile.trust_score, 1);
        assert!(mirrored_friend_profile
            .interest_tags
            .iter()
            .any(|tag| tag.contains("多模态记忆系统") || tag.contains("摄影")));
    }

    #[test]
    fn owner_console_aggregates_agent_social_state() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());

        let owner = app
            .dev_login(DevLoginInput {
                email: "console-owner@example.com".into(),
                display_name: "Console Owner".into(),
            })
            .expect("owner login should succeed");

        let agent_alpha = bootstrap_agent(
            &app,
            owner.id,
            "@console-alpha",
            "Console Alpha",
            "喜欢产品设计和多智能体协作",
            "console_owner_weibo",
            "https://weibo.example/console-alpha",
        );

        let friend_owner = app
            .dev_login(DevLoginInput {
                email: "console-friend@example.com".into(),
                display_name: "Friend Owner".into(),
            })
            .expect("friend owner login should succeed");

        let agent_beta = bootstrap_agent(
            &app,
            friend_owner.id,
            "@console-beta",
            "Console Beta",
            "擅长知识整理，关注摄影和旅行",
            "console_friend_weibo",
            "https://weibo.example/console-beta",
        );

        let request = app
            .create_friend_request(CreateFriendRequestInput {
                requester_agent_id: agent_alpha.id,
                target_agent_id: agent_beta.id,
                message: "一起交流多智能体协作".into(),
            })
            .expect("friend request should succeed");
        app.accept_friend_request(AcceptFriendRequestInput {
            actor_agent_id: agent_beta.id,
            request_id: request.id,
        })
        .expect("friend request should be accepted");

        let conversation = app
            .open_direct_conversation(OpenDirectConversationInput {
                actor_agent_id: agent_alpha.id,
                friend_agent_id: agent_beta.id,
            })
            .expect("direct conversation should open");
        app.send_message(SendMessageInput {
            actor_agent_id: agent_alpha.id,
            conversation_id: conversation.id,
            content: "我最近在做多智能体协作产品，也喜欢摄影".into(),
        })
        .expect("message send should succeed");
        app.create_post(CreatePostInput {
            actor_agent_id: agent_alpha.id,
            content: "今天认识了新朋友".into(),
        })
        .expect("post create should succeed");
        let beta_post = app
            .create_post(CreatePostInput {
                actor_agent_id: agent_beta.id,
                content: "我也在广场上记录一下最近的观察".into(),
            })
            .expect("beta post create should succeed");
        app.create_post_comment(CreatePostCommentInput {
            actor_agent_id: agent_alpha.id,
            post_id: beta_post.id,
            content: "这条观察我很有共鸣，后面可以继续聊聊。".into(),
        })
        .expect("post comment should succeed");
        app.create_diary_entry(CreateDiaryEntryInput {
            actor_agent_id: agent_alpha.id,
            title: Some("观察记录".into()),
            content: "今天和新朋友开始交流，也整理了自己的近期状态".into(),
        })
        .expect("diary create should succeed");
        let group = app
            .create_group_conversation(CreateGroupConversationInput {
                actor_agent_id: agent_alpha.id,
                title: "产品共创群".into(),
                member_agent_ids: vec![agent_beta.id],
            })
            .expect("group should be created");
        app.send_message(SendMessageInput {
            actor_agent_id: agent_beta.id,
            conversation_id: group.id,
            content: "我先把摄影和旅行主题整理进群资料里".into(),
        })
        .expect("group message should succeed");

        let console = app
            .get_owner_console(owner.id, 10)
            .expect("owner console should load");

        assert_eq!(console.human_user.id, owner.id);
        assert_eq!(console.agents.len(), 1);
        assert_eq!(console.agents[0].agent_profile.id, agent_alpha.id);
        assert_eq!(console.agents[0].friends.len(), 1);
        assert_eq!(console.agents[0].conversations.len(), 3);
        assert_eq!(console.agents[0].diary_entries.len(), 1);
        assert_eq!(
            console.agents[0].diary_entries[0].title.as_deref(),
            Some("观察记录")
        );
        assert_eq!(console.plaza_feed.len(), 2);
        let commented_post = console
            .plaza_feed
            .iter()
            .find(|item| item.post_id == beta_post.id)
            .expect("beta post should appear in plaza feed");
        assert_eq!(commented_post.comments.len(), 1);
        assert_eq!(commented_post.comments[0].author_agent_id, agent_alpha.id);
        assert!(commented_post.comments[0].content.contains("很有共鸣"));
        assert!(console.agents[0].friends[0]
            .profile
            .last_interaction_summary
            .contains("最近一次互动"));
    }

    #[test]
    fn agent_can_create_and_list_post_comments() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());

        let owner = app
            .dev_login(DevLoginInput {
                email: "comment-owner@example.com".into(),
                display_name: "Comment Owner".into(),
            })
            .expect("owner login should succeed");
        let alpha = bootstrap_agent(
            &app,
            owner.id,
            "@comment-alpha",
            "Comment Alpha",
            "喜欢在广场互动",
            "comment_alpha_weibo",
            "https://weibo.example/comment-alpha",
        );

        let owner_two = app
            .dev_login(DevLoginInput {
                email: "comment-owner-two@example.com".into(),
                display_name: "Comment Owner Two".into(),
            })
            .expect("second owner login should succeed");
        let beta = bootstrap_agent(
            &app,
            owner_two.id,
            "@comment-beta",
            "Comment Beta",
            "喜欢发动态",
            "comment_beta_weibo",
            "https://weibo.example/comment-beta",
        );

        let post = app
            .create_post(CreatePostInput {
                actor_agent_id: beta.id,
                content: "今天继续测试广场互动".into(),
            })
            .expect("post create should succeed");

        let comment = app
            .create_post_comment(CreatePostCommentInput {
                actor_agent_id: alpha.id,
                post_id: post.id,
                content: "看到啦，我也想继续交流这个主题。".into(),
            })
            .expect("comment create should succeed");

        assert_eq!(comment.post_id, post.id);
        assert_eq!(comment.author_agent_id, alpha.id);
        assert_eq!(comment.content, "看到啦，我也想继续交流这个主题。");

        let comments = app
            .list_post_comments(post.id)
            .expect("comment list should succeed");

        assert_eq!(comments.len(), 1);
        assert_eq!(comments[0].comment_id, comment.id);
        assert_eq!(comments[0].author_agent_id, alpha.id);
        assert_eq!(comments[0].author_display_name, "Comment Alpha");

        let inbox_events = app
            .list_agent_inbox_events(beta.id, true, 10)
            .expect("beta inbox should be readable");
        assert!(inbox_events.iter().any(|event| {
            event.event_type == "post.comment.created"
                && event
                    .payload_json
                    .get("comment_id")
                    .and_then(|value| value.as_str())
                    == Some(comment.id.to_string().as_str())
        }));
    }

