    #[test]
    fn runtime_secret_reference_health_check_and_rotation_never_return_secret_values() {
        let app = PlatformApp::with_runtime_model_provider(
            MemoryPlatformRepository::default(),
            Arc::new(StaticRuntimeModelProvider::default()) as Arc<dyn AgentRuntimeModelProvider>,
        );
        let owner = app
            .dev_login(DevLoginInput {
                email: "runtime-secret-owner@example.com".into(),
                display_name: "Runtime Secret Owner".into(),
            })
            .expect("owner login should succeed");
        let company = app
            .create_company(CreateCompanyInput {
                human_user_id: owner.id,
                name: "Runtime Secret Company".into(),
                slug: Some("runtime-secret-company".into()),
                description: None,
            })
            .expect("company creation should succeed");
        let agent = app
            .create_company_agent(CreateCompanyAgentInput {
                human_user_id: owner.id,
                company_id: company.company.id,
                display_name: "Runtime Secret Agent".into(),
                handle: "runtime-secret-agent".into(),
                persona: "验证 Secret 引用健康检查与轮换".into(),
                org_unit_id: Some(company.org_units[0].id),
                job_title: None,
                role_key: None,
                reports_to_membership_id: None,
            })
            .expect("agent creation should succeed");
        app.upsert_agent_runtime(UpsertAgentRuntimeInput {
            human_user_id: owner.id,
            company_id: company.company.id,
            agent_id: agent.agent_profile.id,
            interval_seconds: None,
            max_events: None,
            daily_run_budget: None,
            daily_action_budget: None,
            daily_model_input_token_budget: None,
            daily_model_output_token_budget: None,
            daily_model_cost_budget_microusd: None,
            model_input_price_microusd_per_million_tokens: None,
            model_output_price_microusd_per_million_tokens: None,
            daily_approval_request_budget: None,
            executor_kind: Some(AGENT_RUNTIME_EXECUTOR_RULES_V1.into()),
            company_message_policy: None,
            auto_start_assigned_tasks: None,
            auto_announce_project_membership: None,
            context_max_projects: None,
            context_max_conversations: None,
            context_max_inbox_events: None,
            system_prompt: None,
            model_name: None,
            model_provider: None,
            provider_secret_ref: Some("env:TEST_MODEL_KEY".into()),
            allowed_model_actions: None,
            approval_required_model_actions: None,
            approval_request_ttl_minutes: None,
            model_max_output_tokens: None,
            model_timeout_seconds: None,
            model_max_retries: None,
            fallback_to_rules_v1: None,
        })
        .expect("runtime should be configured");

        let health = app
            .check_agent_runtime_secret_reference(CheckAgentRuntimeSecretInput {
                human_user_id: owner.id,
                company_id: company.company.id,
                agent_id: agent.agent_profile.id,
            })
            .expect("configured reference should be healthy");
        assert_eq!(health.status, "healthy");
        assert_eq!(health.reference_scheme, "env");
        assert!(!serde_json::to_string(&health)
            .expect("health should serialize")
            .contains("TEST_MODEL_KEY"));

        let rotated = app
            .rotate_agent_runtime_secret_reference(RotateAgentRuntimeSecretReferenceInput {
                human_user_id: owner.id,
                company_id: company.company.id,
                agent_id: agent.agent_profile.id,
                provider_secret_ref: "secret:ROTATED_MODEL_KEY".into(),
            })
            .expect("healthy replacement reference should rotate");
        assert_eq!(rotated.secret_health.reference_scheme, "secret");
        assert_eq!(rotated.secret_health.status, "healthy");
        assert!(!serde_json::to_string(&rotated)
            .expect("rotation health should serialize")
            .contains("ROTATED_MODEL_KEY"));
        assert_eq!(
            app.get_agent_runtime_for_human(owner.id, company.company.id, agent.agent_profile.id)
                .expect("rotated runtime should remain readable")
                .config
                .provider_secret_ref
                .as_deref(),
            Some("secret:ROTATED_MODEL_KEY")
        );

        assert!(matches!(
            app.rotate_agent_runtime_secret_reference(RotateAgentRuntimeSecretReferenceInput {
                human_user_id: owner.id,
                company_id: company.company.id,
                agent_id: agent.agent_profile.id,
                provider_secret_ref: "secret:MISSING_MODEL_KEY".into(),
            }),
            Err(AppError::Validation(_))
        ));
        assert_eq!(
            app.get_agent_runtime_for_human(owner.id, company.company.id, agent.agent_profile.id)
                .expect("failed rotation must preserve the old reference")
                .config
                .provider_secret_ref
                .as_deref(),
            Some("secret:ROTATED_MODEL_KEY")
        );
        assert!(matches!(
            app.rotate_agent_runtime_secret_reference(RotateAgentRuntimeSecretReferenceInput {
                human_user_id: owner.id,
                company_id: company.company.id,
                agent_id: agent.agent_profile.id,
                provider_secret_ref: "sk-plaintext-secret".into(),
            }),
            Err(AppError::Validation(_))
        ));
    }

