    #[test]
    fn conversation_message_pages_use_stable_exclusive_cursors() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());
        let owner = app
            .dev_login(DevLoginInput {
                email: "message-page-owner@example.com".into(),
                display_name: "Message Page Owner".into(),
            })
            .expect("owner login should succeed");
        let alpha = bootstrap_agent(
            &app,
            owner.id,
            "@message-page-alpha",
            "Message Page Alpha",
            "测试稳定消息游标",
            "message_page_alpha_weibo",
            "https://weibo.example/message-page-alpha",
        );
        let friend_owner = app
            .dev_login(DevLoginInput {
                email: "message-page-friend@example.com".into(),
                display_name: "Message Page Friend".into(),
            })
            .expect("friend owner login should succeed");
        let beta = bootstrap_agent(
            &app,
            friend_owner.id,
            "@message-page-beta",
            "Message Page Beta",
            "参与消息分页测试",
            "message_page_beta_weibo",
            "https://weibo.example/message-page-beta",
        );
        let request = app
            .create_friend_request(CreateFriendRequestInput {
                requester_agent_id: alpha.id,
                target_agent_id: beta.id,
                message: "测试消息翻页".into(),
            })
            .expect("friend request should succeed");
        app.accept_friend_request(AcceptFriendRequestInput {
            actor_agent_id: beta.id,
            request_id: request.id,
        })
        .expect("friend request should be accepted");
        let direct = app
            .open_direct_conversation(OpenDirectConversationInput {
                actor_agent_id: alpha.id,
                friend_agent_id: beta.id,
            })
            .expect("direct conversation should open");
        let mut sent = Vec::new();
        for index in 1..=5 {
            sent.push(
                app.send_message(SendMessageInput {
                    actor_agent_id: if index % 2 == 0 { beta.id } else { alpha.id },
                    conversation_id: direct.id,
                    content: format!("分页消息 {index}"),
                })
                .expect("message should be sent"),
            );
        }
        sent.sort_by(|left, right| {
            left.created_at
                .cmp(&right.created_at)
                .then_with(|| left.id.cmp(&right.id))
        });

        let latest = app
            .get_agent_conversation_message_page(alpha.id, direct.id, None, 2)
            .expect("latest page should load");
        assert_eq!(
            latest
                .messages
                .iter()
                .map(|message| message.id)
                .collect::<Vec<_>>(),
            sent[3..5]
                .iter()
                .map(|message| message.id)
                .collect::<Vec<_>>()
        );
        assert!(latest.has_more);
        assert_eq!(latest.next_cursor, Some(sent[3].id));

        let middle = app
            .get_agent_conversation_message_page(alpha.id, direct.id, latest.next_cursor, 2)
            .expect("middle page should load");
        assert_eq!(
            middle
                .messages
                .iter()
                .map(|message| message.id)
                .collect::<Vec<_>>(),
            sent[1..3]
                .iter()
                .map(|message| message.id)
                .collect::<Vec<_>>()
        );
        assert!(middle.has_more);
        assert_eq!(middle.next_cursor, Some(sent[1].id));

        let oldest = app
            .get_owned_conversation_message_page(owner.id, direct.id, middle.next_cursor, 2)
            .expect("owner should load the oldest page");
        assert_eq!(oldest.messages.len(), 1);
        assert_eq!(oldest.messages[0].id, sent[0].id);
        assert!(!oldest.has_more);
        assert!(oldest.next_cursor.is_none());

        assert!(matches!(
            app.get_agent_conversation_message_page(alpha.id, direct.id, Some(Uuid::new_v4()), 2),
            Err(AppError::Validation(_))
        ));
    }

