    #[test]
    fn owner_can_freeze_and_unfreeze_only_owned_agent() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());

        let owner = app
            .dev_login(DevLoginInput {
                email: "freeze-owner@example.com".into(),
                display_name: "Freeze Owner".into(),
            })
            .expect("owner login should succeed");
        let owned_agent = bootstrap_agent(
            &app,
            owner.id,
            "@freeze-alpha",
            "Freeze Alpha",
            "喜欢协作和观察行为日志",
            "freeze_owner_weibo",
            "https://weibo.example/freeze-alpha",
        );

        let stranger = app
            .dev_login(DevLoginInput {
                email: "freeze-stranger@example.com".into(),
                display_name: "Freeze Stranger".into(),
            })
            .expect("stranger login should succeed");

        let frozen = app
            .freeze_owned_agent(owner.id, owned_agent.id)
            .expect("owner should be able to freeze owned agent");
        assert!(matches!(frozen.status, AgentStatus::Frozen));

        let console_after_freeze = app
            .get_owner_console(owner.id, 10)
            .expect("owner console should load after freeze");
        assert!(console_after_freeze.agents[0]
            .recent_actions
            .iter()
            .any(|action| {
                action.action_type == "owner.freeze"
                    && matches!(action.status, AgentActionStatus::Success)
            }));

        let unfrozen = app
            .unfreeze_owned_agent(owner.id, owned_agent.id)
            .expect("owner should be able to unfreeze owned agent");
        assert!(matches!(unfrozen.status, AgentStatus::Active));

        let console_after_unfreeze = app
            .get_owner_console(owner.id, 10)
            .expect("owner console should load after unfreeze");
        assert!(console_after_unfreeze.agents[0]
            .recent_actions
            .iter()
            .any(|action| {
                action.action_type == "owner.unfreeze"
                    && matches!(action.status, AgentActionStatus::Success)
            }));

        let unauthorized = app
            .freeze_owned_agent(stranger.id, owned_agent.id)
            .expect_err("stranger should not freeze someone else's agent");
        assert!(matches!(unauthorized, AppError::Unauthorized(_)));
    }

