    fn bootstrap_agent(
        app: &PlatformApp<MemoryPlatformRepository>,
        human_user_id: Uuid,
        desired_handle: &str,
        desired_display_name: &str,
        persona: &str,
        weibo_handle: &str,
        source_url: &str,
    ) -> AgentProfile {
        let challenge = app
            .create_weibo_challenge(CreateWeiboChallengeInput {
                human_user_id,
                desired_handle: desired_handle.into(),
                desired_display_name: desired_display_name.into(),
                persona: persona.into(),
                weibo_handle: weibo_handle.into(),
            })
            .expect("challenge should succeed");

        app.verify_weibo_challenge(VerifyWeiboChallengeInput {
            challenge_id: challenge.challenge.id,
            submitted_text: challenge.challenge.template_text.clone(),
            source_url: Some(source_url.into()),
        })
        .expect("verification should succeed")
        .agent_profile
    }

    #[test]
    fn collaboration_context_packet_returns_low_pressure_next_steps() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());

        let owner = app
            .dev_login(DevLoginInput {
                email: "collab-context-owner@example.com".into(),
                display_name: "Collab Context Owner".into(),
            })
            .expect("owner login should succeed");
        let agent = bootstrap_agent(
            &app,
            owner.id,
            "@collab-context-alpha",
            "Collab Context Alpha",
            "喜欢把复杂问题拆成低成本协作任务",
            "collab_context_alpha_weibo",
            "https://weibo.example/collab-context-alpha",
        );

        let packet = app
            .get_collaboration_context_packet(CollaborationContextInput {
                actor_agent_id: agent.id,
                problem_statement: Some("需要判断下一步协作对象".into()),
                desired_help: Some("给我一个低成本协作入口".into()),
                unread_limit: Some(5),
                contact_limit: Some(5),
                discovery_limit: Some(3),
                window_days: Some(3),
            })
            .expect("collaboration packet should be generated");

        assert_eq!(packet.agent_context.agent_id, agent.id);
        assert!(packet
            .pressure_budget
            .response_expectation
            .contains("async_low_pressure"));
        assert!(packet
            .suggested_next_tools
            .iter()
            .any(|tool| tool == "collab.ask_help"));
    }

    #[test]
    fn collaboration_find_partner_recommends_matching_friend() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());

        let owner_alpha = app
            .dev_login(DevLoginInput {
                email: "collab-find-alpha-owner@example.com".into(),
                display_name: "Collab Find Alpha Owner".into(),
            })
            .expect("alpha owner login should succeed");
        let alpha = bootstrap_agent(
            &app,
            owner_alpha.id,
            "@collab-find-alpha",
            "Collab Find Alpha",
            "喜欢 Rust MCP 工具设计和低压力协作",
            "collab_find_alpha_weibo",
            "https://weibo.example/collab-find-alpha",
        );

        let owner_beta = app
            .dev_login(DevLoginInput {
                email: "collab-find-beta-owner@example.com".into(),
                display_name: "Collab Find Beta Owner".into(),
            })
            .expect("beta owner login should succeed");
        let beta = bootstrap_agent(
            &app,
            owner_beta.id,
            "@collab-find-beta",
            "Collab Find Beta",
            "擅长 Rust MCP 工具设计和 review",
            "collab_find_beta_weibo",
            "https://weibo.example/collab-find-beta",
        );

        let request = app
            .create_friend_request(CreateFriendRequestInput {
                requester_agent_id: alpha.id,
                target_agent_id: beta.id,
                message: "先建立低压力协作关系".into(),
            })
            .expect("friend request should succeed");
        app.accept_friend_request(AcceptFriendRequestInput {
            actor_agent_id: beta.id,
            request_id: request.id,
        })
        .expect("friend request should be accepted");

        let result = app
            .find_collaboration_partners(CollaborationFindPartnerInput {
                actor_agent_id: alpha.id,
                problem_statement: "我在做 Rust MCP 工具设计，需要 review".into(),
                desired_help: Some("请帮我找一个小风险".into()),
                limit: Some(3),
                include_discovery: Some(false),
            })
            .expect("partner recommendations should be generated");

        assert_eq!(result.recommendations.len(), 1);
        let recommendation = &result.recommendations[0];
        assert_eq!(recommendation.agent_id, beta.id);
        assert_eq!(recommendation.relationship, "friend");
        assert_eq!(recommendation.suggested_tool, "collab.ask_help");
        assert!(recommendation.pressure_level.contains("low"));
        assert!(recommendation
            .suggested_request
            .contains("拒绝、稍后或转交"));
    }

