    #[test]
    fn problem_workspace_progress_can_be_appended_by_participant() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());

        let owner = app
            .dev_login(DevLoginInput {
                email: "workspace-progress-owner@example.com".into(),
                display_name: "Workspace Progress Owner".into(),
            })
            .expect("owner login should succeed");
        let agent = bootstrap_agent(
            &app,
            owner.id,
            "@workspace-progress-agent",
            "Workspace Progress Agent",
            "负责记录协作进展",
            "workspace_progress_weibo",
            "https://weibo.example/workspace-progress",
        );

        let workspace = app
            .create_problem_workspace(CreateProblemWorkspaceInput {
                actor_agent_id: agent.id,
                title: Some("进展记录测试".into()),
                problem_statement: "确认 workspace 可以记录低压力推进状态".into(),
                participant_agent_ids: None,
                conversation_id: None,
                pressure_level: None,
                summary_text: None,
            })
            .expect("workspace should be created");

        let result = app
            .append_problem_workspace_progress(AppendProblemWorkspaceProgressInput {
                actor_agent_id: agent.id,
                workspace_id: workspace.id,
                record_type: Some("decision".into()),
                content: "先做追加记录，不自动通知参与者。".into(),
                artifact_ref: Some("docs:workspace-progress-v0".into()),
                task_status: None,
                assignee_agent_id: None,
                due_at: None,
            })
            .expect("progress record should append");

        assert_eq!(result.progress_record.workspace_id, workspace.id);
        assert_eq!(result.progress_record.author_agent_id, agent.id);
        assert_eq!(result.progress_record.record_type, "decision");
        assert!(result.progress_record.content.contains("不自动通知"));
        assert_eq!(
            result.progress_record.artifact_ref.as_deref(),
            Some("docs:workspace-progress-v0")
        );
        assert_eq!(result.workspace.progress_records.len(), 1);
        assert_eq!(
            result.workspace.progress_records[0].id,
            result.progress_record.id
        );
        assert!(result
            .workspace
            .suggested_next_tools
            .iter()
            .any(|tool| tool == "workspace.progress.add"));

        let updated = app
            .get_problem_workspace(agent.id, workspace.id)
            .expect("workspace should remain readable");
        assert_eq!(updated.progress_records.len(), 1);
        assert_eq!(updated.progress_overview.decisions.len(), 1);
        assert!(updated.updated_at >= workspace.updated_at);

        app.append_problem_workspace_progress(AppendProblemWorkspaceProgressInput {
            actor_agent_id: agent.id,
            workspace_id: workspace.id,
            record_type: Some("task".into()),
            content: "补一个结构化 overview，让 agent 少翻历史。".into(),
            artifact_ref: None,
            task_status: None,
            assignee_agent_id: None,
            due_at: None,
        })
        .expect("task record should append");
        app.append_problem_workspace_progress(AppendProblemWorkspaceProgressInput {
            actor_agent_id: agent.id,
            workspace_id: workspace.id,
            record_type: Some("artifact".into()),
            content: "MCP 文档已经补充 workspace.progress.add。".into(),
            artifact_ref: Some("MCP_TOOLS_REFERENCE.md".into()),
            task_status: None,
            assignee_agent_id: None,
            due_at: None,
        })
        .expect("artifact record should append");
        app.append_problem_workspace_progress(AppendProblemWorkspaceProgressInput {
            actor_agent_id: agent.id,
            workspace_id: workspace.id,
            record_type: Some("blocker".into()),
            content: "还缺显式邀请流程，需要后续设计。".into(),
            artifact_ref: None,
            task_status: None,
            assignee_agent_id: None,
            due_at: None,
        })
        .expect("blocker record should append");

        let overview = app
            .get_problem_workspace_progress_overview(agent.id, workspace.id)
            .expect("progress overview should be readable");
        assert_eq!(overview.recent_record_count, 4);
        assert_eq!(overview.decisions.len(), 1);
        assert_eq!(overview.tasks.len(), 1);
        assert_eq!(overview.artifacts.len(), 1);
        assert_eq!(overview.blockers.len(), 1);
        assert!(overview
            .next_focus
            .as_deref()
            .unwrap_or_default()
            .contains("阻塞"));
        assert!(overview
            .suggested_next_tools
            .iter()
            .any(|tool| tool == "collab.find_partner"));
    }

    #[test]
    fn problem_workspace_task_status_can_be_tracked_and_updated() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());

        let owner = app
            .dev_login(DevLoginInput {
                email: "workspace-task-owner@example.com".into(),
                display_name: "Workspace Task Owner".into(),
            })
            .expect("owner login should succeed");
        let alpha = bootstrap_agent(
            &app,
            owner.id,
            "@workspace-task-alpha",
            "Workspace Task Alpha",
            "负责拆任务",
            "workspace_task_alpha_weibo",
            "https://weibo.example/workspace-task-alpha",
        );
        let beta = bootstrap_agent(
            &app,
            owner.id,
            "@workspace-task-beta",
            "Workspace Task Beta",
            "可以接收转交任务",
            "workspace_task_beta_weibo",
            "https://weibo.example/workspace-task-beta",
        );

        let request = app
            .create_friend_request(CreateFriendRequestInput {
                requester_agent_id: alpha.id,
                target_agent_id: beta.id,
                message: "先成为好友，再测试结构化任务".into(),
            })
            .expect("friend request should succeed");
        app.accept_friend_request(AcceptFriendRequestInput {
            actor_agent_id: beta.id,
            request_id: request.id,
        })
        .expect("friend request should be accepted");

        let workspace = app
            .create_problem_workspace(CreateProblemWorkspaceInput {
                actor_agent_id: alpha.id,
                title: Some("结构化任务状态测试".into()),
                problem_statement: "验证 workspace task 可以 open / delegated / done".into(),
                participant_agent_ids: Some(vec![beta.id]),
                conversation_id: None,
                pressure_level: None,
                summary_text: None,
            })
            .expect("workspace should be created");
        let due_at = now_utc() + chrono::Duration::days(1);

        let created = app
            .append_problem_workspace_progress(AppendProblemWorkspaceProgressInput {
                actor_agent_id: alpha.id,
                workspace_id: workspace.id,
                record_type: Some("task".into()),
                content: "补齐 workspace task.update 工具和文档。".into(),
                artifact_ref: None,
                task_status: Some("todo".into()),
                assignee_agent_id: Some(alpha.id),
                due_at: Some(due_at),
            })
            .expect("task should be created");
        assert_eq!(created.progress_record.task_status.as_deref(), Some("open"));
        assert_eq!(created.progress_record.assignee_agent_id, Some(alpha.id));
        assert_eq!(
            created.progress_record.assignee_display_name.as_deref(),
            Some("Workspace Task Alpha")
        );
        assert_eq!(created.progress_record.due_at, Some(due_at));

        let overview = app
            .get_problem_workspace_progress_overview(alpha.id, workspace.id)
            .expect("overview should be readable");
        assert_eq!(overview.tasks.len(), 1);
        assert_eq!(overview.open_tasks.len(), 1);
        assert!(overview.delegated_tasks.is_empty());
        assert!(overview.done_tasks.is_empty());
        assert!(overview
            .suggested_next_tools
            .iter()
            .any(|tool| tool == "workspace.task.update"));

        let delegated = app
            .update_problem_workspace_task(UpdateProblemWorkspaceTaskInput {
                actor_agent_id: alpha.id,
                task_record_id: created.progress_record.id,
                content: None,
                task_status: Some("delegated".into()),
                assignee_agent_id: Some(beta.id),
                due_at: None,
            })
            .expect("task should be delegated");
        assert_eq!(delegated.task.task_status.as_deref(), Some("delegated"));
        assert_eq!(delegated.task.assignee_agent_id, Some(beta.id));
        assert_eq!(
            delegated.task.assignee_display_name.as_deref(),
            Some("Workspace Task Beta")
        );
        assert_eq!(
            delegated.workspace.progress_overview.delegated_tasks.len(),
            1
        );
        assert!(delegated.workspace.progress_overview.open_tasks.is_empty());

        let done = app
            .update_problem_workspace_task(UpdateProblemWorkspaceTaskInput {
                actor_agent_id: beta.id,
                task_record_id: created.progress_record.id,
                content: None,
                task_status: Some("complete".into()),
                assignee_agent_id: None,
                due_at: None,
            })
            .expect("participant should mark task done");
        assert_eq!(done.task.task_status.as_deref(), Some("done"));
        assert_eq!(done.workspace.progress_overview.done_tasks.len(), 1);
        assert!(done.workspace.progress_overview.open_tasks.is_empty());
        assert!(done.workspace.progress_overview.delegated_tasks.is_empty());
    }

    #[test]
    fn problem_workspace_result_write_resolves_and_records_summary() {
        let app = PlatformApp::new(MemoryPlatformRepository::default());

        let owner = app
            .dev_login(DevLoginInput {
                email: "workspace-result-owner@example.com".into(),
                display_name: "Workspace Result Owner".into(),
            })
            .expect("owner login should succeed");
        let alpha = bootstrap_agent(
            &app,
            owner.id,
            "@workspace-result-alpha",
            "Workspace Result Alpha",
            "负责发起结果回写",
            "workspace_result_alpha_weibo",
            "https://weibo.example/workspace-result-alpha",
        );
        let beta = bootstrap_agent(
            &app,
            owner.id,
            "@workspace-result-beta",
            "Workspace Result Beta",
            "可以帮忙收束协作结果",
            "workspace_result_beta_weibo",
            "https://weibo.example/workspace-result-beta",
        );

        let request = app
            .create_friend_request(CreateFriendRequestInput {
                requester_agent_id: alpha.id,
                target_agent_id: beta.id,
                message: "先成为好友，再测试结果回写".into(),
            })
            .expect("friend request should succeed");
        app.accept_friend_request(AcceptFriendRequestInput {
            actor_agent_id: beta.id,
            request_id: request.id,
        })
        .expect("friend request should be accepted");

        let workspace = app
            .create_problem_workspace(CreateProblemWorkspaceInput {
                actor_agent_id: alpha.id,
                title: Some("结果回写测试".into()),
                problem_statement: "验证 workspace 可以写入可复用最终摘要".into(),
                participant_agent_ids: Some(vec![beta.id]),
                conversation_id: None,
                pressure_level: None,
                summary_text: None,
            })
            .expect("workspace should be created");

        let result_summary =
            "结论：保留低压力邀请和任务状态，下一步把结果摘要暴露给后续 agent 复用。";
        let result = app
            .write_problem_workspace_result(WriteProblemWorkspaceResultInput {
                actor_agent_id: beta.id,
                workspace_id: workspace.id,
                result_summary: result_summary.into(),
                artifact_ref: Some("AGENT_COLLABORATION_ROADMAP.md".into()),
                close_workspace: None,
                result_status: None,
            })
            .expect("participant should write workspace result");

        assert_eq!(result.workspace.status, "resolved");
        assert_eq!(
            result.workspace.summary_text.as_deref(),
            Some(result_summary)
        );
        assert_eq!(result.result_record.record_type, "summary");
        assert_eq!(result.result_record.content, result_summary);
        assert_eq!(
            result.result_record.artifact_ref.as_deref(),
            Some("AGENT_COLLABORATION_ROADMAP.md")
        );
        assert_eq!(result.workspace.progress_overview.summaries.len(), 1);
        assert!(result
            .workspace
            .suggested_next_tools
            .iter()
            .any(|tool| tool == "collab.loop.close"));

        let reopened = app
            .write_problem_workspace_result(WriteProblemWorkspaceResultInput {
                actor_agent_id: alpha.id,
                workspace_id: workspace.id,
                result_summary: "阶段性复盘：先保留 workspace，继续观察后续协作体验。".into(),
                artifact_ref: None,
                close_workspace: Some(false),
                result_status: Some("open".into()),
            })
            .expect("owner should write another result without closing");
        assert_eq!(reopened.workspace.status, "open");
        assert!(reopened.workspace.progress_overview.summaries.len() >= 2);
    }

